window.__D("text/maamarei-admur-hazaken/c014",{"p":[[2101000317,"בבינה וי\"ו בז\"א ה' אחרונה במל' ואפי'<sup data-n=\"2043\">99</sup> בחי' קודם ז\"א לבחי' המל' דהיינו וי\"ו קודם לה\"א כי בחי' המל' מקבלת מבחי' ז\"א וזהו כמו עכשיו בזמן הגלות דמ\"ה מברר ב\"ן וכמ\"ש והוא<sup data-n=\"2044\">100</sup> ימשול בך כו' וע\"כ פ' שמע קודם לוהי' א\"ש כו' (והיינו כמאמר<sup data-n=\"2045\">101</sup> ריב\"ק במשנה למה קדמה פ' שמע לוהי' א\"ש כדי שיקבל עול מ\"ש תחלה ואח\"כ עול מצות ועול מ\"ש הוא ע\"י התורה דאורייתא מחכמה נפקת (וכמו שהקדים מצות ת\"ת קודם למצות בפ' ראשונה כמ\"ש ושננתם ואח\"כ וקשרתם לפי שמונה הסדר מלמעלה למטה שהתורה גבוה מן המצות (ולא כדלעיל דמונה הסדר מלמטה למעלה הנמוך תחלה כו'), אבל ענין התפילין דר\"ת היינו הויות להדדי שהוא והי' כי יביאך והי' א\"ש באמצע וקדש מימין ושמע משמאל כידוע וא\"כ פ' והי' א\"ש קודם לפ' שמע לפי שבחי' המל' שבפ' והי' א\"ש למעלה מבחי' ז\"א שהוא בפ' שמע מפני שזהו כמו לעתיד דכתיב אשת חיל עט\"ב דשם ב\"ן דמל' תתעלה למעלה מבחי' ז\"א וכנ\"ל<sup data-n=\"2046\">102</sup> המצות גבוהים מת\"ת לעתיד והוא ענין פ' ראשונה כנ\"ל ונמצא בחי' תפילין דר\"ת הוא כמו לעתיד לאחר עליות המל' ואז יהי' בחי' תש\"י שהיא בבחי' המל' למעלה מתש\"ר (שהוא בבחי' ז\"א כידוע) ולכך הקדים וקשרתם לאות על ידך ואח\"כ לטוטפות כו' דסובל ב' הדיעות מלמטה למעלה שמזכיר הנמוך תחלה והיינו כמו עכשיו שהמל' מקבלת מז\"א וגם מלמעלה למטה שמזכיר העליון תחלה היינו כמו לעתיד שהמלכות תהי' עט\"ב כנ\"ל.\n<b>אך</b> בענין תורה ומצות שהקדים בפ' ראשונה תורה למצות ובפ' שני' הקדים מצות לתורה זה א\"א<sup data-n=\"2047\">103</sup> כ\"א שפ' ראשונה מדבר לעתיד ומזכיר הנמוך תחלה כנ\"ל ופ' שני' מדבר עכשיו ומזכיר הנמוך תחלה כנ\"ל, אבל זה א\"א לומר דפ' ראשונה ובפ' שני' הקדים מצות לתורה זה א\"א מדברים עכשיו שהמל' מקבלת מז\"א אך מה שהקדים בפ' ראשונה תורה למצות היינו מלמעלה למטה שמזכיר העליון תחלה ובפ' שני' מדבר מלמטה למעלה שמזכיר הנמוך תחלה וע\"כ הקדים מצות לתורה או ב' הפרשיות מדברים לעתיד שהמל' למעלה מז\"א אלא שבפ' הא' מזכיר הנמוך תחלה מלמטה למעלה ובפ' השני' מזכיר העליון תחלה מלמעלה למטה כו' שהרי שמע והי' א\"ש הן בחי' ז\"א ומל' וצריך שיהיו שניהם באופן א' אם מלמעלה למטה או מלמטה למעלה וא\"א לחלקם שזה יהי' עולה מלמטה למעלה וזה מלמעלה למטה, ואעפ\"י שבחי' ז\"א עיקרו מבחי' החסדים שהן בבחי' אור ישר מלמעלה למטה ובחי' המל' עיקרה מבחי' הגבורות שהן בבחי' או\"ח מלמטה למעלה זהו דוקא כשאינן מיוחדים יחד אלא צריכים להתחבר זע\"ז אבל כאן שמזכיר תורה ומצות יחד בב' הפרשיות שהוא יחוד זו\"נ ה' עם וי\"ו כנ\"ל א\"כ בהכרח ששניהם יהיו באופן א' או שניהם עולים מלמטה למעלה או שניהם יורדים מלמעלה למטה, ולפי\"ז לא יתורץ מה ששינה בסדר המוקדם והמאוחר בתורה ומצות בין פ' הא' לפ' הב' כ\"א שפ' הא'",[["2043","99","<b>ואפי' בחי' קודם ז\"א</b>: כ\"ה בכת\"י המעתיק, ואוצ\"ל: ז\"א קודם."],["2044","100","<b>והוא ימשול בך</b>: בראשית ג, טז."],["2045","101","<b>כמאמר ריב\"ק במשנה למה קדמה פ' שמע</b>: ברכות יג, א."],["2046","102","<b>וכנ\"ל</b>: כנראה חסר כאן בהכת\"י."],["2047","103","<b>דפ' ראשונה. . זה א\"א</b>: כ\"ה בהכת\"י, וניכר שחסר כאן (או שיש איזה טעות בכת\"י המעתיק)."]]],[2101000318,"מדבר לעתיד ופ' הב' מדבר עכשיו ושניהם מלמטה למעלה שמזכיר הנמוך תחלה כנ\"ל, דא\"א לומר שניהם מלמעלה למטה ועכשיו דתקשי פרשה ב', ולעתיד תקשי פ' הא', וא\"א לומר שניהם מלמטה למעלה ועכשיו דתקשי פ' הא' ולעתיד תקשי פ' ב' ודו\"ק (אך זה אפשר לומר דשניהם מלמעלה למטה שמזכיר העליון תחלה ולהיפך דפ' הא' מדבר עכשיו ופ' הב' מדבר לעתיד ודו\"ק. והמשכיל יבין היטיב וד\"ל)."],[2101000319,"<h3>ביאור על ד\"ה בגמרא רמי' כו' ולקחתי דגני</h3>\n<b></b><b>ביאור<sup data-n=\"2048\">1</sup> על התורה בגמרא רמי דשבת<sup data-n=\"2049\">2</sup>, תקס\"ט לפ\"ק</b>\n<b>הנה</b> פעם כתיב ולקחתי<sup data-n=\"2050\">3</sup> דגני ופעם כתיב ואספת דגנך ומתרץ בגמ' כאן כשעושין רצונו של מקום וכאן כשאין עושין רצונו של מקום, ומזה יובן שפרשה שני' איירי כשעושין, ובמ\"א<sup data-n=\"2051\">4</sup> מק' הגמ' כתיב ואספת דגנך שעושה המלאכה בעצמו וכתיב ועמדו זרים ורעו כו' מלאכתן נעשה ע\"י אחרים ומתרץ כאן כשעושין כו' וכאן כשאין עושין כו', ומזה יובן שפרשה שני' איירי כשאין עושין וסותרין תרתי גמרות אהדדי. והנה להבין הענין צ\"ל מקודם מהו עושין רצונו של מקום ומהו מקום, [מקום] הוא בחי' מל' דאצי' ורצון הוא רצון עליון, גם מקודם צ\"ל מהו המאריך<sup data-n=\"2052\">5</sup> באחד מאריכין כו' ומהו בחי' מאריכין משמע שיש א' באריכות וא' בקיצור מהו אריכות הא' כי מאן<sup data-n=\"2053\">6</sup> דאריך יתארך, גם מאריכין באחד הוא בחי' ד' דאחד ומאריכין בד' כדי<sup data-n=\"2054\">7</sup> שתמליכהו למעלה ולמטה ובד' סטרין, הלא הם רק בחי' מקום ויש ומה האריכות בד' דאחד, אך להבין כ\"ז צ\"ל מקודם מהו בחי' מקום וצ\"ל ענין השתלשלות, כי בחי' מקום הוא בכל מקום הן בגשמיות הן ברוחניות. כי הנה<sup data-n=\"2055\">8</sup> מקום אתי כתיב, הוא מקומו של עולם ואין העולם מקומו, הוא<sup data-n=\"2056\">9</sup> תפיס בכולא עלמין ולית",[["2048","1","<b>ביאור על התורה</b>: מאמר זה נדפס כאן ע\"פ כת\"י מעתיקים, ולא ידוע לע\"ע ע\"י מי נכתבה הנחה זו.\nמאמר זה הוא נוסח אחר (קצר) מד\"ה כתיב ולקחתי דגני הנדפס לעיל (ע' רנה וע' רסד). תוכן התחלת המאמר (ועוד איזה ענינים מהמאמר) נמצא בשינויים בס' עבודת הלוי פ' עקב ח, ג, בכותרת: כי\"ק בעת ששמע מאדמו\"ר הזקן נ\"ע, ומתחיל: ואספת דגנך."],["2049","2","<b>דשבת, תקס\"ט לפ\"ק</b>: כ\"ה בכת\"י א'. ובכת\"י ב': דשנת תקעיין לפ\"ק [וראה להלן ברשימת המאמרים שבסוף הספר אשר מאמר זה הוא משבת נחמו תקס\"ט]."],["2050","3","<b>ולקחתי דגני. . ואספת דגנך ומתרץ בגמ'</b>: הושע ב, יא. עקב יא, יד. ברכות לה, ב."],["2051","4","<b>ובמ\"א מק' הגמ'</b>: בגמ' ברכות דל\"ה שם: ת\"ר ואספת דגנך כו' בזמן שישראל עושין רצונו של מקום מלאכתן נעשית ע\"י אחרים שנא' ועמדו זרים ורעו צאנכם וגו' ובזמן שאין ישראל עושין רצונו של מקום מלאכתן נעשית ע\"י עצמן שנא' ואספת דגנך כו'. וע\"ש בתוס'."],["2052","5","<b>המאריך באחד מאריכין</b>: ברכות יג, ב."],["2053","6","<b>מאן דאריך</b>: ראה זח\"ב רנט, ב. ועוד."],["2054","7","<b>כדי שתמליכהו למעלה ולמטה ולד' סטרין</b>: ראה ברכות שם. זח\"ג רכג, ב. ערב, א. ובכ\"מ."],["2055","8","<b>הנה מקום אתי. . הוא מקומו של עולם</b>: תשא לג, כא. ב\"ר פס\"ח, ט. וראה לקו\"ת ויקרא הוספות נא, ב (בשם לקו\"ת להאריז\"ל פ' תשא עה\"פ). שלח מג, א."],["2056","9","<b>הוא תפיס בכולא עלמין</b>: ראה זח\"ג רכה, א."]]],[2101000320,"מאן דתפיס בי', מקום אתי כתיב שיש בחי' מקום גם אצלו ית'. אך מבשרי<sup data-n=\"2057\">10</sup> אחזה אלוה, בגשמי' בחי'<sup data-n=\"2058\">11</sup> מקום יש בו ו\"ק מעלה ומטה מזרח מערב צפון ודרום, ו\"ק הנ\"ל הם בחי' מיצר וגבול בגשמיות שלא יתפשט יותר העולם ובחי' מקום הוא השטח לאורך ורוחב כנ\"ל וכן הוא למעלה כביכול העולמות שלמעלה יש בחי' מקום השטח ההשפעה שמשפיע הוא בחי' מקום ויש בו ג\"כ ו\"ק הוא בחי' הגבול שלא יתפשט יותר, כי העולמות מוגבלים כי מחנה מיכאל בחי' אהבה ומחנה גבריאל הוא בחי' יראה כו' והם מוגבלים כי במדה ניתן להם מששת ימי בראשית, וכן ביצירה ו\"ק דיצירה והוא<sup data-n=\"2059\">12</sup> בחי' עבדו זקן ביתו, והעולמות נק' בחי' מקום גשמי נגד עולמות דאצי'<sup data-n=\"2060\">13</sup>, וצ\"ל ענין בחי' מקום אתי כי בחי' מקום איתא ג\"כ בבחי' אצי' וכמ\"ש ברוך כבוד ה' ממקומו משמע שיש בחי' מקום גם אצלו ית'.\n<b>גם</b> להבין ענין ו\"ק דאצי', הנה בחי' אצי' הוא נמשך בג' קוין והוא הגדול הגבור והנורא כמ\"ש בפרד\"ס<sup data-n=\"2061\">14</sup> חח\"ן מימין בג\"ה משמאל דתי\"ם באמצע ונמשכין מבחי' כתר, הנה בחי' מקום הוא בחי' השפעה בשטח דהיינו שמשפיע עד\"מ חכמה וכדומה ובחי' השפעה בעצמה הוא בחי' מקום ובחי' הגבול שלא יתפשט יותר כי בחי' מעלה היא ראשית ההשפעה עד\"מ השפעות החכמה יש בחי' מלמעלה ממקום התחלת החכמה דהיינו כי זה שנתהווה להיות בחי' חכמה הוא מחמת הרצון בחי' חפץ חסד הוא ובחי' מעלה הוא ראשית ההשפעה שמחמת זה נתהווה הוא בחי' מעלה, ומטה הוא סוף ההשפעה כשנשתלשל בחי' חכמה בכל עולם ועולם הגשמי שכל אנושי וזהו סוף ההשפעה בחי' מטה ולא יותר וזהו ג\"כ אורך דהיינו אריכות ההשפעה, ורוחב הוא בחי' הרחבת ההשפעה בכל מיני שכליות אך רק באופן זה דהיינו מה שהחכמה הנ\"ל משפיע או חסדים או גבורות רק שהוא בבחי' רוחב וכן בגבורות וכו', וימין ושמאל הוא ההיפוך אף שמשפיע לו חסדים הוא יכול להבין דבר מתוך דבר אף בגבורות וכן להיפך וזהו בחי' ו\"ק כי ימין ושמאל הוא בחי' דרום וצפון ואוי\"ר הוא בחי' מזרח ומערב ומעלה ומטה, ומהו בחי' גבול כי באצי' הוא המדות בלי גבול כו' שהגבול הוא המדה המנגד לזה המדה עד\"מ כשרוצה להשפיע מדת חסדים בלי גבול מדת הגבורה מנגדת שלא יתפשט יותר וכן מדת גבורה כשרוצה בבחי' גבורה שלא להשפיע אזי מדת החסד מתנגדת, והמדה השנית הוא הגבול של הא', וזהו בחי' מקום דו\"ק דז\"א ונמשך בג' קוין מן הבחי' כתר דהיינו רצון והוא ג\"כ בחי' מקום שהרצון להתפשט חסדים בלי קץ והרצון של בחי' גבורה מנגדת וכן להיפך, ובבחי' רחמים שהוא קו האמצעי כי<sup data-n=\"2062\">15</sup> יעקב מבריח מן הקצה אל הקצה יש ג\"כ בחי' גבול שלא יתפשט יותר<sup data-n=\"2063\">16</sup>.",[["2057","10","<b>מבשרי אחזה אלוה</b>: איוב יט, כו."],["2058","11","<b>בחי' מקום יש בו ו\"ק</b>: ראה בכ\"ז גם לקו\"ת בחוקותי מח, ב (ובמצויין שם). ס' שע\"ת לאדהאמ\"צ קכה, ג. וש\"נ. ובכ\"מ."],["2059","12","<b>והוא בחי' עבדו זקן ביתו</b>: חיי\"ש כד, ב. וראה זח\"א קכו, ב."],["2060","13","<b>דאצי'</b>: בכת\"י ב': דז\"א."],["2061","14","<b>בפרד\"ס חח\"ן מימין</b>: שער סדר עמידתן (ש\"ו) פ\"א. וראה ס' מאמרי אדהאמ\"צ בראשית ע' ריז. וש\"נ."],["2062","15","<b>כי יעקב מבריח מן הקצה אל הקצה</b>: ראה זח\"ב קעה, ב. זח\"ג קפו, א. ועוד."],["2063","16","<b>יותר</b>: בכת\"י ב' נוסף: כי בחי' רחמים שורה דייקא. [וכנראה חסר כאן]."]]],[2101000321,"<b>ולכאורה</b> הוא להיפך כי בחי' הגבול<sup data-n=\"2064\">17</sup> הוא שהמדה המנגדת (אותה הוא מגבילה ובבחי' רחמים הוא בחי' ת\"ת הוא כלול משתיהן מחסדים וגבורות ומהו הגבול המנגד שלא יתפשט יותר כי בחי' רחמים שורה דווקא על בחי'<sup data-n=\"2065\">18</sup>) דין וגבורה דהיינו עני או מדוכא ביסורין ומסתמא הוא בדין שעושין לו דין מלמעלה שאין בחי' חסד גובר כי צריך לדין וע\"ז שורה רחמים שמרחם עליו בבחי' רחמנות בלבד אף שאינו ראוי להטיב לו נמצא שהוא כלול משתיהן ומהו<sup data-n=\"2066\">19</sup> המנגד. אך אעפי\"כ אנו רואים שיש גבול ומדה לבחי' רחמנות ג\"כ, שיש בחי' גבורה שאין הרחמים גובר ג\"כ רצון<sup data-n=\"2067\">20</sup> וכדומה שאין ראוי אפי' לרחמנות, וזהו מחמת כי מדת רחמנות הוא ג\"כ במדה כי הו\"ק דז\"א הם במדה כו' ומקור ושורש לבי\"ע להיות בחי' בע\"ג ממש.\n<b>אך</b> צ\"ל מה שאנו אומרים יהי<sup data-n=\"2068\">21</sup> רצון מלפניך שיכבשו רחמיך את כעסך הלא בחי' רחמים הוא ג\"כ בגבול ומדה ואיך הוא מדת רחמנות, וכבוש את כעסך הלא אין מדת הרחמים שורה אלא על בחי' כעס כנ\"ל כי הוא ממתיק הגבורות ונק' המתקת הגבורות אבל כשיש כעס גדול שראוי לדבר זה וכנ\"ל אזי אין הרחמנות גובר כי הוא ג\"כ בבחי' מדה וכו' ומה זה שאנו מתפללים יה\"ר כו'. אך כי יש בחי' רחמים רבים שהוא בלי גבול והוא בחי' עצמיות, והוא בחי' יעקב המבריח מן הקצה כו' נחלה בלי מצרים שאין לו בחי' מיצר וגבול והוא נמשך מבחי' כתר כי יש פנימיות הכתר וחיצוניות הכתר, כי<sup data-n=\"2069\">22</sup> הוא ממוצע בין מאציל לנאצלים, נקודה התחתונה שבמאציל נעשה מקור וראש לנאצלים וחיצוניות הכתר הוא הרצון הגלוי שמזה נמשך בהשתל' בחי' ג' קוין הנ\"ל. ואף שהוא שורש וראש להם כי הוא רצון שלמעלה מהטעם ודעת שאין לו בחי' טעם ודעת גלוי ע\"ז הרצון רק שרצונו כך בלי טעם גלוי והוא בלי גבול אך אעפי\"כ יש טעם הכמוס על בחי' הרצון שאינו מתגלה לזולתו והוא בחי' ח\"ס ומחמת טעם הכמוס נמשך בבחי' קוין כי אנו רואים שפעם הרצון כך ופעם כך אך שהוא בלי טעם אך הוא משתנה מפני טעם הכמוס שפעמים הטעם הכמוס ממשיך כך ופעם כו', ופנימיות הכתר הוא בחי' עצמיות כתר שבכתר שאינו בבחי' מקור להיות ממנו הג' קוין הנ\"ל שהוא למעלה אפי' מן בחי' חכמה סתימאה הנ\"ל שהוא רק רצון פשוט בלי שום השתנות והוא בחי' רחמים רבים הנ\"ל בחי' ע\"ס הגנוזות במאצילן כי ע\"ס גנוזות בחי' חכים ולא בחכמה ידיעא מבין ולא בבינה ידיעא ובבחי' חסד חסדי<sup data-n=\"2070\">23</sup> ה' כי לא תמנו כי הם בלי הפסק ובגבורה תכלית שנאה וכדומה בחי' ע\"ס הגנוזות בחי' עצמיות ולא<sup data-n=\"2071\">24</sup> מכל מדות אלין כלל, וזהו שאנו מתפללים יה\"ר שיהי' רצון הפשוט פנימיות הרצון מלפניך דייקא, ויהי' בחי' רצון",[["2064","17","<b>הגבול</b>: בהכת\"י אין ברור אם רשום: הגבול, או: הגדול."],["2065","18","<b>(אותה הוא מגבילה. . דווקא על בחי')</b>: כ\"ה בהכת\"י."],["2066","19","<b>ומהו</b>: בכת\"י ב': וזהו."],["2067","20","<b>רצון</b>: כ\"ה בהכת\"י, ואולי חסר כאן כמה תיבות."],["2068","21","<b>יהי רצון מלפניך שיכבשו רחמיך את כעסך</b>: ברכות ז, א."],["2069","22","<b>כי הוא ממוצע בין מאציל לנאצלים</b>: ראה ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א."],["2070","23","<b>חסדי ה' כי לא תמנו</b>: איכה ג, כב."],["2071","24","<b>ולא מכל מדות אלין כלל</b>: ע\"פ תקו\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101000322,"הפשוט בחי' ר\"ר בלי גבול בחי' נחלה בלי מצרים ומשם יכול להיות התחדשות שיכבוש הרחמים את כעס הגדול כי הוא בלי גבול בחי' עצמותו ית'.\n<b>וזהו</b> אנכי מי שאנכי<sup data-n=\"2072\">25</sup>, כי הוא יכול למחות החטא שזדונות<sup data-n=\"2073\">26</sup> נעשו לו כזכיות, וזה הבחי' בחי' ר\"ר נתגלה בר\"ח אלול נפתחין יגמה\"ר, ולכאורה אינו מובן כי בכל השנה מאירים י\"ג מדות הרחמים ומה ההתחדשות בר\"ח אלול. אך שכל השנה הוא בחי' י\"ג ת\"ד בבחי' שערות שהוא המשכה מחיצוניות הכתר ובר\"ח אלול מתגלה בחי' ר\"ר בחי' כתר שבכתר בחי' גלגלתא ובמה אנו מעוררים הבחי' הנ\"ל הוא בחי' רחל<sup data-n=\"2074\">27</sup> מבכה על בניה כו' בבחי' בכי', כי אני<sup data-n=\"2075\">28</sup> לדודי ודודי לי ר\"ת אלול, כי בחי' אני לדודי הוא בחי' בכי' הנ\"ל שהוא דייקא מחמת הריחוק ואזי מעורר בחי' ודודי לי בחי' ר\"ר כי אנו רואים שבכי' ור\"ר מתדמין זל\"ז כי אנו רואים כשבוכה אזי מתעורר ר\"ר עליו וגם רחמים מעורר הבכי' עד\"מ כשאב אינו רואה לבנו ימים רבים אזי מחמת הרחמנות על בנו בוכה ע\"כ מחמת הריחוק והבכי' איך שהוא משפיל את עצמו ואומר הוידוי אשמנו כו', ומחמת הריחוק ממשיך דייקא בחי' ר\"ר הנ\"ל, וזהו בחי' בע\"ת, והוא עד\"מ מעיגול וקו שנמשך בתוך העיגול ובקו יש בחי' ירידות ועליות אבל בעיגול מעלה ומטה שוין כן הוא ג\"כ שמה שנמשך בקו ומדה דהיינו שכל ומדות כמו שהוא באתעדל\"ת כן הוא באתעדל\"ע כמו שהוא בבחי' מ\"ן כן הוא בבחי' מ\"ד, ומהו שנמשך עד\"מ אם עוסק באהבה או אפי' בהתבוננות כן נמשך לו ג\"כ בבחי' מ\"ד אהבה או בחי' בינה וכדומה כי רוח<sup data-n=\"2076\">29</sup> אייתי רוח ואמשיך רוח אבל בבחי' ריחוק הנ\"ל שמשפיל א\"ע לאין אזי יבוא לבחי' ר\"ר הנ\"ל כי בבחי' ריחוק שורה דייקא ומתגלה אור א\"ס, כי בגלות דווקא שורה ומתגלה בחי' היותר הגבוה, כי בזמן בהמ\"ק הי' פא\"פ בחי' פנימי' בחי' אורות בכלים שהי' שורה בבית ק\"ק השכינה כמ\"ש במ\"א וזה הי' גם כן במ\"ת<sup data-n=\"2077\">30</sup> פב\"פ, אבל בגלות בבחי' ריחוק דייקא שורה ומתגלה בחי' א\"ס כנ\"ל.\n<b>וזהו</b> שכתוב שאג ישאג<sup data-n=\"2078\">31</sup> על נוהו אחית תרין דמעין (וגומ' וא\"מ וגומ'<sup data-n=\"2079\">32</sup>) כי מחמת המנגד ניכר האהבה עד\"מ שדואג במר נפש ובוכה על העבר שאבד מסתמא",[["2072","25","<b>אנכי מי שאנכי</b>: ראה ראב\"ע תולדות כז, יט. ס' תניא מהדו\"ק פמ\"ט (ע' קו). ס' מאמרי אדה\"ז עה\"ת ח\"א ע' רט, ובהמ\"מ שם."],["2073","26","<b>שזדונות נעשו לו כזכיות</b>: יומא פו, ב."],["2074","27","<b>רחל מבכה על בניה</b>: ירמי' לא, יד. וראה גם לקו\"ת נצבים מז, ג. באוה\"ת על מארז\"ל ע' עב (וס' קיצורים והערות לתניא ע' קמז) מביא מר\"ח שער התשובה פ\"א ”כדי שנתקן גלות שכינתו יתברך\", וכותב באוה\"ת: ”וע' מזה מ\"ש ע\"פ רחל מבכה על בניה דתקס\"ט\". ולכאו' כוונתו להמאמר שלפנינו. [ענין רחל מבכה כו', נמצא גם בד\"ה זה שבס' עבודת הלוי שצויין לעיל בתחילת המאמר]."],["2075","28","<b>אני לדודי ודודי לי ר\"ת אלול</b>: שה\"ש ו, ג. פע\"ח שער ר\"ה פ\"א. ראשית חכמה שער התשובה פ\"ד (ד\"ה עוד יש). ב\"ח לטור או\"ח סתקפ\"א. ועוד."],["2076","29","<b>רוח אייתי רוח ואמשיך רוח</b>: ראה זח\"ב קסב, ב. זח\"א צט, ב."],["2077","30","<b>במ\"ת פב\"פ</b>: ואתחנן ה, ד."],["2078","31","<b>שאג ישאג על נוהו אחית תרין דמעין</b>: ירמי' כה, ל. זח\"ב קצו, א: ה' ממרום ישאג וממעון קדשו יתן קולו שאוג ישאג על נוהו ואדכר לון לישראל ונחית תרין דמעין לגו ימא רבא. וראה ג\"כ זח\"ב ט, א. זח\"ג קלז, ב. קעב, א. ועוד."],["2079","32","<b>וגומ' וא\"מ וגומ'</b>: כ\"ה בהכת\"י, וניכר שהוא טעות המעתיק: ואוצ\"ל: בגו ימא רבא."]]],[2101000323,"שהוא דבר שאהבתו אליו באה\"ר כי יש כמה בחי' דואג הרבה על הדבר ובוכה ויש שאינו דואג אלא מעט ואינו בוכה זהו הכל מחמת כמו שהי' אהבתו אל הדבר ההוא כמו שהי' אהבה בבחי' פנימיות כך הוא הדאגה וכן בהיפך ע\"כ כתיב שאג ישאג ובחי' תרין דמעין זהו כביכול בהיפוך שהי' לו לישראל בבחי' אה\"ר וכן הוא ג\"כ באדם מחמת הריחוק גובר האהבה ורוצה בבחי' חילא<sup data-n=\"2080\">33</sup> יתיר אזי ממשיך אא\"ס בעצמו מה שלא הי' יכול לעשות ע\"י העלאת מ\"ן בהתבוננות או באהבה וכדומה והוא ג\"כ כמו שבהשתלשלות העולמות תהו הוא גבוה בשרשו מן בחי' תיקון ונשתלשל בחי' תוהו ונק' בחי' תוהו שלמעלה בחי' אורות המקיפים ונעשה למטה ג\"כ מקיפים בחי' יש גמור, כי אנו רואים בבהמה שהיא מצד התוהו שמדתה תוקף מבחי' אדם כי אצלה הוא בתוקף ועוז בבחי' שאין יכול להיפך מן הטבע שיש לה בטבע תולדתה ובבחי' אדם יכול המדה להיפך בשכל כי הוא אינו בתוקף ועוז הוא בבחי' תיקון אבל בבחי' בהמה הוא בבחי' תוהו, וכמו שנשתלשל שלא בדרך הדרגה כי הוא בדרך ריחוק כן מלמטה למעלה כשהוא בבחי' תוהו ומוריד דמעות מחמת הריחוק כנ\"ל אזי יבוא ג\"כ שלא בדרך הדרגה למעלה לבחי' ר\"ר בחי' עצמיות.\n<b>וכמ\"כ</b> הוא בבחי' גלות ג\"כ שמתלבש בע' שרים בדרך ריחוק כמ\"ש כרחל<sup data-n=\"2081\">34</sup> לפני גוזזי' נאלמה כי בזמן בהמ\"ק הי' הע' שרים בבחי' הביטול וכמ\"ש וכל<sup data-n=\"2082\">35</sup> צבא השמים לך<sup data-n=\"2083\">36</sup> משתחוים וד\"ל. רק שהי' בחי' גיזוז השערות והשערות היו מחוברים ע\"כ היו בטלים כי ד\"י<sup data-n=\"2084\">37</sup> בבחי' אורות בכלים בבחי' קו כנ\"ל. . בהם הי' בחי' ביטול רק שהי' יונקים מקצת השערות מותרי המוחין ע\"כ לא הי' להם שליטה רק בחי' עושר וכבוד כסף וזהב. אבל בגלות כרחל לפני גוזזיה נאלמה שהשערות הם בחי' גוזזיה ע\"כ הם בבחי' יש גמור אני <sup data-n=\"2085\">38</sup>.. כו' ויש להם שליטה כי הם בבחי' יש נפרדים ממש עכשיו דייקא מכל השערות כמו שהי' גוזזים שלא בדרך הדרגה כנ\"ל, וזהו נאלמה כי בזמן המקדש למען<sup data-n=\"2086\">39</sup> יזמרך כבוד כו' ועכשיו הוא בבחי' נאלמה וע\"כ מהריחוק באים דייקא לבחי' ר\"ר מבחי' עצמיות.\n<b>וזהו</b> המאריך באחד שהוא אריכות בד' דאחד שהוא בחי' ד' סטרין. . והוא בחי' מקום כנ\"ל והוא המאריך איך אריכות א' הנ\"ל שנמשך מבחי' מקום אתי ונמשך מלמעלה למעלה מבחי' הוא בחי' ביטול המקום למקורו, וזהו עושין רצונו של מקום שממשיכין בחי' רצון לבחי' מקום בחי' מל' להמשיך בבי\"ע בבחי' גילוי, וע\"כ פרשה ראשונה בבחי' עושין רצונו של מקום כי בחי' רצון ש\"מ הוא בחי' חיצוניות הכתר כו', ובמה עושין שיהי' התחדשות. . נמשך בבחי' קו המדה ח\"ס",[["2080","33","<b>חילא יתיר</b>: זח\"א קכט, ב."],["2081","34","<b>כרחל לפני גוזזי' נאלמה</b>: ישעי' נג, ז. וראה גם לקו\"ת נצבים מח, ב. ובכ\"מ."],["2082","35","<b>וכל צבא השמים לך משתחוים</b>: ע\"פ נחמי' ט, ו."],["2083","36","<b>לך משתחוים</b>: ע\"כ נמצא בכת\"י א', ומכאן ואילך נדפס מכת\"י ב'."],["2084","37","<b>ד\"י</b>: כ\"ה בהכת\"י, וצ\"ב תיבה זו."],["2085","38","בהכת\"י חסר בצידי הגליון, וחסר כאן תיבה אחת או שתיים."],["2086","39","<b>למען יזמרך כבוד</b>: תהלים ל, יג."]]],[2101000324,"שמודד מחמת טעם הכמוס איך להיות אופן ההמשכה אבל עושין רצון מבחי' פנימיות הרצון נקודה תחתונה שבמאציל בחי' א\"ס בחי' מל' בחי' כתר שבכתר וכנ\"ל ע\"כ כתיב בפרשה ראשונה ובכל מאדך בחי' מאד מאד בלי גבול, וע\"כ בפ' שני' בבחי' אין עושין רש\"מ כי באמת ממשיך רצון לבחי' מקום אבל אינו מבחי'. . מבעל הרצון מבחי' עצמי' וכו' כי מחמת בכל לבבך וכו' הכתובה בפ' שני' ממשיך בהם בחי' רצון וכו' אבל. . בפ' ראשונה ממשיך מבעל הרצון וכו', ע\"כ בפ\"ר כתיב תורה קודם למצות תפילין וכדומה בפ' שני' כתיב מצות תפילין קודם לתורה כי עכשיו מצות הן למטה מבחי' תורה רק לעתיד מתגלה המצות יותר.\n<b>כי</b> באברהם כתיב עקב<sup data-n=\"2087\">40</sup> אשר שמע אברהם בקולי כו' קיים א\"א את כל התורה כולה כו' ואיך קיים מצות שיש מצות שלא נוהגות שלא בזמן המקדש כמו תרומות ומעשרות וכדומה רק שקיים המצות כמו שהן למעלה בשרשן בחי' מצותיו ותורותיו כמו שהקב\"ה. . באצילות לבד והי' ממשיך מבחי' בעל הרצון מבחי' עצמי' לבחי' חיצונית הכתר שהי' נמשך. . אבל כשבא לקיים המצות בגשמיות אזי שורה ומתגלה אורות בכלים כי הוא שורה ו\"ק<sup data-n=\"2088\">41</sup> על הכלים. . גשמי' ורק עכשיו הוא בחי' אברים דמלכא ותורה הוא מבחי' עצמי' למעלה מבחי' מצות וע\"כ בפרשה ראשונה עורש\"מ מבחי' בעל הרצון וכנ\"ל ופ\"ש שהוא בבחי' אין עושין וכו' אזי מצות קדמה, ולעתיד יתגלה בחי' המצות יותר כי בשרשן מצות גבוהים.",[["2087","40","<b>עקב אשר שמע אברהם. . קיים א\"א את כל התורה</b>: תולדות כו, ה. יומא כח, ב."],["2088","41","<b>ו\"ק</b>: תיבה זו אינה ברורה בהכת\"י."]]],[2101000325,"<h3>הללו את ה' כל גוים</h3>\n<b>תורה דשמ\"ע</b>\n<b>הללו</b><sup data-n=\"2089\">1</sup> את ה' כל גוים כו' כי גבר עלינו חסדו ואמת ה' כו'. להבין ענין נתינת טעם הזה כי גבר עלינו חסדו ע\"כ הללו<sup data-n=\"2090\">2</sup> את ה' כל גוים דלכאו' אין זה טעם מספיק. וגם להבין עיקר ענין שמ\"ע שמקריבין בו פר א' ואיל א' ובז' ימי החג מקריבין ע' פרים ביום הא' י\"ג פרים ומתמעטין והולכי' בכל יום עד יום הז' שמקריבין בו ז' פרים כידוע, וכל<sup data-n=\"2091\">3</sup> אלה הע' פרים לנגד ע' אוה\"ע כידוע, ואמר<sup data-n=\"2092\">4</sup> בזהר הטעם דבז' ימי החג זמין לבחי' אושפיזין והן ז' אושפיזין עילאין כו' ובשמע\"צ עביד סעודתא לבני היכלא דמלכא שהן ישראל ע\"כ מקריבין פר א' בלבד כו' למיהוי א' בא' כו'. ולהבין למה על הענין דע' שרים דאוה\"ע קראם בשם אושפיזין עילאין.",[["2089","1","<b>הללו</b>: נדפס ג\"כ (בתוס' הגהות) באוה\"ת דרושים לסוכות ע' א'תשנה. וראה ג\"כ ד\"ה בסוכות תשבו תשל\"ו."],["2090","2","<b>הללו את ה' כל גוים</b>: תהלים קיז, א."],["2091","3","<b>וכל אלה הע' פרים לנגד ע' אוה\"ע</b>: סוכה נה, ב. במדב\"ר פכ\"א, כד."],["2092","4","<b>ואמר בזוהר הטעם</b>: זח\"ג קד, ב."]]],[2101000326,"<b>ועוד</b> הלא אושפיזין המה אבות ישראל אברהם ויצחק<sup data-n=\"2093\">5</sup> כו'. וגם להבין ענין פר א' שבשמע\"צ מפני שישראל<sup data-n=\"2094\">6</sup> נק' גוי אחד בארץ וזהו למהוי א' בא' כו'. הנה כ\"ז יובן בהקדים שורש ענין שמחת תורה שהוא בחדש תשרי דוקא ותשרי אותיות ראשית חסר אלף והענין עד\"מ מנפש האדם שבחי' גילוי כללות חיות הנפש וראשיתו הנה הוא מתגלה ושורה במוחין שבראש ומשם מתפשט לכל האברים לכ\"א כפי מזג חומרו וא\"כ הרי כל החיות פרטי' שבכל האברים כמו כח הראי' וכח השמיעה ודיבור וריח וכל המשכות חיות פרטיים שבאיברים פנימי' וחיצוני' כולם כלולי' המה במוחי' שבראש שכוללם יחד בבחי' כללות החיות ואח\"כ מבחי' המוחין שבראש מתפשטין ומתחלקין כאו\"א לפי טבעו לשכון בכלי ואבר המיוחד אליו כידוע וכך הוא הדמיון להבין שרש בחי' ר\"ה שהוא ר\"ח תשרי וכל החודש ההוא עד שמע\"צ הוא בחי' כללות החיות לכל ימות השנה שכלולי' בו כל פרטי אור וחיות שבכל ימי השנה שמתחלקי' לי\"ב חדשים ושס\"ה ימי' כו' ומחודש הזה נמשכי' ובאין בבחי' התחלקות פרטיי' כאו\"א בזמנו (ושורש הענין הוא בחי' התחלקות הזמן מלמע' מן הזמן שבתשרי הוא כללות התחלקות הזמן דשס\"ה ימים כו') וזהו בבחי' עולם שנה וכמו\"כ בבחי' נפש כמ\"ש במ\"א וככה בבחי' המשכת<sup data-n=\"2095\">7</sup> התורה מח\"ע הרי ביוה\"כ נתנו לוחות האחרונות שהן כללות כל התורה כולה על כל השנה כמו במועדי' ורגלים כו' ומתחלק אח\"כ לפרטי פרטיות וכמו\"כ בבחי' המשכות שמח' של מצוה הנה בשמחת תורה נמשך המשכה כללית בבחי' שמחה של מצוה על כל השנה כו', וע\"כ נק' חדש זה תשרי אותיות ראשית כנ\"ל.\n<b>ולהבין</b> ענין שמחה של מצוה מה שרשה למע'. הנה ילה\"ק תחלה מ\"ש תחת<sup data-n=\"2096\">8</sup> אשר לא עבדת את הוי' בשמחה וטוב לבב מרוב כל כו', פי' עבודה זו היא עבודת מעהמ\"צ כידוע ואומר שהשמחה וטוב לבב מעבודת המצוה שנק' שמחה ש\"מ הוא למע' במדריגה גם מרוב כל, ויובן זה ע\"פ מארז\"ל דיפה<sup data-n=\"2097\">9</sup> שעה א' בתשומע\"ט בעוה\"ז מכל חיי עוה\"ב, פי' חיי עוה\"ב הנה הוא בחי' זיו השכינה שהנשמות נהנין כו' כידוע ופי' שכינה הוא בחי' ממכ\"ע מבחי' הארת הקו שאינה אלא הארה א' מעצמות אוא\"ס שלפני הצמצום כו' שנק' סוכ\"ע בכלל כידוע, וידוע דביו\"ד<sup data-n=\"2098\">10</sup> נברא העוה\"ב מאין ליש שהוא רק בחי' הארה דממלא הנ\"ל, וא\"כ אינו רק בחי' הארה דהארה בנשמות שנהנין מזיו זה כמ\"ש כי<sup data-n=\"2099\">11</sup> עמך מקו\"ח באורך נראה אור כו' אבל בחי' מקור כל התענוגי' שלמע' מבחי' זיו ואור ע\"ז אמר כי עמך מקו\"ח והוא בחי'",[["2093","5","<b>ויצחק</b>: באוה\"ת שם: אברהם וישראל ויצחק."],["2094","6","<b>שישראל נק' גוי אחד בארץ</b>: שמואל-ב ז, כג."],["2095","7","<b>המשכת התורה מח\"ע</b>: ראה זח\"ב פה, א. קכא, א."],["2096","8","<b>תחת אשר לא עבדת</b>: דברים כח, מז. וראה תניא פכ\"ו ובליקוט פירושים ומ\"מ שם."],["2097","9","<b>דיפה שעה אחת בתשומע\"ט</b>: אבות פ\"ד מי\"ז. וראה תו\"א ויחי מו, ג. לקו\"ת ראה יט, ד. אוה\"ת דרושים לפ' זכור ע' א'תשסט. ובכ\"מ."],["2098","10","<b>דביו\"ד נברא העוה\"ב</b>: מנחות כט, ב. ירושלמי חגיגה פ\"ב ה\"א. זח\"א ד, א. ובכ\"מ. וראה אגה\"ק ס\"ה."],["2099","11","<b>כי עמך מקו\"ח</b>: תהלים לו, י. וראה לקו\"ת ויקרא נא, ד. תו\"ח שמות תרמה, ב. ובכ\"מ."]]],[2101000327,"סובב הנ\"ל שלמע' גם ממקור כל חיי עוה\"ב שנברא ביו\"ד ונק' זיו והארת השכינה כנ\"ל, ולזה אמר דיפה שעה א' בתשו' ומע\"ט בעוה\"ז מכל חיי עוה\"ב לפי שבמצות ומע\"ט יש בו בחי' מפנימי' הרצון והתענוג העליון הפשוט שבעצמות אוא\"ס שלפני הצמצום שנק' סובב כנ\"ל, ונק' מקור כל בחי' התענוגי' העליוני' הבאי' בבחי' ההשתלשלות דקו\"ח כו' דהיינו למע' הרבה מבחי' עונג העליון שבחי' זיו והארה בעלמא שמאיר בחיי העוה\"ב מבחי' ממלא הנ\"ל, וזהו הטעם שמברכין על המצות אשר קדשנו במצותיו פי' אשר לשון עונג כמו באשרי<sup data-n=\"2100\">12</sup> כו' וכידוע וראי' לדבר ממה שהמצות נק' בש' רמ\"ח<sup data-n=\"2101\">13</sup> איברים דמלכא ועד\"מ אור וחיות העצמות של הנפש שמתפשט ברמ\"ח איברים ע\"י אמצעות המוחין שבראש כו', כך למע' בחי' אור חיות העצמי' דמלכא עילא' שהן כללות ע\"ס דאצי' הוא ע\"י המצות דוקא וז\"ש ועשיתם<sup data-n=\"2102\">14</sup> אותם וארז\"ל כאלו עשאוני כו' משום דאיהו<sup data-n=\"2103\">15</sup> וחיוהי חד כו' וד\"ל.\n<b>והנה</b> ארז\"ל דבעוה\"ב<sup data-n=\"2104\">16</sup> צדיקי' יושבים ועטרותיהן בראשיהן וי\"ל מהו ענין העטרות שעל ראשיהן והלא עיקר העוה\"ב הוא מה שנהנין מזיו כו' כנ\"ל. אך הנה מה שנהנין מזיו כו' הוא רק בחי' התגלות עונג העליון הבא בבחי' ממלא כנ\"ל שזה האור בא בבחי' או\"פ לנשמות דהיינו בבחי' השגה ותפיסא ממש להיות נהנין במורגש ממש כל חד לפ\"ע כלי השגתו כו' אבל בחי' העטרה שעל גבי הראש הוא בחי' אור עונג העליון המאיר עליהם בבחי' מקיף בלתי מוגבל ומתלבש בבחי' כלי כלל כו', כי לא יכילנו כלי ההשגה כלל וכלל וכמו העטרה שנתנה ע\"ג הראש למע' מן כלי המוחין שבראש כו' להיותו למע' מן ההשגה והתפיסא לגמרי רק בבחי' מקיף שורה על גבי הראש כו', והוא בחי' אור התענוג הפשוט שנמשך מבחי' סוכ\"ע כנ\"ל, המלובש במצות מעשיות וע\"כ מכל המצות שעשו הצדיקי' מהם נעשו בחי' עטרות בחי' מקיפים על ראשיהן וזהו למע' הרבה מכל עיקר חיי העוה\"ב שנהנין מזיו כו' כנ\"ל הטעם שבחי' סובב למע' הרבה מבחי' ממלא וז\"ש צדיקי' יושבי' ועטרותיהם בראשיהן מהארת סובב ונהנין מזיו השכינה שנק' חיי העוה\"ב בבחי' או\"פ לפי ערך כלי השגתם כו' וד\"ל (ולזה אמרו דשכר<sup data-n=\"2105\">17</sup> מצוה מצוה שהרי המצוה עצמה שנעשה ממנה בחי' עטרה בחי' מקיף הנ\"ל הרי היא למעלה משכר המצוה ליהנות מזיו שאינו אלא מבחי' ממלא כנ\"ל וד\"ל), וכמו העטרה הגשמי' שעשוי' מכמה מיני אבנים טובות ולא ממין א' בלבד לפי שזהו עיקר היופי וההידור ונק' כליל תפארתו כך בחי' העטרות העליונו' שע\"ג ראשי הצדיקים שנעשי' מבחי' מעשה המצות שלהן יש בהן כמה מיני מדריגות אורות שונות זו מזו מפני חילוקי כמה מיני",[["2100","12","<b>באשרי</b>: בראשית ל, יג. וראה ת\"ז תי' ט\"ל (עט, א)."],["2101","13","<b>רמ\"ח אברים דמלכא</b>: ראה ת\"ז תי' ל. זח\"ב קיח, א. וראה תניא פ\"ד ובליקוט פירושים ומ\"מ שם."],["2102","14","<b>ועשיתם אותם וארז\"ל כאילו עשאוני</b>: ראה זח\"ג קיג, א. ויק\"ר פל\"ה, ז."],["2103","15","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["2104","16","<b>דבעוה\"ב צדיקים. . בראשיהן</b>: ברכות יז, א."],["2105","17","<b>דשכר מצוה מצוה</b>: אבות פ\"ד מ\"ב. וראה תניא פל\"ז, פל\"ט."]]],[2101000328,"מצות מעשיות שונות שכל מצוה יש לה המשכה מיוחדת אם מחסדים או מגבורות או כלול משתיהן יחד כמו כמה מיני גוונים שונים שבכמה מיני אבנים טובות הגשמיים כו'. (וזהו<sup data-n=\"2106\">18</sup> שארז\"ל ע\"פ ויתנצלו בני ישראל את עדי\"ם מהר חורב שהן ב' כתרים שע\"ג כאו\"א שקיבלו בשעת מ\"ת כו' מטעם קבלת מעשה המצות כשאמרו נעשה ונשמע כידוע וז\"ש ותבואי<sup data-n=\"2107\">19</sup> בעד\"י עדיי\"ם כו' וכמ\"ש במ\"א).\n<b>והנה</b> בחי' העטרות הנ\"ל נק' ג\"כ בשם אמונה כי האמונה ג\"כ היא בבחי' אור מקיף ע\"ג המוחין שבראש כי הרי האמונה היא למעלה מן הטעם וההשגה שבמוח וכך העטרות הנ\"ל הן למעלה מן השכל וז\"ש וצדיק<sup data-n=\"2108\">20</sup> באמונתו יחי' וזה פלא לכאורה למה דוקא בבחי' האמונה שלו ולא בעבודתו בדו\"ר שכליי' וכיוצא אך הענין הוא כי בחי' או\"מ גדול הרבה מבחי' או\"פ וכל קבלת או\"פ הוא נמשך רק מבחי' מקיף כידוע בענין מזל\"א כו' ולזה אמר דצדיק גם בעבודתו באוי\"ר שכליי' וכיוצא באמונתו יחי' מבחי' האמונה שלמעלה מן ההשגה יחי' בהשגת שכל דגם שהחכ' תחי' אבל מקבלת מלמעלה מן החכמה וכמ\"ש והחכ'<sup data-n=\"2109\">21</sup> מאין תמצא שהוא הארת הכתר בחכ' שנק' מזלא (וכך למעלה הרי אמר בע\"ח דאור<sup data-n=\"2110\">22</sup> אבא יונק ממזל הח' דונוצר וזהו הכל<sup data-n=\"2111\">23</sup> תלוי במזל אפי' ס\"ת בהיכל כמ\"ש במ\"א וד\"ל). ולפי\"ז הרי בחי' המשכת תענוג העליון שע\"י המצות נמשך לעתיד בבחי' ההעלם ע\"ג הראש שהוא בבחי' האמונה שלמעלה מן השכל והטעם אבל עכשיו ע\"י מעשה המצות בעוה\"ז הנה בחי' המשכות אור מקיף הזה בא לידי גילוי והוא ע\"י בחי' שמחה של מצוה שהרי השמחה היא באה בבחי' גילוי בפנימי' הלב והמצוה הגם ששרשה בחי' מקיף ועטרה ע\"ג הראש אך בשמחה של מצוה באה לידי גילוי מן ההעלם כו' וד\"ל.\n<b>אך</b> יש להבין לכאורה איך אפשר להיות שיומשך ויבא בחי' העלם המקיף דתענוג העליון המלובש במצות ששרשו בבחי' סובב הכללי כו' שהוא בלתי ב\"ג לידי גילוי במקבלים שהן ב\"ג ותכלית כמו בשמחה ש\"מ או בעטרות שע\"ג ראשי הצדיקים הרי אין ערוך כלל לב\"ג לגבי בלתי ב\"ג כידוע, אך הנה זה יובן בהקדים מ\"ש זה<sup data-n=\"2112\">24</sup> היום עשה ה' נגילה ונשמחה בו פי' מה שנמשך בחי' הארת התענוג והשמחה העליונה שנשמחה בו בבחי' בלתי ב\"ג זאת עשה ה' לנו הגם שנשמות הן ב\"ג ותכלית אך מאת ה' היתה זאת ההמשכה מלמעלה למטה, וז\"ש זה היום עשה ה' לנו שנגילה ונשמחה ב\"ו, והיינו ביו\"כ כו'. כי הנה אנו אומרים בסוכות ושמ\"ע זמן שמחתינו ב' מיני שמחה א' שמחה של מעלה והב' שמחה של מטה בנשמות ישראל.",[["2106","18","<b>וזהו שארז\"ל ע\"פ ויתנצלו</b>: שמות לג, ו. שבת פח, א."],["2107","19","<b>ותבואי בעדי עדיים</b>: יחזקאל טז, ז."],["2108","20","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד. וראה תניא פל\"ג."],["2109","21","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["2110","22","<b>דאור אבא יונק ממזל הח'</b>: ע\"ח שער או\"א ספ\"ח. שער הזווגים ספ\"ב. שער הולדת או\"א וזו\"ן פ\"ו. שער העבורים פ\"ב. שער הנסירה ספ\"ג."],["2111","23","<b>הכל תלוי במזל</b>: זח\"ג קלד, א. וראה שבת קנו, א."],["2112","24","<b>זה היום עשה ה'</b>: תהלים קיח, כד."]]],[2101000329,"<b>והענין</b> הוא דהנה בחי' שמחה של מעלה היינו כמ\"ש ישמח<sup data-n=\"2113\">25</sup> ה' במעשיו שהוא מקבל שמחה ממעשיו<sup data-n=\"2114\">26</sup> דהיינו מנשמות ישראל שבשבילם נמשך כל ההשתלשלות דאבי\"ע לפי שישראל<sup data-n=\"2115\">27</sup> עלו במחשבה קודם ההשתלשלות כנודע ואמנם עיקר השמחה באה מבחי' המנגד דהיינו כמו היוצא מבית השבי' שישמח מאד, וכמו\"כ אב שבנו יוצא לחירות חפשי מבית השבי' עושה משתה ושמחה מפני שמקבל תענוג גדול מזה כידוע, וכך גם בנשמות ישראל שנק' בנים כמ\"ש כי<sup data-n=\"2116\">28</sup> בנים אתם כו' וביו\"כ יוצאי' מבית השבי' מובדלים מיניקות הסט\"א ע\"י מחילת וסליחת עון שכאשר הי' העוונות מבדילים כמחיצה של ברזל ה\"ז כמו השבי' וכמ\"ש מלך<sup data-n=\"2117\">29</sup> אסור כו' ואנו<sup data-n=\"2118\">30</sup> יוצאי' לחירות ע\"י טהרת העון ביו\"כ כמ\"ש כי<sup data-n=\"2119\">31</sup> ביום הזה יכפר עליכם לטהר אתכם כו' אזי ממילא נמשך בחי' שמחה ותענוג גדול למעלה בעצמות אא\"ס בסוכות שאחר יו\"כ והוא הנק' שמחה של מעלה וז\"ש זה היום עשה ה' שנעשה למעלה מאת ה' להיות בו בחי' גילוי ושמחה כו' ונמשך גם למטה מטה בנשמות ישראל והוא שמחה הב' שנק' שמחה של מטה בנשמות ישראל. אך אין הארת שמחה של מעלה מאיר בנשמות ישראל בבחי' או\"פ רק בבחי' מקיף והוא ענין סכך דסוכה שזהו ענין וימינו<sup data-n=\"2120\">32</sup> תחבקני כמשי\"ת אך מ\"מ נמשך בהם ממש ואע\"פ שבעוה\"ב אינן יכולים לקבל הארה זו רק בבחי' עטרות ע\"ג הראש כנ\"ל ומה שנהנין מזיו כו' הוא רק הארה בעלמא היינו לפי ששרש ומקור חיי העוה\"ב הוא רק מבחי' ממלא כנ\"ל, אבל ע\"י המצות בעוה\"ז מתגלה דוקא מבחי' סובב וכמ\"ש אשר<sup data-n=\"2121\">33</sup> אנכי מצוך כו' אנכי מי שאנכי<sup data-n=\"2122\">34</sup> בחי' סובב הכללי כו', וע\"כ יפה שעה א' במע\"ט בעוה\"ז דוקא מכל חיי העוה\"ב כו' ואע\"פ שבעוה\"ז הוא בחי' צמצום והסתר היותר אחרון כידוע מ\"מ לא יש מניעה מזה כלל בבחי' הארת סובב הכללי כו' משום דקמי' כחשיכה כאורה כו' שאין בחי' הסתר והעלם שנק' חושך מחשיך ומעלים כלל מאחר שנאמר בו אני<sup data-n=\"2123\">35</sup> ה' לא שניתי כו' כמו קודם ההשתלשלות כך הוא אחר ההשתלשלות אין עוד מלבדו וכולא קמי' כלא כו', וככה הוא בזמן שמחתינו בסוכות שנמשך הארת מקיף הכללי בבחי' שמחה העליונה וחופף ומקיף על נשמות ישראל ע\"י סכך<sup data-n=\"2124\">36</sup> דסוכה שנק' צילא דמהימנותא בחי' צל המקיף כידוע וז\"ש ישמח ישראל בעושיו שמחמת הארת המקיף דשמחה העליונה נמשך בחי' שמחה שלמטה להיות ישמח ישראל בעושיו מלמטה למעלה והוא ע\"י שמחה של מעלה שנק' עושיו וכמו שאנו אומרי' וישמחו ב\"ך ב\"ך דוקא וד\"ל.",[["2113","25","<b>ישמח ה' במעשיו</b>: תהלים קמט, ב."],["2114","26","<b>ממעשיו</b>: בכת\"י ב: ממעשינו."],["2115","27","<b>שישראל עלו במחשבה</b>: ב\"ר בתחילתו. ובכ\"מ."],["2116","28","<b>כי בנים אתם</b>: דברים יד, א."],["2117","29","<b>מלך אסור</b>: שה\"ש ז, ו. וראה תניא פמ\"ה. אגה\"ת פ\"ז."],["2118","30","<b>ואנו</b>: בכת\"י ב: ואזי. ובכת\"י ג: ואם."],["2119","31","<b>כי ביום הזה יכפר</b>: ויקרא טז, ל."],["2120","32","<b>וימינו תחבקני</b>: שה\"ש ב, ו."],["2121","33","<b>אשר אנכי מצוך</b>: דברים ו, ו."],["2122","34","<b>אנכי מי שאנכי</b>: ראה זח\"א קסז, ב. זח\"ג רנז, ב. לקו\"ת פינחס פ, ב. שם ראה לא, ד."],["2123","35","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["2124","36","<b>סכך דסוכה שנק' צילא דמהימנותא</b>: זח\"ג קג, א ואילך. זח\"ב קפו, ב. וראה סידור רנז, א. ובכ\"מ."]]],[2101000330,"<b>והנה</b> בז' ימי הסוכות נמשך האור העליון בבחי' מקיף בלבד כנ\"ל וכמ\"ש וימינו תחבקני עד\"מ אדם החובק את חבירו שמסבבו מכל צד בידיו ובכתפיו מאחוריו לבלתי יוכל ליפרד מאיתו כלל כך הארת צילא דמהימנותא חופף על נשמות ישראל בבחי' חביקה מכל צד לבלתי יוכלו להיפרד כלל מאחדות הפשוטה כו' אבל עכ\"ז אין האור מאיר בנשמתם בבחי' או\"פ כלל, אך בשמיני עצרת מאיר האור בהם בבחי' פנימי' והוא הנק' בחי' קליטה כמ\"ש<sup data-n=\"2125\">37</sup> בפע\"ח. ולהבין זה הנה יש להקדים שרש ענין מחילות העוונות ביו\"כ, דהנה כתיב וזרקתי<sup data-n=\"2126\">38</sup> עליכם מים טהורים כו' ויש להבין מהו מים טהורים כו', אך הענין הוא דעיקר מחילות העוונות הוא ע\"י המשכת י\"ג מדה\"ר ביו\"כ כידוע וכל עשי\"ת או' י\"ג מדה\"ר כדי שעי\"ז יומשך ממקור י\"ג מדה\"ר ביו\"כ, וזהו שאו' ממעמקים בכל עשי\"ת שהן בחי' י'<sup data-n=\"2127\">39</sup> עומקים הנז' בס\"י דהיינו להמשיך מעומקא דעומקא ששם מקור י\"ג מדה\"ר שלמעלה מן החכמה לגמרי ע\"כ משם נמשך מחילת העוונות וטהרת החטאים. וביאור הדבר ידוע להיות שיש ב' מיני מדות הא' בחי' המדות שלמטה מן השכל והוא כמו בחי' המדות שבתורה ולהבדיל בין טמא לטהור כו' שהוא נמשך עפ\"י החכמה דוקא כידוע דאורייתא<sup data-n=\"2128\">40</sup> מח\"ע נפקת ויש<sup data-n=\"2129\">41</sup> בה מ\"ט פנים טמא כו', וע\"כ עפ\"י התורה אין<sup data-n=\"2130\">42</sup> יסורים בלא עון כו', אבל להיות נושא עון ועובר על פשע כו' בהכרח שזה נמשך מלמעלה מן החכמה שבמדות העליונות אלא מבחי' אור הכתר שלמעלה מבחי' החכמה ובחי' המדות שבכתר נק' מדות שלמעלה מן החכמה והן בחי' י\"ג מדה\"ר כמו ונוצ\"ר חס\"ד ור\"ב חס\"ד שאמר<sup data-n=\"2131\">43</sup> בזוהר אית חסד ואית חסד כו' דבחי' ורב חסד שבאור הכתר הוא מקור כל החסדים והוא למעלה הרבה מבחי' החסד שנמדד בקצבה עפ\"י השכל בלבד אבל בחי' החסד שלמעלה מן השכל אינו מוגבל כלל ומתפשט בלי שיעור כמו גם להטיב לרעים כמו לטובים כו' ונק' ימין העליון וכמו וימינך<sup data-n=\"2132\">44</sup> פשוטה לקבל שבים כו' ומשם יוכל להיות נושא עון לגמרי וכן מדת הרחמים דשם נק' ר\"ר בלי גבול ומדה מטעם זה כידוע, וז\"ש אנכי אנכי<sup data-n=\"2133\">45</sup> הוא מוחה פשעיך פי' אנכ\"י הוא בחי' פנימי' אור הכת\"ר שלמעלה מהתלבשות בחכמה ודוקא משם הוא מחילת העוונות מטעם הנ\"ל וד\"ל. וזהו וזרקתי עליכם מים טהורים כו' פי' מים הן בחי' מי החסדים העליונים אך אית חסד ואית חסד כנ\"ל דהיינו בחי' החסד המסתעף מן החכמה שיש שם מדידה ויוכל להיות נטיה למדת הדין ונק' מיין מרירין וכמו ולא<sup data-n=\"2134\">46</sup> יכלו לשתות כו' כי מרים הם כו' וממדת הדין שבחסד יש יניקה לחיצוני' ע\"י העוונות כי יש שם בחי' התחלקות טמא וטהור כו' ולא נק' מים טהורים לגמרי רק בחי' המקיפים שהוא",[["2125","37","<b>כמ\"ש בפע\"ח</b>: ראה שער הלולב פ\"ח. וראה באוה\"ת הנסמן לעיל בריש המאמר (ע' א'תשסג)."],["2126","38","<b>וזרקתי עליכם מים טהורים</b>: יחזקאל לו, כה."],["2127","39","<b>י' עומקים הנז' בס\"י</b>: פ\"א מ\"ה."],["2128","40","<b>דאורייתא מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["2129","41","<b>ויש בה מ\"ט פנים טמא כו'</b>: ראה עירובין יג, ב. במדב\"ר פי\"ט ב. ובכ\"מ."],["2130","42","<b>אין יסורים בלא עון</b>: שבת נה, א."],["2131","43","<b>שאמר בזוהר אית חסד ואית חסד</b>: זח\"ג קלג, ב."],["2132","44","<b>וימינך פשוטה לקבל שבים</b>: תפילת נעילה."],["2133","45","<b>אנכי אנכי הוא מוחה פשעיך</b>: ישעי' מג, כה. וראה לקו\"ת אמור לד, ד."],["2134","46","<b>ולא יכלו לשתות</b>: שמות ז, כא."]]],[2101000331,"כמו בחי' ורב חסד ונוצר חסד שלמעלה מבחי' החכמה שאין שם שום שרש ואחיזה לטומאת החיצונים ע\"כ נק' מים טהורים והמה ביכולתם ג\"כ לטהר מכל טומאת חטא שכבר יש למטה וז\"ש וזרקתי עליכם מים טהורים ממקור י\"ג מדה\"ר לטהר אתכם מכל חטאתיכם, וזהו לפני הוי' תטהרו לפני בחי' התחלקות המדות שמן החכמה כידוע דשם הוי' היו\"ד הוא בחי' חכמה ה\"א בינה כו' ולפני הוי' היינו בשם אהי' דכתר שלמעלה משם הוי' דחכמה משם תטהרו דוקא מטעם הנ\"ל וד\"ל.\n<b>והנה</b> אחר המשכת י\"ג מדה\"ר ביו\"כ שהוא שרש מחילות העוונות נמשך בחי' המקיפי' בסוכות וע\"כ מקריבים בז' ימי החג ע' פרים לנגד ע' שרים כנ\"ל, והענין הוא כי ידוע בשרש הע' שרים שלמטה שהוא מבחי' ז' מלכי' קדמאין דתהו שמתו ונפלו למטה בבי\"ע כמ\"ש ואלה<sup data-n=\"2135\">47</sup> המלכים כו' וימלוך וימת כו' ולמטה מטה נתהווה מהן ז' מדות הרעות דנוג\"ה דעשי' שנק' ז' פרות הרעות שבולעות לז' פרות הטובות דקדושה בתוכם כמ\"ש ולא<sup data-n=\"2136\">48</sup> נודע כי באו אל קרבנה כו' לפי שבחי' נוג\"ה דעשי' רובו רע כו' ובחי' הטוב דסט' דקדושה נבלע בהן ממש, וזהו שרש ענין גלות השכינה כידוע ולעתיד כתיב והוצאתי<sup data-n=\"2137\">49</sup> את בלעו מפיו כו' דהיינו כל בחי' ניצוצות דקדושה שבלעו החיצוניי' כמ\"ש חיל<sup data-n=\"2138\">50</sup> בלע ויקיאנו כו' (וז\"ש לולי<sup data-n=\"2139\">51</sup> ה' שהי' לנו כו' בקום עלינו אדם בליע\"ל דשליט באדם דקדושה כמ\"ש עת<sup data-n=\"2140\">52</sup> אשר שלט האדם באדם לרע לו כדי לברר ממנו הטוב לגמרי ולא ישאר בו רק חלק הרע לגמרי כו' ואז ממילא יאבד כידוע כו' וז\"ש אזי חיים בלעונו כו', אך ברוך ה' שלא נתננו טרף לשיניהם כו' כצפור נמלטה מפח כו' ובבהמות וחיות ועופות הן המה החיות הרעות המזיקי' וטורפים ועופת הדורסים כו' ולעתיד יבוררו הכל ע\"כ נאמר לעתיד לא ירעו ולא<sup data-n=\"2141\">53</sup> ישחיתו כו' ארי' כבקר יאכל תבן וגר זאב עם כבש ופרה ודוב תרעינה יחדיו ירבצו ילדיהן כו' וכמ\"ש במ\"א), וזהו מ\"ש יצב<sup data-n=\"2142\">54</sup> גבולות עמים למספר בנ\"י כי לנגד ע' נפש דיעקב בסט' דקדושה להיות שרש כללות נש\"י במדות דקדושה, והמדות הן ז' וכאו\"א כלול מי' כידוע כך גם הציב מחצב שרש אוה\"ע במספר כזה להיות שרשם מז' מדות דנוג\"ה כנ\"ל וכל מדה כלולה מי' ע\"כ המספר שלהם ג\"כ ע' (ומה שאמרו במדדש שמ\"ע שם ע' ישראל א' מע' מאומות וכו' מבואר במ\"א וד\"ל) (וגם בבחי' הזמן והמספר הקצוב ע' שנה לשרש כללות נשמות ישראל שהן ע' שני' השאולי' מאלף שנין דאדם קדמאה כידוע<sup data-n=\"2143\">55</sup> ומבואר בזוהר ומרומז גם בדברי רז\"ל",[["2135","47","<b>ואלה המלכים כו' וימלוך וימת</b>: בראשית לו, לא ואילך."],["2136","48","<b>ולא נודע כי באו אל קרבנה</b>: בראשית מא, כא."],["2137","49","<b>והוצאתי את בלעו מפיו</b>: ירמי' נא, מד."],["2138","50","<b>חיל בלע ויקיאנו</b>: איוב כ, טו. וראה תו\"א תולדות כ, ג. אוה\"ת שם קנד, א. שערי אורה פו, ב ואילך. ובכ\"מ."],["2139","51","<b>לולי ה' שהי' לנו</b>: תהלים קכד, א."],["2140","52","<b>עת אשר שלט האדם באדם</b>: קהלת ח, ט. וראה זח\"ב צה, ב. פרדס שט\"ז פ\"ז."],["2141","53","<b>לא ירעו. . וגר זאב</b>: ישעי' יא, ו ואילך. וראה שם סה, כה."],["2142","54","<b>יצב גבולות עמים למספר בנ\"י</b>: דברים לב, ח. וראה בהנסמן בס' הערכים חב\"ד מערכת אותיות ע' רפד ואילך."],["2143","55","<b>כידוע ומבואר בזהר</b>: זח\"א נה, א. צא, ב. וראה ניצוצי זהר שם. וראה דרמ\"צ קח, ב. ובכ\"מ."]]],[2101000332,"באמרם ודוד מי קשיש כולי האי כו' וכן<sup data-n=\"2144\">56</sup> ע\"פ הודיעני מדת ימי כו', כי המל'<sup data-n=\"2145\">57</sup> לית לה מגרמה כלום כו'), כך גם למל' דנוג\"ה הוגבל מספר זה דע' שנה כמ\"ש ימי<sup data-n=\"2146\">58</sup> שנותינו בהם ע' שנה פי' בהם בהיכלות דנוג\"ה כמ\"ש במ\"א דה\"ם זה בהיפוך אותיות דשם מ\"ה משום דקאי בבחי' נוג\"ה שהניצוץ האלקי מלובש בה במספר קצוב ע' שנה דוקא כו' וד\"ל<sup data-n=\"2147\">59</sup>).\n<b>והנה</b> לזה הטעם מקריבים ע' פרים בז' ימי החג לנגד ע' שרים כנ\"ל כדי לברר ולהוציא מהם כל בחי' ניצוצות דקדושה האלקית שנפלו בשברה\"כ מבחי' ז' מדות דתהו המלובש ומאיר בתוך תוכם כנ\"ל שהוא תוס' מרובה על עיקר חיותם ושפעם הנמדד ממקורא דכולא כי בבחי'<sup data-n=\"2148\">60</sup> מאמר קו המדה הרי נאמר קץ<sup data-n=\"2149\">61</sup> שם לחושך כו' רק ע\"י יניקתם מסט' דקדושה בא להם תוס' אור תמיד ולזה מקריבים הע' פרים להיות קרבן אשה ריח ניחוח לה' ויתעלה עי\"ז בחי' הטוב שבהן ויוכלל הכל למעלה באלקי' חיים ואז ממילא אין להם קיום כי כבר כלה קיצם כו' וד\"ל. אך עדיין יש להבין בסדר הקרבת הע' פרים למה מקריבים ביום הא' י\"ג פרים וביום הב' י\"ב פרים כו' ועד\"ז הולך ומתמעט עד שביום הז' מקריבי' ז' פרים. אך הנה זה יובן בהקדים ענין הידוע שבסט' דקדושה למעלה יש י\"ג מדות עליונות שלמעלה מן החכ' ונק' י\"ג מדה\"ר ובזהר נק' י\"ג ת\"ד דא\"א כידוע וכולן המה בחי' אורות מקיפי' כידוע שז\"ש ויקרא<sup data-n=\"2150\">62</sup> ה' ה' אל רחום וחנון כו' ורב חסד כו', וביאור זה ידוע עד\"מ באדם למטה בעבודת ה' הנה<sup data-n=\"2151\">63</sup> יש ב' מיני אהבות אהבה זוטא שנק' אהבת עולם והיא הנולדה מן השכל והטעם שע\"י השכל והטעם בגדולת הבורא מתעורר לבבו באהבה ע\"כ נק' אהבת עולם, והב' אה\"ר שלמעלה מן השכל והטעם שהיא רק מפני שבאה מלמעלה בחי' אהבה הנק' ימין מקרבת וכמ\"ש וימינו<sup data-n=\"2152\">64</sup> תחבקני עד\"מ אדם החובק לחבירו שלא יפרד מאתו שאין סיבת הדיבוק הזה שהוא היפך הפירוד מחמת הנחבק אלא רק מחמת החובק כך התעוררות אהבה רבה העליונה שתחבק לניצוץ האלקי ואינה מנחת אותה להיפרד כלל רק ליכלל ולידבק תמיד באחד כו', הנה כמים<sup data-n=\"2153\">65</sup> הפנים תתעורר אה\"ר בניצוץ האלקי למעלה מן השכל והטעם הרי אין התעוררו' זו מחמת עצמו כלל וכלל מאחר שאינה נמשכת מצד השכל כלל רק מפני התעוררות אהבה רבה העליונה שנמשכה עליו ומחבקו וכמו אהבה כמים הפנים בלב האדם לאדם שאין התעוררות אהבה זו בלבו נולדה מחמת האדם כלל רק מפני שחבירו מראה לו לבבו באהבה רבה הוא מעורר בלבבו ג\"כ אהבה זו אליו כמים הפנים כו'",[["2144","56","<b>וכן ע\"פ הודיעני מדת ימי</b>: ע\"פ תהלים לט, ה. ב\"ר פי\"ט, ח."],["2145","57","<b>המל' לית לה מגרמה כלום</b>: ראה זח\"א קלה, ב. ובכ\"מ."],["2146","58","<b>ימי שנותינו בהם ע' שנה</b>: תהלים צ, י."],["2147","59","<b>וד\"ל)</b>: בכת\"י ג אין כאן מוסגר."],["2148","60","<b>בבחי' מאמר קו המדה</b>: ראה זח\"א טו, א. ובכ\"מ."],["2149","61","<b>קץ שם לחושך</b>: איוב כח, ג."],["2150","62","<b>ויקרא ה' ה' אל רחום וחנון</b>: שמות לד, ו."],["2151","63","<b>הנה יש ב' מיני אהבות</b>: ראה בארוכה בס' הערכים חב\"ד כרך א' ע' תקח ואילך, ע' תקסג ואילך."],["2152","64","<b>וימינו תחבקני</b>: שה\"ש ב, ו."],["2153","65","<b>כמים הפנים</b>: ראה משלי כז, יט. וראה תניא פמ\"ו, ובכ\"מ."]]],[2101000333,"א\"כ אהבה רבה זו מחמת חבירו באה לו בלבו ולא מחמתו כלל וד\"ל, וכך יובן למעלה בבחי' אה\"ר שלמעלה מבחי' חכ' דאצי' שנק' רב חסד או ונוצר חסד שהוא מי\"ג מדה\"ר שלמעלה מן החכמה כנ\"ל, ועד\"ז כל המדות הללו הן בחי' מקיפים שלמעלה מהגבלת אור בכלי כו' כידוע משא\"כ בחי' המדות שלמטה מן החכמה שהן אורות פנימי' מוגבלים בכלים כמו עד\"מ אהבה זוטא שנק' אהבת עולם הנ\"ל ולמעלה נק' ז' כפולות וג' אמות חב\"ד כו' כמ\"ש<sup data-n=\"2154\">66</sup> בס\"י וד\"ל, והנה עד\"ז יש ג\"כ בסט' דקליפה כי זה לעומת זה עשה האלקי' כידוע דהיינו שיש ז' מדות הרעות שלמטה מן השכל שנולדו מן השכל כו' ויש י\"ג מדות שלמעלה מן השכל ולא נולדה בלבו מן השכל כלל ונק' מקיפי' דקליפה וכמו עבר<sup data-n=\"2155\">67</sup> עבירה ושנה הותרה לו שנעשית לו כהיתר בלי התעוררות טעם ושכל אלא מבחי' מקיפי' דקליפה שלמעלה מן החכמה דקליפה מקפת וחובקת לנפשו הבהמית כמו ימין מקרבת דבסט' דקדושה כנ\"ל עד שמתעורר כמים הפנים כו' באהבה רעה זו שלמעלה מן הטעם וע\"כ הותרה לו וכמארז\"ל הבא<sup data-n=\"2156\">68</sup> לטמא פותחין לו שערי טומאה להמשיך עליו מכתרין דקליפה שאינו עפ\"י טעם ודעת כלל כו' (וכמ\"ש במ\"א בפי' וירא<sup data-n=\"2157\">69</sup> את העם כי בר\"ע הוא כו') אבל לנגד ז' מדות הטובות שנולדים מן השכל נמשך בקליפה ז' מדות הרעות שנולדים מן השכל כמו תאוות<sup data-n=\"2158\">70</sup> וממון וכה\"ג אך כמו ענין תאוות הכבוד והלבושים הנאים הוא מבחי' מקיפי' דקליפה שלמעלה מן השכל כו' שהוא קליפה יותר קשה ועמוקה וידוע<sup data-n=\"2159\">71</sup> שכל דבר הגבוה יותר כשנופל יפול למטה הרבה ביותר מדבר שאינו גבוה כ\"כ שאינו נופל למטה כ\"כ כך בחי' המדות דתוהו להיות שרשן למעלה מן השכל והן למעלה הרבה כידוע ע\"כ בנפילתן נפלו למטה יותר והוא בחי' מדות דקליפה שהן בלתי מוגבלים בשכל ונק' מדות שבלא טעם, כמו תאוות הכבוד והלבושים וההתנשאות והחוצפא כו' וד\"ל, ולזאת הנה מקריבים ע' פרים לברר דוקא לבחי' מקיפי' דקליפה ולכך מקריבים ביום הא' י\"ג פרים לברר י\"ג מדות דמקיפי' דקליפה לברר מהם הטוב ולהעלותם בי\"ג מדות העליונות כו', וביום הא' נברר אור מקיף א' וביום הב' מקיף השני כו' עד יום הז' שאז מקריבי' ז' פרים שהוא לברר ז' מדות דקליפה שנולדים מהחכמה כי הבירור הרי הוא בא מלמטה למעלה מבחי' נוג\"ה ותחלה צריך לברר הקליפה הקשה שנפל למטה יותר שהן המקיפים כנ\"ל, ואח\"כ הפנימי' שאינם למטה כ\"כ וע\"כ ביום הז' מקריבים ז' פרים וד\"ל.\n<b>וזהו</b><sup data-n=\"2160\">72</sup> שמקריבי' הע' פרים אחר מחילת העוונות ביו\"כ דוקא כנ\"ל שאז נמשכו כל בחי' המקיפי' דקדושה בז' ימי החג בסכך דסוכה כנ\"ל כי הנה בכל השנה",[["2154","66","<b>כמ\"ש בס\"י</b>: פ\"א מ\"ב. וראה תניא פ\"ג ופ\"ו ובליקוט פירושים ומ\"מ שם."],["2155","67","<b>עבר עבירה ושנה הותרה לו</b>: יומא פו, ב."],["2156","68","<b>הבא לטמא פותחין לו שערי טומאה</b>: שבת קד, א. זח\"א נד, א. ובכ\"מ."],["2157","69","<b>וירא את העם כי ברע הוא</b>: שמות לג, כב. וראה שעה\"ת ח\"ב פ\"י."],["2158","70","<b>תאוות וממון</b>: אוצ\"ל: תאוות ממון."],["2159","71","<b>וידוע שכל דבר הגבוה יותר</b>: ראה לעיל ע' קא ובהנסמן במ\"מ שם."],["2160","72","<b>וזהו שמקריבים הע' פרים אחר מחילת העוונות</b>: ראה ג\"כ תו\"א מקץ לד, ב. תו\"ח שמות שלט, ב. ד\"ה אל תצר לכ\"ק אדהאמ\"צ ע' 14."]]],[2101000334,"שלא נמחלו עוונות ישראל עדיין הרי עוונותיהם <sup data-n=\"2161\">73</sup>מבדילים כמחיצה כו' ומעורב בהן בחי' הרע דע' שרים בדיבוק וחיבור יחד כי שלט האדם באדם כו' כנ\"ל ע\"כ אינן יכולי' להקריב ע' פרים לברר הטוב מע' שרים אך לאחר שנמחלו עוונות שלהם ביו\"כ ונתרוממו ונתעלו למעלה בלי תערובות רע כלל וכלל אז דוקא יכולים לברר מע' שרים בחי' הטוב שבהם כו', אך עדיין אין בירור זה רק מבחי' מקיפי' דסכך דקדושה שאינו אלא בסכך<sup data-n=\"2162\">74</sup> דסוכה וכה\"ג שנק' צילא דמהימנותא רק בבחי' ההעלם על<sup data-n=\"2163\">75</sup> נשמות ישראל מפני שאין האור מאיר עדיין בתוך תוכם בבחי' קליטה עד שמיני עצרת שאז נקלט האור בבחי' קליטה כידוע בענין עצרת לשון עציר\"ה וקליטה מפני שאז הוא אחר הבירורים דמקיפים שבכל ז' ימי החג כנ\"ל ע\"כ מקריבים בו פר א' בלבד נגד ישראל בלבד כי אין אז בירור לסט' דקליפה כי כבר נבררו המקיפי' ופנימי' שלהם בז' ימי החג כנ\"ל, וזהו שאמר דעביד סעודתא לבני ביתא והיכלא דמלכא כנ\"ל וכמשי\"ת וד\"ל, וע\"כ השמחה דכל החג הוא רק בהעלם בבחי' מקיף בלבד אבל בשמיני עצרת באה השמחה בבחי' גילוי להיות האור בא בבחי' פנימי' בחי' קליטה כנ\"ל וד\"ל.\n<b>וזהו</b> הללו את ה' כל גוים שבחוהו כל האומים כי גבר עלינו חסדו כו'. כי הנה מבואר למעלה דע' פרים שבז' ימי החג הן לנגד ע' שרים דקליפה ועי\"ז גבר עלינו חסדו בשמיני עצרת כנ\"ל כי פי' גבר עלינו היינו ע\"י בחי' תגבורת השמחה והתענוג העליון ע\"כ יגבר חסדו בתגבורת שפע אור גדול מאד להיות נמשך על נשמות ישראל לאין קץ ושיעור כלל כידוע שכל דבר שאין לו שיעור ותכלית נק' תגבורת החסד וכ\"ז גרמו הקרבת הע' פרים לברר מהע' שרים כנ\"ל עד\"מ היוצא מבית השבי' ששבי' זו גרמה שמחה גדולה ביציאתו ממנה כו' וככה בירור הניצוצות מע' שרים גורמים שמחה ותענוג גדול בנשמות ישראל מלמעלה למטה בשמיני עצרת להיות בבחי' קליטה כנ\"ל כי אחר הבירור דוקא נמשך בחי' קליטה דש\"ע כנ\"ל, וזהו הללו את ה' כל גוים בז' ימי החג שמקריבים בשבילם ע' פרים כדי שיגבר עלינו חסדו בשמ\"ע עלינו דוקא כי<sup data-n=\"2164\">76</sup> חלק ה' עמו וכמ\"ש ומי<sup data-n=\"2165\">77</sup> כעמך ישראל גוי אחד כו' וד\"ל, וזהו כל<sup data-n=\"2166\">78</sup> פעל ה' למעניהו וגם רשע ליום רע\"ה, פי' כמו שכל פעל ה' למעניהו דוקא כמ\"ש לכבודי<sup data-n=\"2167\">79</sup> בראתיו כו' כך גם התהוות הרשע הוא למעניהו כדי לגרום בבירור שלו שמחה ותענוג גדול למעלה וכמ\"ש ובאבוד<sup data-n=\"2168\">80</sup> רשעים רינה ומפני שהטוב שבהם עולה למעלה ע\"כ אמר הללו את ה' כל גוים שנכלל הטוב שבהם באלקי' חיים כנ\"ל, וזהו העלי' שלהם כו' ומה שאמר כפל לשון גוים ולאומים הענין הוא כי יש ב' מיני בירורים הא' בחי' בירור הטוב מן הרע להעלותו למעלה ומה",[["2161","73","<b>עוונתיהם מבדילים כמחיצה</b>: ראה ישעי' נט, ב. תניא פי\"ז ובליקוט פירושים ומ\"מ שם."],["2162","74","<b>בסכך דסוכה. . שנק' צילא דמהימנותא</b>: זח\"ג קג, א."],["2163","75","<b>על. . ישראל</b>: בכת\"י ב: עלינו."],["2164","76","<b>כי חלק ה' עמו</b>: דברים לב, ט."],["2165","77","<b>ומי כעמך כישראל</b>: שמואל ב ז, כג."],["2166","78","<b>כל פעל ה' למענהו</b>: משלי טז, ד. וראה תניא פכ\"ז ובליקוט פירושים ומ\"מ שם."],["2167","79","<b>לכבודי בראתיו</b>: ישעי' מג, ז."],["2168","80","<b>ובאבוד רשעים רנה</b>: משלי יא, י."]]],[2101000335,"שלא יוכל להתברר נק' רע גמור הוא כלה ונאבד וז\"ש באבוד רשעים רינה כנ\"ל, והבירור הב' הוא לברר גם לבחי' הרע להיות גם הוא עולה ונכלל למעלה באלקות וכמו לעתיד דכתיב אז<sup data-n=\"2169\">81</sup> אהפוך אל עמים שפה ברורה לעבדו שכם א' פי' אהפוך אל עמים שיתהפכו מרע לטוב לגמרי ע\"ד ענין בע\"ת כשנמחל מהם העון והחטא לגמרי הרי הזדונות<sup data-n=\"2170\">82</sup> נעשו זכיות וכמ\"ש אם<sup data-n=\"2171\">83</sup> יהי' חטאיכם כשנים כשלג ילבינו כו' ועד\"מ ממיתוק המים הרעים ביפים שהמר נעשה מתוק וכן ענין מחילת העון והחטא כמ\"ש וזרקתי<sup data-n=\"2172\">84</sup> עליכם מים טהורים כו', וזהו ענין לאהפכא<sup data-n=\"2173\">85</sup> חשוכא לנהורא ומרירו למיתקא כו' אך הנה עכ\"ז הגם שנתברר הרע ונעשה טוב אינו עולה להיות בבחי' כלי פנימי' בבחי' הפנימי' דקדושה האלקי' אלא רק להיות בבחי' כלי חיצוניו' ואחוריים דקדושה, וע\"ד שנאמר לעתיד ועמדו<sup data-n=\"2174\">86</sup> זרים ורעו צאנכם שיהי' בחי' טפל לישראל ולא כמו הגרים שנק' גם הם בחי' טפל לישראל וכמ\"ש ונספחו<sup data-n=\"2175\">87</sup> כספחת כו', אבל מ\"מ אינם נק' עבדים כי גם הם נחשבים מבני היכלא דמלכא שהרי הגרים נכנסים תחת כנפי השכינה ובחי' כנפיים הגם שהם טפלים לגוף מ\"מ נחשבים עם הגוף אבל בחי' בירור האומות שנק' בחי' עבד שאינו נחשב מבחי' בני היכלא דמלכא בבחי' הפנימי' כלל ע\"ז אמר לעבדו שכם א' בבחי' חיצוניות ואחוריים דקדושה שנק' שכם וכתף לאחד כמו העבד שעובד עבודתו בכתף בלבד להיות כי<sup data-n=\"2176\">88</sup> ישראל עלה במחשבה כמשל טפה במוח האב, וע\"כ אמר כי<sup data-n=\"2177\">89</sup> אתה אבינו ונק' בנים כידוע וגם הגרים הרי הן ניצוצות דקדושה שנפלו בע' שרים ועולין תחת כנפי השכינה נק' ג\"כ בנים כמו<sup data-n=\"2178\">90</sup> נשמות שמעי' ואבטליון ונשמת ר\"ע ור\"מ וכה\"ג כמ\"ש<sup data-n=\"2179\">91</sup> בע\"ח בענין ועשו בא מצידו כי<sup data-n=\"2180\">92</sup> ציד בפיו כו' וגם הן נחשבים בבחי' כלי פנימי' רק שאינן בחי' פנימי' כישראל וכידוע בהיכל הגרים ובענין נפשות הגרים שעשה אברהם כמ\"ש ואת<sup data-n=\"2181\">93</sup> הנפש אשר עשו בחרן, ולכך מ\"ע לאהוב את הגרים (ולא משמע כן בטעם כי<sup data-n=\"2182\">94</sup> גר היית בארץ מצרים ששלט האדם באדם כו' בבחי' גלות השכינה בע' שרים כידוע וכך ענין ניצוץ האלקי דנפש הגר בע' שרים כשאח\"כ נעשה גר בישראל ולכך בענין הקללות אמר הגר<sup data-n=\"2183\">95</sup> אשר בקרבך יעל\"ה מעל\"ה כו' שהטפל נעשה עיקר והעיקר",[["2169","81","<b>אז אהפוך אל עמים</b>: צפני' ג, ט. ובהבא להלן ראה ג\"כ ס' הערכים חב\"ד כרך ב' ע' שכ ואילך, וע' תרנג."],["2170","82","<b>הזדונות נעשו זכיות</b>: יומא פו, ב."],["2171","83","<b>אם יהיו חטאיכם כשנים</b>: ישעי' א, יח."],["2172","84","<b>וזרקתי עליכם מים טהורים</b>: יחזקאל לו, כה."],["2173","85","<b>לאהפכא חשוכא לנהורא</b>: ראה זח\"א ד, א."],["2174","86","<b>ועמדו זרים ורעו צאנכם</b>: ישעי' סא, ה."],["2175","87","<b>ונספחו</b>: ישעי' יד, א."],["2176","88","<b>כי ישראל עלה במחשבה</b>: ב\"ר בתחילתו. ובכ\"מ. וראה תניא פ\"ב."],["2177","89","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["2178","90","<b>כמו נשמות שמעי' ואבטליון</b>: גיטין נז, ב. ובכ\"מ."],["2179","91","<b>כמ\"ש בע\"ח בענין ועשו אחיו בא מצדו</b>: בראשית כז, ל. וראה ע\"ח שער הארת המוחין פ\"ב. תו\"א תולדות כ, ג. אוה\"ת שם ע' קנד. ובכ\"מ."],["2180","92","<b>כי ציד בפיו</b>: בראשית כה, כח."],["2181","93","<b>ואת הנפש אשר עשו בחרן</b>: בראשית יב, ה."],["2182","94","<b>כי גר היית בארץ מצרים</b>: ויקרא יט, לד. ובכ\"מ."],["2183","95","<b>הגר אשר בקרבך יעלה מעלה</b>: דברים כח, מג."]]],[2101000336,"טפל כענין הידוע במאמר דרישא<sup data-n=\"2184\">96</sup> שכיבת לעפרא וזנבא שליט כמ\"ש קולה כנחש כו', אך זהו מדבר ברע דנוג\"ה שלא נברר עדיין רק אתכפייא ולא באתהפכא אבל מ\"מ אין הגר בבחי' ב\"ן וגם מענין האושפיזין לא משמע כן כמשי\"ת<sup data-n=\"2185\">97</sup>).\n<b>וזהו</b> ענין האושפיזין שבז' ימי החג כנ\"ל, דהנה על ב' מיני בירורים הנ\"ל אמר הללו את ה' כל גוים שהן הנבררים בבחי' הטוב שלהם בלבד והרע נופל שנק' הל\"ל<sup data-n=\"2186\">98</sup> לשון בהל\"ו נר\"ו כו' שאין בטוב העולה בחי' חיצוניות כלל ולאומים היינו גם בחי' הרע שנברר ונעשה בבחי' חיצוניות ואחוריים כנ\"ל, וע\"ז אמר שבחוהו כמו וחכם<sup data-n=\"2187\">99</sup> באחור ישבחנ\"ה ענין תיקון חיצוני בלבד והנה בכל השנה הע' שרים הן בבחי' הפירוד למטה מטה ובסוכות מתבררים ע\"י המקיפים דקדושה כנ\"ל והמברר נק' אושפיזא שאינו בא רק לפרקים משא\"כ ישראל שהן בני היכלא בתמידות להיותם מבחי' שם מ\"ה דתיקון שלאחר הבירור כידוע, וע\"כ כל האושפיזין המה על ענין הבירור מאוה\"ע דוקא כמו אושפיזא הא' אברהם שעשה גרים הרבה והכנסת אורחים גם לערביים וכה\"ג וכך הוא ענין כל האושפיזין לפי שהמה המבררים בירורי נוג\"ה שיוכללו ויעלו באלקות שאינו אלא לפרקים אך בשמ\"ע פר א' לבני היכלא שהן ישראל להיותם דבוקים תמיד באחד בבחי' פנימי', וזהו ואמת ה' לעולם שהוא בחי' קליטה להיות אמת חותמו נרשם ונקלט בכנס\"י שנק' עולם כמ\"ש אתה<sup data-n=\"2188\">100</sup> כהן לעולם וכידוע וד\"ל.",[["2184","96","<b>דרישא שכיבת לעפרא</b>: זח\"ג קיט, ב. וראה ע\"ח שמ\"ח פ\"ג. וראה ג\"כ סה\"מ אתהלך לאזניא ע' קמו. ובכ\"מ."],["2185","97","<b>כמשי\"ת)</b>: בהכת\"י חסר התחלת המוסגר."],["2186","98","<b>הל\"ל לשון בהל\"ו נר\"ו</b>: ראה איוב כט, ג. תו\"א וישב ל, א. שמות נד, ב. לעיל ע' קיז. ובכ\"מ."],["2187","99","<b>וחכם באחור ישבחנה</b>: משלי כט, יא."],["2188","100","<b>אתה כהן לעולם</b>: תהלים קי, ד."]]],[2101000337,"הוספות\nא) <b>ביאור</b><sup data-n=\"2189\">1</sup> מכ\"ק אדמו\"ר האמצעי — לד\"ה הללו את ה'.\nב) ביאור מכ\"ק ה”צמח צדק\" — לד\"ה צדקת פרזונו.\nביאור מכ\"ק אדמו\"ר האמצעי",[["2189","1","<b>ביאור</b>: נמצא בכמה כת\"י בין מאמרי כ\"ק אדמו\"ר האמצעי. [מאמר זה נדפס אח\"כ גם בס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'תסו. ושם בתוס' השוואות]."]]],[2101000338,"<h3>ביאור על ד\"ה הללו את ה' כל גוים - מכ\"ק אדמו\"ר האמצעי</h3>\n<b></b><b>בעזר\"ה (ביאור לתורה<sup data-n=\"2190\">2</sup> דשמ\"ע ע\"פ הללו את ה' כל גוים כו')</b>\n<b>להבין</b><sup data-n=\"2191\">3</sup> מ\"ש בע\"ח דכל עיקר ענין התורה והמצות הוא רק לברר בירורי נוג\"ה שהוא בחי' העלאות ניצוצות דרפ\"ח כו' ויש לכאורה סתירה גדולה ע\"ז ממ\"ש בזוהר דשרש תרי\"ג המצות הן בחי' תרי\"ג המשכות מבחי' תרי\"ג ארחין דגלגלתא ועם ז' מצות דרבנן הם תר\"ך עמודי אור בגי' כת\"ר<sup data-n=\"2192\">4</sup> כידוע, וגם הלא ידוע דהמצוה בעצמה הוא בחי' המשכה עד\"מ מצות סוכה הסכך הוא בחי' המשכות מקיפים דאימא ומצות תפילין הוא בחי' המשכות המוחי' דאו\"א לז\"א בד' פרשיות קד\"ש וכו' ומצות ציצית הוא בחי' המשכות ל\"ב נתיבות חכמה מבחי' אור מקיף דטלית והן ל\"ב חוטין דציצית כידוע ועד\"ז כל המצות, והגם שיש הרבה מצות שהן בחי' העלאות כמו מצות הקרבנות וכיוצא מ\"מ הרי מבואר בע\"ח דכל עיקר שרש כל המצות בכללות אינו אלא להוסיף אורות באצי', וידוע ענין הוספת אור שהוא בחי' המשכה מעצמות המאציל מלמעלה למטה ואיך א' בע\"ח שכל עיקר התורה והמצות הוא לברר בירורי נוג\"ה שהוא בחי' העלאה כידוע, וגם שרש התורה שא' בע\"ח שהוא לברר בירורים דוקא כי בחכ'<sup data-n=\"2193\">5</sup> אתברירו כידוע וכמ\"ש להבדיל בין טמא לטהור כו' הנה לכאורה יש סתירה גדולה ע\"ז ממה שידוע בעיקר מצות ת\"ת שהוא להמשיך אא\"ס בחכ' עילאה כי אורייתא<sup data-n=\"2194\">6</sup> מח\"ע נפקת כו'. אך הנה כ\"ז יובן בהקדים שיש ב' מיני מצות הא' בחי' המצות הרוחניות כמו שהן למעלה באצי' ונקראו מצות הוי' או אורחות הוי' וכיוצא והן<sup data-n=\"2195\">7</sup> הנק' ג\"כ בשם רמ\"ח אברים דמלכא והוא בחי' רמ\"ח אברים דז\"א ושרשם הראשון הוא נמשך מבחי' תרי\"ג ארחין דא\"א, וע\"כ נקראו ארחו\"ת הוי' כמ\"ש<sup data-n=\"2196\">8</sup> באד\"ר דהיינו כמו מצות סוכה למעלה הוא מ\"ש בסוכות<sup data-n=\"2197\">9</sup> הושבתי בנ\"י שהן ענני כבוד שהן בחי' מקיפי' עליונים דאימא דאצי' כמ\"ש ואשא<sup data-n=\"2198\">10</sup>",[["2190","2","<b>לתורה דשמ\"ע ע\"פ הללו</b>: נדפס לעיל ע' רפה."],["2191","3","<b>להבין מ\"ש בע\"ח</b>: שער מט. וראה ג\"כ אגה\"ק סכ\"ה. לקו\"ת שלח לז, ב. ובכ\"מ. ובכל הבא להלן ראה אוה\"ת דרושים לשמע\"צ כרך ה' ע' ב'קמט ואילך. מאמר זה הובא ג\"כ באוה\"ת תזריע (כרך ב') ע' תצח."],["2192","4","<b>ממ\"ש בזוהר דשרש תרי\"ג המצות. . כת\"ר</b>: ראה זח\"ג קכט, א (ובביאור האריז\"ל שם). מ\"ח מס' א\"א ספ\"ד. פרדס ש\"ח פ\"ג. אגה\"ק סכ\"ט. לקו\"ת ראה כד, א."],["2193","5","<b>בחכ' אתברירו</b>: ראה זח\"ב רנד, ב. ע\"ח שי\"ח פ\"ה ועוד. מבו\"ש ש\"ה ח\"א פ\"ב. אגה\"ק סכ\"ו. סכ\"ח. תו\"א בראשית ה, ג. סידור מד, ד. דרמ\"צ לא, ב. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 206."],["2194","6","<b>אורייתא מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["2195","7","<b>והן הנק' ג\"כ בשם רמ\"ח אברים דמלכא</b>: ראה ת\"ז תי' ל. זח\"ב קיח, א. תניא פ\"ד ובליקוט פירושים ומ\"מ שם."],["2196","8","<b>כמ\"ש באד\"ר</b>: זח\"ג קכט, א. וראה בהנסמן לעיל בריש המאמר."],["2197","9","<b>בסוכות הושבתי את בנ\"י</b>: ויקרא כג, מג."],["2198","10","<b>ואשא אתכם על כנפי נשרים</b>: שמות יט, ד."]]],[2101000339,"אתכם על כנפי נשרים וכתיב כנשר<sup data-n=\"2199\">11</sup> יעיר כו' על גוזליו ירחף כו' שהוא אור אימא דפרישת גדפהא על בנין כו' וכיוצא בזה מצות תפילין למעלה הוא בחי' המשכת מוחי' לז\"א כנ\"ל, ועד\"ז כל המצות שבבחי' האצי' ושרשם הכללי היינו בבחי' ארחין דגלגלתא דא\"א והן בחי' המשכות אור א\"ס מלמעלה באצי' וכמ\"ש בע\"ח דשרש המצות הוא רק להוסיף אור באצי' כנ\"ל, אבל המצות הגשמיי' הנעשות למטה בדברים גשמיי' דנוג\"ה כמו בצמר דציצית וקלף דתפילין וסכך הגשמי דסוכה וכיוצא הן הנה בחי' בירורי נוגה דעשי' שהוא בחי' העלאו' רפ\"ח ניצוצות דתהו כנ\"ל, וזהו כללות התירוץ על הקושי' והסתירה הנ\"ל בענין שרש המצות, ועד\"ז יתורץ גם הסתיר' השני' בענין שרש התורה דשניהם אמת דודאי שרש התורה היא לברר בירורי נוג\"ה משום דבחכ' אתברירו וכמ\"ש להבדיל בין טמא לטהור כו' כנ\"ל, אך זהו דוקא במצות גשמיות דנוגה שגם הן עיקרן רק לברר לאהפכא חשוכא לנהורא כו' שזהו כללות ענין סו\"מ בשס\"ה ל\"ת ועשה טוב ברמ\"ח מ\"ע כידוע, וע\"כ גם בחי' חכמה שבתורה הוא המברר לטו\"ר<sup data-n=\"2200\">12</sup> שבמ\"ע ול\"ת כך וכך יוכשר עפ\"י החכמה וכך וכך לא יוכשר כו' אבל בחי' חכמה שבתורה שלמעלה דהיינו בבחי' ח\"ע דאצי' שאין שם בחי' בירור כידוע<sup data-n=\"2201\">13</sup> בע\"ח דעולם האצי' הוא לאחר התיקון כו' שם בחי' חכמה דאורייתא בבחי' המשכה מעצמות המאציל כנ\"ל דהיינו ע\"י בחי' החכמה דאצי' יהי' אופן ההמשכה<sup data-n=\"2202\">14</sup> של כל מצוה ומצוה מתרי\"ג ארחין דגלגלתא אם כך או כך כו' וד\"ל.\n<b>ולהבין</b> זה בתוס' ביאור הנה שרש פי'<sup data-n=\"2203\">15</sup> לשון תורה הוא לשון הוראה להורות על דבר מה כמ\"ש יורו משפטיך כו', וההוראה תלוי' במי שמורה אם כך או כך, והיינו כאשר יש ב' אופנים אם כך או כך אז צריכים למורה שיורה איך יהי' אם כאופן זה אם כאופן זה, וכך יובן בשרש התורה למעלה באצי' שהוא המורה איך יהי' בחי' המשכה עליונה ע\"י המצוה מבחי' אור הכת\"ר דהיינו איך יהי' הרצון העליון של המאציל אם כך או כך כמו מצות תפילין למעלה שהוא רצון המאציל שיהי' ד' בתים וד' פרשיות, ובזה יהי' המשכות מוחי' דאו\"א לז\"א כנ\"ל, הנה זה הרצון נמשך עפ\"י בחי' החכמה עילאה שנק' בחי' מו\"ס דא\"א (או בחי' חכ' הקדומה דא\"ק כו') להיות המשכות מוחי' דאו\"א לז\"א דוקא ע\"י אופן זה דד' פרשיות שנק' תפילין<sup data-n=\"2204\">16</sup> דמארי עלמא כו' ולא באופן אחר והוא הנק' הוראה שתלוי' במי שמורה כי הי' יכול להיות המשכת רצון המאציל באופן אחר במצות תפילין וגזר החכמה והורה שיהי' באופן כך וכך דוקא ועד\"ז במצות ציצית בטלית ול\"ב חוטין דוקא יומשך ל\"ב נ\"ח ולא באופן אחר וכיוצא בזה בכל המצות הרוחניות דאצי' שנק' רמ\"ח אברי' כו' הכל",[["2199","11","<b>כנשר יעיר קנו</b>: דברים לב, יא."],["2200","12","<b>לטו\"ר</b>: בכת\"י ב: לסו\"מ וע\"ט."],["2201","13","<b>כידוע בע\"ח דעולם האצי' הוא לאחר התיקון</b>: ראה גם ע\"ח שמ\"ג בהקדמה. שמ\"ז פ\"ד. שמ\"ח פ\"ג. לקו\"ת במדבר ג, ג. ביאוה\"ז להצ\"צ ע' רנב ואילך. אוה\"ת בראשית תתמה, א. ובכ\"מ."],["2202","14","<b>ההמשכה של כל</b>: בכת\"י ב: ההמשכה מכל."],["2203","15","<b>פי' לשון תורה הוא לשון הוראה</b>: ראה ג\"כ זח\"ג נג, ב. לקוטי שיחות ח\"ט ע' 462."],["2204","16","<b>תפילין דמארי עלמא</b>: ברכות ו, א."]]],[2101000340,"עפ\"י הוראת חכמת עצמות המאציל, וז\"ש ואהי'<sup data-n=\"2205\">17</sup> אצלו אמון אצלו ממש וכמארז\"ל דהתורה<sup data-n=\"2206\">18</sup> קדמה לעולם אלפיים שנה אפי' לעולם הנאצל כי הרצון להאציל נמשך ג\"כ עפ\"י טעם שבחכ' כו' (אך נק' טעם כמוס שהוא טעם לרצון בהעלם אע\"פ שאין טעם לרצון בגילוי כמ\"ש במ\"א) וד\"ל.\n<b>והנה</b> כתיב ותמלא<sup data-n=\"2207\">19</sup> כד\"ה ותעל שהן כ\"ד ספרים דאורייתא שנמשל לכ\"ד קטן ששואבין בו מים הגדול כך שרש בחי' חכמה שבתורה למעלה כנ\"ל ג\"כ אינו אלא כערך כד מים לגבי עצמות חכמת המאציל דהיינו שלא נתגלה רק בחי' הארה בעלמא מעצמיות החכמה במצות עליונות, והוא אשר מבואר בפע\"ח קצת מן אופני ההמשכות שבמצות למעלה כו' אבל עיקר החכ' חכ' נעלמה היא בהעלם עצמות המאציל כו' רק בבחי' הטעמים והנגיגות שבתורה יש בהעלם קצת מהארת עצמות החכמה שהוא למעלה מבחי' החכ' המלובש להורות אופן המשכות רצון המאציל במצות העליונות כנ\"ל. וביאור הדבר הנה ידוע שיש ד' מדריגות בתורה טנת\"א הנקודות הן בבחי' חכמה, וביאור הדבר הנה ידוע שיש בחכמה ב' מדריגות הא' בחי' גילוי השכל כמו שהוא בא ונמשך מלמעלה מן השכל דוקא שהוא בא בבחי' נקודה בעלמא כברק המבריק עד\"מ והוא אשר אנו רואים שימצא אדם איזה שכל בהברקה בעלמא ועדיין לא בא השכל בהתגלות גמור זהו הנק' בחי' נקודה דחכמה ואח\"כ מתפשט בהתגלות גמור כמו שמן הנקודה ימשיכו קו לאורך ורוחב אבל הנקודה בעצמה היא בהעדר ההתפשטות לגמרי אבל קצת גילוי יש בה בצמצום גדול והוא אשר נתגלה מעט מזעיר מאד מלמעלה מן השכל הנק' העלם השכל כמו שהוא במקורה בכח המשכיל ההיולי שנק' בשם חכמה נעלמה וכך הענין בבחי' נקודות שבתורה שהוא בחי' נקודה דחכמה הבאה בגילוי ממקור החכמה הנק' ח\"ס, אבל מדריגה השנית בחכמה הוא בחי' העלם החכמה כמו שהיא קודם שבאה לידי גילוי כלל וכלל גם לא בבחי' נקודה והיא המתלבשת בהעלם בנגינות וטעמים שבתור' כמו ניגון דזרק\"א מקיף סגולת\"א<sup data-n=\"2208\">20</sup> כו', דהנה הניגון הזה דזרק\"א וכיוצא אינו שייך לגוף האותיות כלל כי ניגון דזרקא על תיבה זו דומה לניגון דזרקא שעל תיבה אחרת כו' מפני שבהעלם גנוז בניגון זה בחי' העלם החכמה שבתיבה זאת ולא בחי' גילוי החכמה כנקודה שהרי הנקודה שייך עכ\"פ אל האות כידוע בענין נקודה קו שטח שמן הנקודה נעשה קו ומן הקו נעשה שטח האות, וא\"כ יש יחוס לאות עם הנקודה וכמו שאמרו למה<sup data-n=\"2209\">21</sup> נקו\"ד על וישקה\"ו כו' ומכש\"כ התגי\"ן של האותיות שהי'<sup data-n=\"2210\">22</sup> ר\"ע",[["2205","17","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["2206","18","<b>דהתורה קדמה אלפיים שנה לעולם</b>: ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. וש\"נ. תו\"א בראשית א, א. הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ ת\"ש ע' 83, ובסה\"מ תשי\"א ע' 262."],["2207","19","<b>ותמלא כדה ותעל</b>: בראשית כד, טז. וראה ת\"ז תכ\"א (מו, ב). אוה\"ת בראשית מח, א. וראה לעיל ע' ב."],["2208","20","<b>סגולתא</b>: בכת\"י ב: שופר סגולתא. ובכת\"י ג: מקף סגולתא."],["2209","21","<b>למה נקו\"ד על וישקה\"ו</b>: אדר\"נ לד, ד. זח\"ב קכד, ב. ובכ\"מ. ובהבא להלן ראה ג\"כ תו\"א מקץ לב, א. סה\"מ תקס\"ח ע' רנא ואילך. סידור קלו, ג. עט\"ר נט, א. ובכ\"מ."],["2210","22","<b>שהי' ר\"ע דורש עליהם תלי תלים</b>: מנחות כט, ב."]]],[2101000341,"דורש עליהם תלי תילי' של הלכות כו', אבל על הטעמים והנגינות לא מצינו שום דרש כלל כי הוא העלם גמור, וזהו שאמר בע\"ח<sup data-n=\"2211\">23</sup> דשרש הטעמים הוא בבחי' הכת\"ר ושרש הנקודות הוא בבחי' החכמה כו' וד\"ל. אך<sup data-n=\"2212\">24</sup> לפעמים מצינו בע\"ח דהטעמים הוא<sup data-n=\"2213\">25</sup> בבחי' החכמה, אך הענין הוא דשניהם אמת שהוא בחי' הארת הכתר בחכמה כו'. וביאור הדבר הנה עד\"מ כאשר א\"א לאדם להסביר איזה שכל עמוק בדיבור לזולתו גם שהוא חכם גדול הנה יוכל לכוין לו העומק ההוא ע\"י רמז כי גם שבאותיות א\"א להלביש כי לא יכילו אותו אבל ברמז יתלבש, וכיוצא בזה ג\"כ בנגינות וטעמים דגם שא\"א שיאיר אור העלם החכמה גם בבחי' נקודה ע\"ג האותיות, אבל בניגון שהוא תנועת והמשכת קול בעלמא יוכל להתלבש בו, אך הוא שם בהעלם גדול מושלל מכל בחי' השגה אפי' כנקודה וברק בעלמא אינו מושג והמופת לזה מן השיר שבניגון שבו יכווין אדם אל בחי' העלם השכל אשר הוא למעלה מן ההשגה לגמרי כו' כמ\"ש במ\"א והוא הנק' בחי' הארת הכתר בחכמה שהוא בחי' מקור השכל כמו שהוא בהעלם בכח השכל, אך הוא מאיר למטה בניגון וכיוצא וגם הוא כלא חשיב לגבי עצם החכמה הנעלמה שנק' כח המשכיל העצמי שהוא בחי' ח\"ס עצמו כנ\"ל, וע\"כ הטעמים לפעמים בחכמה בלבד כו' וד\"ל. ובכ\"ז יובן ענין הנ\"ל בפי' ותמלא כד\"ה כו' שגם כ\"ד ספרים דאורייתא שהוא בחי' החכמה להורות אופן המשכות רצון המאציל במצות עליונות כלא חשיב לגבי עצם החכמה כו', והיינו בחי' נקודה דחכמה השייך לאותיות כנ\"ל אבל בבחי' הטעמים והנגינות שבה יש בהעלם מבחי' עצמות ח\"ס כמו עד\"מ שהעומק השכל מלובש ברמז וכה\"ג וגם זאת אינו אלא הארה בעלמא וז\"ש ויהי<sup data-n=\"2214\">26</sup> שיר\"ו חמשה ואלף כו' וכמ\"ש ובלילה<sup data-n=\"2215\">27</sup> שיר\"ה עמי כו' ונק' רננה דאורייתא שהוא למעלה מגוף אותיות התורה כנ\"ל בענין טנת\"א כו' וד\"ל.\n<b>והנה</b> ידוע שהתענוג הוא מקור הרצון שהרי לפי ערך התענוג בדבר מה כן יתפשט הרצון אליו כידוע וכך הוא למעלה בבחי' המשכות רצון העליון שבמצות עליונות הנה בחי' התענוג הוא פנימי' מקורן ושרשן (והוא בחי' י\"ג חיוורת' דע\"י שהוא פנימי' התרי\"ג ארחין כו' כידוע), וא\"כ מובן שלפי אופן התענוג כך יומשך הרצון. והנה ידוע ג\"כ שהתענוג מתלבש בחכמה (וע\"כ נק' גם החכמה טעם כלומר תענוג) וכנראה בחוש שבהתענג אדם בדבר מה ראשית גילוי העונג הוא בשכלו אמנם אין זה רק בחי' גילוי העונג מעצמות העונג הנעלם והגילוי עונג הזה שמתלבש בשכל הוא המקור לרצון דהיינו לעוררו שיתפשט לפי אופן גילוי זה העונג ממש כנ\"ל. וכך יובן למעלה בבחי' שרש החכמה שבתורה למעלה שהיא גוזרת על אופן המשכות רצון המאציל כנ\"ל שהוא עפ\"י אופן בחי' גילוי העונג שבה דוקא, והוא רק בחי' נקודה דחכמה שבה גילוי העונג מצומצם מאד והיינו ע\"י בחי'",[["2211","23","<b>בע\"ח דשרש הטעמים הוא בבחי' הכתר</b>: שער טנת\"א פ\"ב. ובכ\"מ."],["2212","24","<b>אך לפעמים מצינו בע\"ח דהטעמים הוא בבחי' דחכמה</b>: ראה ע\"ח שער אבי\"ע רפ\"א ועוד. וראה אוה\"ת ראה כרך ה' ע' ב'מח."],["2213","25","<b>הוא</b>: בכת\"י ב נוסף בכתיבה מאוחרת: ג\"כ."],["2214","26","<b>ויהי שירו חמשה ואלף</b>: מלכים-א ה, יב."],["2215","27","<b>ובלילה שירה עמי</b>: תהלים מב, ט."]]],[2101000342,"שערות שנק' מזלות דא\"א כמ\"ש<sup data-n=\"2216\">28</sup> בע\"ח דאור אבא יונק ממזל הח' וכיוצא דהיינו שמקבל בחי' המשכות העונג העליון שברצון העליון בבחי' צמצום שערות בלבד וד\"ל. וזהו שרש ענין התורה שלמעלה אשר<sup data-n=\"2217\">29</sup> המלאכים ביקשו תנה הודך על השמים כו' דהיינו בחי' המשכות השגות טעמי המצות העליונות שנמשכי' מתרי\"ג ארחין כנ\"ל, והוא אשר נמשך רק ממותרי מו\"ס כו' אבל בבחי' הנגינה והטעמים מלובש עצם התענוג כמו שהוא למעלה בעצמות המאציל (והוא בחי' י\"ג חיוורת' הנ\"ל) וע\"ז מרמזי' הנגינות שבטעמים כמו זרק\"א כו' שהוא אופן המשכות התענוג הפשוט שלמעלה מבחי' גילוי התענוג בחכמה שנק' נקודה כו' ולפי אופן המשכות זה העונג העצמי כן מורה הנגיגה והטעם שעל התיבה (וכמ\"ש<sup data-n=\"2218\">30</sup> בע\"ח דכלל גדול הוא דפנימי' אבא הוא פנימי' עתיק כו' ופנימי' אבא הוא בחי' מו\"ס עצמו והוא בחי' העונג הפשוט כו' וד\"ל), והוא למעלה הרבה מבחי' גילוי העונג בחכמה להורות אופן המשכת הרצון.\n<b>אך</b> הנה לכאורה יש להבין דהלא ידוע דבחכ' אתברירו דהיינו איך יוכשר כל מצוה לעשותה באיזה אופן פרטי א\"כ בהכרח שיש בה מבחי' הארת עונג הפשוט להכריע איזה תענוג יומשך בגילוי להיות מזה התעוררות רצון שהרי אם החכמה תגזור אומר שאין זו מצוה כלל הרי אין כאן לא רצון ולא עונג לרצון ועד\"מ באדם כשצריך לברר<sup data-n=\"2219\">31</sup> אם יהי' לו עונג מדבר מה שבהכרח שיברר בשכלו אם יומשך עונג לדבר זה ממקור העונג הנק' תענוג הפשוט הרי בהכרח שכח השכל מגיע אל עצם<sup data-n=\"2220\">32</sup> תענוג הפשוט כו'. אך הענין הוא דבאמת נמשך בכח החכמה במקורה שנק' מו\"ס הארת עונג הפשוט (וכנ\"ל דפנימי' אבא הוא פנימי' ע\"י כו') אך שבנקודת החכמה הבאה בגילוי לא נמשך רק אפס קציהו כו' כנ\"ל, ולפ\"ז מקור כל הבירורי' שע\"י החכמה דוקא היינו ע\"י בחי' מו\"ס דוקא שהוא המברר באיזה אופן יבא העונג והרצון כו' והוא למעלה גם מבחי' העונג שמלובש בנגינות וטעמים שאין שם אלא הארה בעלמא מעצם התענוג כנ\"ל ובכח חכמה המברר לעונג בהכרח שיש בו מפנימי' העונג יותר כו' וד\"ל. ובכ\"ז יובן המאמר דהשיב הקב\"ה למלאכים שבקשו תנה הודך על השמים כו' כלום יצה\"ר יש בכם גזל או רציחה כו' דהנה עיקר המשכות העונג בחכ' למעלה במצות העליונות הוא להוסיף אורות באצי' בלבד כנ\"ל באריכות אבל מצות הגשמיות שנעשות למטה הוא רק לברר בירורי נוג\"ה כנ\"ל ומבואר למעלה ג\"כ בתירוץ הסתירה השני' שבחכ' אתברירו שא' על התורה היינו במצות גשמיות אבל למעלה באצי' עיקר התורה להמשיך אור כו' אמנם הנה יש להבין לכאורה בזה דהלא אם תגזור החכ' שבתורה דבריאה למטה שהסוכה פסולה",[["2216","28","<b>כמ\"ש בע\"ח דאור אבא יונק ממזל הח'</b>: ש' א\"א ספ\"ט. ש' או\"א ספ\"ח. ש' הזווגים ספ\"ב. ש' הולדת או\"א וזו\"ן פ\"ו. ש' העבורים פ\"ב. ש' הנסירה ספ\"ג."],["2217","29","<b>אשר המלאכים ביקשו תנה הודך</b>: שבת פח, ב."],["2218","30","<b>וכמ\"ש בע\"ח. . דפנימי' אבא הוא פנימי' עתיק</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ ת\"ש ע' 49."],["2219","31","<b>לברר</b>: בכת\"י ב: לכרוח."],["2220","32","<b>עצם</b>: בכת\"י ב: עצם כח."]]],[2101000343,"וכדומה הרי אין בה רצון העליון כלל גם למעלה באצי' ולא נמשך תוס' אור באצי' כלל, א\"כ הרי הא בהא תליא דהוספת האור באצי' תלויה בתורה של מטה וא\"כ מה חילוק יש ביניהן לומר שתורה של מעלה אינה לברר בירורי' רק להוסיף אור כו' ולהורות על אופן גילוי התענוג והרצון כו' כנ\"ל, ותורה שלמטה באה לברר בירורי' כו'. אך הענין הוא דבאמת עיקר התורה הוא רק לברר בירורי נוג\"ה שנפלו בשבה\"כ וכמ\"ש להבדיל בין טמא לטהור כו' ומה שלמעלה באצי' נק' התורה לשון הוראה להורות על אופן גילוי התענוג והרצון כנ\"ל אין זה בחי' תענוג ורצון סתם אלא בחי' התענוג והרצון להיותו מתהפך חשוכא לנהורא כו' שהוא בחי' הבירורים כידוע והוא הנק' הוספת אור חדש באצי' וזה תלוי בחכ' שבתורה שלמעלה במו\"ס עצמו כנ\"ל, אמנם אין זה נק' בירור באצי' אחר שהאצי' הוא לאחר הבירור כנ\"ל רק שהוספת אור זה באצי' הוא כדי שיומשך בבי\"ע ויתברר ויתהפך חשוכא לנהורא כו' והוא ע\"י שם מ\"ה שמברר לב\"ן כו' שזהו ענין בחכ' אתברירו וע\"כ כשחכמה שבתורה למטה גזרה שהסוכה פסולה וכה\"ג גם למעלה לא בא תוס' אור ע\"י סוכה כזאת כי שרש החכ' שבתורה דבריאה הוא בבחי' מו\"ס עצמו ולא גזר חכמה של מעלה שיהי' רצון ועונג בזה כלל גם למעלה והא בהא תלי' כנ\"ל רק שבחי' חכ' שבתורה דאצי' מוספת אור ולא שתברר ממש, ובבי\"ע היא המבררת בירורי נוג\"ה עי\"ז כו' וד\"ל.\n<b>וזהו</b> שהשיב להם הקב\"ה כלום יצה\"ר כו' כי המלאכים דאצי' ודבריאה כו' בקשו להשיג בחי' עונג העליון שבמצות העליונות ע\"פ הארת מו\"ס עד בחי' חכ' דזו\"נ כו', והשיבם שעיקר הארה זו רק לברר בירורי נוג\"ה בעשי' בסו\"מ וע\"ט בפ\"מ לאהפכא חשוכא לנהורא כו' וכל הוספת אור באצי' הוא רק בשביל זה ומאחר שאין לכם מה לברר כי אין יצה\"ר שולט בהם למה תבקשו<sup data-n=\"2221\">33</sup> הוד אור זה כו' וד\"ל. ונמצא מובן מכ\"ז דאין הפרש בין מצות העליונות למצות התחתונות רק שבאצי' המצות הן רק בחי' עונג ורצון העליון ממש כמו שהוא למעלה ובבי\"ע הוא בא בהתלבשות בדברים גשמיי' כמו בצמר דציצית כו' ועד\"מ עונג המלך שיעשו לו בנין נאה כך וכך הרי העונג שבעצמות נפשו מתגלה כשעשו לו הבנין בגשמיות המעשה כשעושי' רצונו כו' וגם בבחי' החכמה המברר לעונג ורצון אין הפרש רק שבאצי' מברר לבחי' עונג העליון כמו שהוא למעלה ולמטה בבי\"ע החכ' הזאת מבררת פועל המעשה והוא חכמה שבתורה להבדיל בין טמא כו' דהיינו אם יעשו הסוכה כך וכך יוכשר וישכון בה גילוי אור מקיף בסכך שנק' צילא דמהימנותא כו' והסכך הגשמי מתברר מנוג\"ה כו' ואם לאו הסוכה פסולה כו' וד\"ל.\n<b>(ומעתה</b> יש להבין מ\"ש<sup data-n=\"2222\">34</sup> רש\"י ע\"פ ישקני מנשיקות פיהו שהם טעמי מצות שלא נתגלו עכשיו אלא לעתיד, אם הכוונה על בחי' טעם החכמה שמברר להמשכת הרצון והעונג כנ\"ל ששרשו בבחי' מו\"ס עצמו<sup data-n=\"2223\">35</sup> שבו מאיר מפנימי' העונג כנ\"ל ע\"כ אינו מתגלה עכשיו גם באצי' אלא לעתיד או על הוספת האור באצי'",[["2221","33","<b>תבקשו הוד</b>: בכת\"י ב: תבקשו עוד הוד."],["2222","34","<b>מ\"ש רש\"י ע\"פ ישקני מנשיקות פיהו</b>: שה\"ש א, ב. פירש\"י שם."],["2223","35","<b>עצמו שבו מאיר</b>: בכת\"י ב: עצמו הוא מאיר."]]],[2101000344,"קאמר דלעתיד יתגלה גם למטה ועכשיו מאיר באצי' ושרשו מבחי' אור אבא שמקבל ממזל הח' שהוא בחי' חכ' שנק' נקודה שבה גילוי העונג בצמצום כו', וכן מ\"ש בעדן<sup data-n=\"2224\">36</sup> עי\"ן לא ראתה כו' יש להבין אם הכוונה על בחי' עונג הפשוט שמאיר בח\"ס כנ\"ל או על בחי' גילוי העונג המצומצם בנקודת חכמה כנ\"ל וד\"ל<sup data-n=\"2225\">37</sup>).\n<b>וגם</b> עוד יש להבין בכמה מקומות שנז' בפע\"ח שהפלפול בתורה בקושיות ופירוקים הוא לברר בירורי נוג\"ה כי כל קושי' מסט' דקליפה כו', והאריז\"ל<sup data-n=\"2226\">38</sup> הי' מקשה עד שמזיע כדי לשבר כח הקליפה כו' איך הוא למעלה בתורה דאצי' שאין שם בירור כנ\"ל רק שהחכ' נק' בשם מורה להורות אופני ההמשכות מבחי' רצון ועונג העליון כנ\"ל אם ענין הפלפול הוא כמו ענין הבירור שבחכמה להבדיל בין טמא כו' הרי מבואר למעלה דהא בהא תלי' שהרי הסוכה שנפסלת למטה עפ\"י החכ' דתור' שלמטה כך למעלה אינה מצוה כלל כו', וא\"כ גם בענין הפלפול הא בהא תלי' דכמו שהפלפול הוא ענין בירור וליבו\"ן הלכתא למטה כך למעלה הוא בירור וליבון באופני רצון העליון שנקראו בחי' שערות ועל הבירור הזה נאמר סלסלה<sup data-n=\"2227\">39</sup> ותרוממיך כו' וכמ\"ש במ\"א, אך א\"כ מה הי' חטא מי מריבה על שהכה לצור ויזובו מי החכמה ולמה לא אמרו אל הצור שיזוב כו' הלא ע\"י ההכאה הוא כמו ענין הפלפול שמתברר עי\"ז יותר כמ\"ש במ\"א. וצריך לומר שאין הפלפול דומה לבירור סתם שע\"י החכ' כי מ\"ש להבדיל בין קדש לחול כו' עפ\"י החכמה העליונה היינו עד\"מ אדם שמורה עפ\"י ההשכלה ברורה מכבר שכבר הבחין בין טוב לרע רק שמורה זה יוכשר וזה לא יוכשר ואע\"פ שיוכלו לסתור הדבר בכמה קושיות להפוך סברתו לא ישמע להם כי זה הדבר כבר הוברר אצלו וזהו הנק' חכמה ברורה וכמ\"ש כל<sup data-n=\"2228\">40</sup> אמרת אלוה צרופה כו', וע\"ז אמרו בכמה דוכתי דבחכמה אתברירו פי' כבר הוברר בחכמה בין טמא לטהור כו', אבל הפלפול והעיון<sup data-n=\"2229\">41</sup> הוא כאשר עדיין לא הוברר בחכמה אם יוכשר אם לאו ויש הרבה טעמים לאיסור והרבה טעמים להיתר ונק' מ\"ט פנים טמא ומ\"ט פנים טהור כו' והוא הפלפול והעיון לתרץ כל קושי' המנגד אל האמת ומבלבלו עד\"מ השערות הנדבקות יחד שצריך להפרידן בסלסול כך העיון לברר דבר מדבר ולהעמיד כאו\"א על שרשו כמו לא קשיא כאן כו' וכמ\"ש במ\"א הנה זהו לא נק' בירור מכבר אלא שמתברר ע\"י העיון ויוצא לאור לאחר הבלבול כו' והוא כמו שהכו לצור שיזוב מים ע\"י ההכאה דהיינו הפלפול שמברר את התערובות ולזה הי' החטא כי זה לא שייך רק בבחי' נוג\"ה ששם יש קושי' מסט' דקליפה המבלבל כו' וצריך שיבררו ע\"י העיון וזהו מצוה בת\"ת בפ\"ע לשבר הקליפה כמו שהאריז\"ל הי' מקשה עד שמזיע כו' אבל אין זה דומה כלל לבחי' בירור שע\"י החכ'",[["2224","36","<b>בעדן עי\"ן לא ראתה</b>: ראה ברכות לד, ב. זח\"ג כד, א. אגה\"ק ס\"ה (קז, א) ובליקוט פירושים ומ\"מ שם."],["2225","37","<b>וד\"ל)</b>: בכמה כת\"י אין כאן מוסגר."],["2226","38","<b>והאריז\"ל הי' מקשה</b>: ראה שער המצות וטעהמ\"צ פ' ואתחנן. פע\"ח שער הנהגת הלימוד."],["2227","39","<b>סלסלה ותרוממך</b>: משלי ד, ח. וראה תו\"א מקץ לא, ד. ותו\"ח ואוה\"ת שם. לקו\"ת אחרי כז, א. ובכ\"מ."],["2228","40","<b>כל אמרת אלוה צרופה</b>: משלי ל, ה."],["2229","41","<b>העיון</b>: בכת\"י ב: העיון והפלפול."]]],[2101000345,"להבדיל כו' למעלה שאין שם קושי' ובלבול כלל כי כבר הוברר רק שמורה איך יומשך הרצון כמשל אדם שיודע כבר פסק ההלכה בבירור גמור רק שמורה אם כשר או פסול כו' כמו המורה את הדרך שכבר נודע בה כו' וכמ\"ש יורו משפטיך כו' והוא שרש ענין חכמה דתורה דאצי' ומ\"ש סלסלה כו' קאי על חכ' שלמטה שמברר את התערובות מצד סט' דקליפה, וע\"כ<sup data-n=\"2230\">42</sup> א' בר\"מ דלעתיד יתעבר אילנא דטו\"ר אסור טמא ופסול כו' ולא יצטרך לפלפול אלא הלכות כמו שהן ברורים גם לעתיד יהיו וכמ\"ש<sup data-n=\"2231\">43</sup> במ\"א ע\"פ מזמור לתודה הריעו לה' כל הארץ ר\"ת הלכה כו'. ובכ\"ז יובן ההפרש בין מצות קריאה שהן כבר ברורים למצות עיון כו' (דלא כמ\"ש במק\"מ ב' הרמ\"ז במצות עיון ע\"ש) ואעפ\"כ אם עפ\"י פלפול נפסק לפסול גם ההלכה למעלה באצי' כן כי מה שעפ\"י הפלפול עתיד להתברר הוא שכבר הוברר כו'.\n<b>וזהו</b> שארז\"ל במי<sup data-n=\"2232\">44</sup> ששונה הלכות בכל יום מובטח לו שהוא בן עוה\"ב לפי שעוה\"ב הוא אחר הבירור כו' וד\"ל (ובכ\"ז יובן מ\"ש בעיקר חטא מי מריבה על שלא רצו להקדישנ\"י לעיני בני ישראל, פי' בבחי' קדש העליון דחכמה דאצי' שיהי' גם למטה כמו למעלה כו' וד\"ל).\n<b>והנה</b> יש להבין בתוס' ביאור שרש ענין בירורי נוג\"ה, ומזה יובן ג\"כ בתוספות ביאור שרש ענין להוסיף אורות באצי' הנז' בע\"ח, דהנה ידוע בענין השבירה שהן ז' מדות דתהו שנקראו ז' מלכים קדמאין וכמ\"ש ואלה המלכים כו' וימלוך וימת כו' ונפלו הכלים בעולם הבריאה ונמשך מזה בחי' נוג\"ה וזהו ענין בירורי נוג\"ה כידוע, והנה<sup data-n=\"2233\">45</sup> מבואר בע\"ח בסיבת שבה\"כ דז' מלכים שמתו ונפלו כו' שהוא מפני שהי' בחי' אורות דתהו בריבוי ותוקף גדול והכלים היו במיעוט שלא לפי ערך האור ע\"כ לא יכלו הכלים לסבול את האור ונפלו ונשברו כו'. וביאור הדברים ידוע ומבואר במ\"א שענין ריבוי האור ותקפו הוא ענין ריבוי האור והחיות להיותו בחי' נקודה עצמי' ושרשי' כמו עד\"מ המדות הטבעי' באדם שהן נולדים באדם בטבע תולדתו כמדת הרחמנות או האכזריות וכיוצא שהן בחי' עצמי' מעצם ומהות הנפש, וכל בחי' עצם הוא בא בתוקף גדול דהיינו שלא ישתנה גם לפי שעה ולא יפיג טעמו ולא יכלה כחו לעולם שהרי אנו רואים שא\"א שיהפוך האדם טבע מדותיו לגמרי מן הקצה לקצה מרחמנות לאכזריות או מפזרנות לקמצנות וכיוצא רק שיכניע אחת מהנה עפ\"י השכל, אבל לא שהעצם ישונה ממהות למהות היפוכו. והנה עוד זאת אנו רואים שטבע המדות להיותם בחי' עצמי' ושרשי' אשר ע\"כ כחם גדול וחזק מאד כנ\"ל ע\"כ לא יבאו בהתחלקות לחלקי' ואופנים שונים ג\"כ אלא כאו\"א אור וחיות",[["2230","42","<b>וע\"כ אמר בר\"מ דלעתיד יתעבר</b>: זח\"ג קכד, א ואילך. וראה אגה\"ק סכ\"ו."],["2231","43","<b>וכמ\"ש במ\"א ע\"פ מזמוד לתודה</b>: תהלים ק, א. ראה סידור מד, ג ואילך. אוה\"ת נ\"ך כרך ב' ע' תתקעג ואילך."],["2232","44","<b>במי ששונה הלכות בכל יום. . עוה\"ב</b>: מגילה כח, ב. ובכ\"מ. וראה אגה\"ק סכ\"ט. לקו\"ת שה\"ש כט, ד."],["2233","45","<b>והנה מבואר בע\"ח בסיבת שבה\"כ</b>: ראה מבו\"ש ש\"ב ח\"ג פ\"ז. תו\"א נח ט, ג. סה\"מ תקס\"ח ע' ה ואילך. תו\"ח בראשית ט, א ואילך. ובכ\"מ."]]],[2101000346,"פשוט מבלתי מתחלק בריבוי המשכות שונות זו מזו אלא הוא עצם אחד פשוט כו' כמו מדת הרחמנות במי שטבעו רחמני מאד הנה ירחם על הכל גם על הרוצח או על החוטא לו ועשה לו רעה עד לחיי נפשו ג\"כ ירחם עליו מצד טבע הרחמים שבלבו, וא\"א לו לחלק המדה הזאת לחלקים ואופנים שונים לומר באופן כך יומשך ולא באופן אחר כמו למי שאינו ראוי לרחמים כמו הרוצח או שונאו וכה\"ג שאסור לרחם עליו וראוי שיתאכזר עליו, אך הטבע הוא עצם א' פשוט בלתי מתחלק כלל, וכן בתינוק קטן שמדותיו הטבעיים כולם אינם מתנהגים ונכנעים תחת השכל כלל ג\"כ לא יתחלקו המדות אצלו כנראה בחוש שכאשר יחפוץ ויתאוה התינוק לדבר מ\"ה אע\"פ שיזיק לו מאד לא ימנע כלל וכן במי שרעב ג' וד' ימים הרי הטבע הרעבון גובר שיאכל גם דברים הרעים המזיקים או כמו תאוה הגופני' ברוב אכילה ותשמיש שגם שיזיקו לו א\"א לו לעמוד על נפשו כו' וכל אלה וכיוצא הן דמיון ומשל לבחי' מדות דתהו שנפלו בשבירה שהן ג\"כ בחי' אורות תקיפים וחזקים כנ\"ל דהיינו שנאצלו בבחי' עצמיות מעצם אור המאציל וכל עצם לא ישונה כמו שנאצל מדת החסד או הרחמים הנה הוא מציאות אור חסד פשוט להיותו עצמי בלתי מתחלק כלל לכמה מיני המשכות מחולקות אלא הוא עצם א' פשוט, וכמו שאמרו דורו<sup data-n=\"2234\">46</sup> של אנוש ניזונין בחסדו של הקב\"ה אע\"פ שעע\"ז כו' או כמו מאריך<sup data-n=\"2235\">47</sup> אף לרשעים כו' וכה\"ג וד\"ל, וכ\"ז נק' האור בריבוי והכלי במיעוט פי' האור הוא בחי' המשכה עצמי' מעצמות אור המאציל ובחי' הכלי הוא בחי' התפשטות אותו האור והתלבשותו בכמה ענינים חלוקים כמו מדת החסד והרחמי' שהוא אור היולי ופשוט ובבוא איזה ענין מה שתתלבש שם מדה זו כמו על עני ומדוכא וכה\"ג שאז יתפשט האור ויתלבש בדבר זה אז נק' בחי' הכלי של האור (אמנם התפשטותו והתלבשותו באיזה דבר הרי מתלבש כמו שהוא בלתי התחלקות באופן כך ולא באופן כך כנ\"ל, ומה שמדה\"ר יכולה להתפשט בכמה ענינים חלוקים אין זה נק' התחלקות בעצם המדה רק שמתלבשת בכמה מיני לבושים כמו אור השכל לפעמים מתחכם בענין זה ולפעמים בענין אחר שזהו כמו אדם שלובש ופושט ולובש כו' כידוע וד\"ל) ומה שנק' למעלה מיעוט הכלי היינו שאינו מתחלק כלל באופנים שונים אלא רק כמו שהאור בעצם כך יתפשט ויתלבש ויתגלה וכ\"ז להיות בחי' עצמי' אשר כחו גדול וחזק כנ\"ל ע\"כ אין המדה מתחלקת לי' אלא רק א' היא וגם היא במיעוט ההתפשטות עד שלא תכיל את האור כי רב הוא ממנה וע\"כ נקראו ע\"ס דתהו בשם יו\"ד נקודות כמ\"ש בע\"ח כמו הנקודה שמצומצמת מאד ואין לה התפשטות כלל לאורך ורוחב ימין ושמאל ואין לומר שהנקודה אין בה גילוי כלל שהרי נקוד במיעוט עכ\"פ רק שהגילוי הוא מצומצם ואין לו התפשטות כלל, ולמעלה הוא הנק' מיעוט הכלי לגבי ערך האור. ויובן זה עד\"מ ממדת הרחמים של מלך גדול על עני ושפל הערך שלפי ערך הארת מדה\"ר לפי ערך גדולת המלך הרי הי' נותן לו גנזי מלכים מאבנים טובות וכה\"ג והעני אין הכלי שלו סובל ריבוי טובה כזאת שלמעלה מערכו לגמרי אלא יקבל לחם ובגדים פשוטים המתייחס לערכו וכיוצא בזה בהשפעת שכל מחכם גדול לתינוק קטן",[["2234","46","<b>דורו של אנוש</b>: ראה פסחים קיח, א."],["2235","47","<b>מאריך אף לרשעים</b>: סנהדרין קיא, א. ובכ\"מ."]]],[2101000347,"שאין כלי הקטן מכיל ריבוי אור שכל הגדול רק אם יצמצם השכל לפי ערכו הקטן מאד אזי יקבל כו' וכן מי שדעתו וכלי מוחו קצרה לא יוכל לקבל עומק שכל מופלא שלמעלה מערכו אז ממילא יתבלבל כלי מוח המקבל ולא יקבל כלום אלא יסתלק אור השכל של המשפיע למקורו והכלי של המקבל אינו מקבל רק אפס קציהו כי לא יוכל להכיל את כל השפע כי רב הוא ממנו כו'. וכל אלה דמיונות ומשלים להבין ענין יו\"ד נקודות דתהו שהוא מפני תוקף וריבוי האורות לא נתגלו בבחי' הכלים רק מעט מזעיר כנקודה בעלמא בלבד והוא הנק' מיעוט הכלי שאינו מתפשט לחלקי' כלל כו' כנ\"ל וכנ\"ל במדות הטבעיי' שהמדה עצם א' ופשוט והתגלותה ג\"כ אינו אלא אפס קציהו כי לא יכול הדבר שמתלבש בו מדת החסד להכיל כל החסד הטבעי, אמנם מה שנגלה בו בלתי מתחלק כמו העצם כמו שאין העצם מתחלק אחר שנתגלה בבחי' צמצום כנקודה שאין לה התפשטות כלל. ויובן זה יותר עד\"מ הארת השכל שאינו מתיישב בדיבור מפני עומקו כי אורו רב ולא יכילנו כלי הדיבור כלל ירמוז ברמז ויבין אותו הרי הרמז לא שמכיל כל עצם עומק השכל רק אפס קצהו אבל מ\"מ יכוין בו אל העומק אמנם מבלי התפשטות כלל לחלקים כו' והרי הרמז לגבי עומק המושג נק' מיעוט הכלי לגבי ריבוי האור כו' וד\"ל. (אך יש להבין למה דוקא מפני ריבוי האור נעשה מיעוט הכלי כמו שע\"י ריבוי הכלי הוא מיעוט האור כמשי\"ת)<sup data-n=\"2236\">48</sup>. אך הענין הוא כמ\"ש במ\"א דכל שהאור יותר גבוה הכלי שלו יותר קטן וראי' מאור השכל שהוא גבוה מכל הכחות והכלי שלו קצר הכמות כו' וכמו שאנו רואים כל מי שדעתו עמוקה יותר יותר יהי' דברי' מועטים כי לפי עומק ורוחב דעתו נראה לו הדבר לקטן הערך עד שא\"צ פירוש ואריכות כלל ע\"כ יאמרנו בדיבור א' או בשתיים ולא יותר משא\"כ תלמידו הקטן הימנו יפרש הדבר באריכות יותר והקטן ממנו יאריך יותר בדברים הרי לפי קוטן הדעת יגדל הכלי שהוא הדיבור יותר ולפי גודל הדעת יקטן הדיבור (וכמ\"ש<sup data-n=\"2237\">49</sup> במשה כבד פה כו' ובהיפוך במוחי' דקטנות ירבה הדיבור יותר כמו שאמרו נשים<sup data-n=\"2238\">50</sup> דברניות הן לפי שנשים<sup data-n=\"2239\">51</sup> דעתן קלה כמ\"ש במ\"א באריכות וד\"ל).\n<b>והנה</b> ענין השבירה באה מחמת שני טעמים, הא' מחמת ריבוי האור ותקפו ע\"כ לא יכול הכלי לסבול וירד גם המקצת מן האור עם הכלי והן רפ\"ח ניצוצות שנפלו עם הכלי' כידוע, והב' מחמת מיעוט הכלי, ויש להבין ענין וביאור שתי סיבות אלה. והנה מה שיוכל להיות סיבת השבירה גם באור במקצת מצד ריבוי האור ותקפו זה יובן מענין מה<sup data-n=\"2240\">52</sup> שמצינו בלוחות ראשונות שהי' גילוי אור תקיף ביותר אשר ע\"כ הי' שליטת עין הרע לנחש הקדמוני בזה והחטיא לישראל בחטא העגל ונשתברו הלוחות כו' ומזה יובן בכל בחי' גילוי אלקות בבחי' התגלות ביותר מדאי לכל עין הרואה שיוכל לשלוט בזה קנאה של נחה\"ק וכו', ואע\"פ שמצינו גילוי",[["2236","48","<b>כמשי\"ת)</b>: בכמה כת\"י אין כאן מוסגר."],["2237","49","<b>וכמ\"ש במשה כבד פה</b>: שמות ד, י. וראה תו\"א ויצא כג, א. שמות נב, ב. ובכ\"מ."],["2238","50","<b>נשים דברניות הן</b>: ברכות מח, ב. ובכ\"מ."],["2239","51","<b>שנשים דעתן קלה</b>: שבת לג, ב. ובכ\"מ."],["2240","52","<b>מה שמצינו בלוחות ראשונות</b>: ראה לקו\"ת להאריז\"ל פ' תשא. לקו\"ת בחוקותי מח, ב. האזינו עב, ד. תו\"ח בראשית טז, א."]]],[2101000348,"אלקות יותר לכל ההמון בימי דוד ושלמה ולא שלט עין הרע בהן היינו מפני שלא הי' הגילוי כמו שהוא למעלה ממש רק בלבושים ומסכים הרבה, אבל גילוי אא\"ס שבלוחות הראשונות הרי הי' מחמת בחי' ההפשטה מכל גשם כמו קודם חטא אדה\"ר כו' כמ\"ש רז\"ל חרות<sup data-n=\"2241\">53</sup> על הלוחות חירו\"ת ממ\"ה<sup data-n=\"2242\">54</sup> כו' כדוגמת<sup data-n=\"2243\">55</sup> העוה\"ב ממש שאין בו גשם אכילה ושתי' כו'. ומעתה הרי יש להבין למה שלט העין הרע בלוחות הראשונות הרי כל סט' דקליפה הוא בבחי' יש נפרד לגמרי כידוע ומאיזה צד יהי' לו אחיזה ושרש אז כו'. אך הענין הוא לפי שהי' בחי' הגילוי הגדול הזה בבחי' יש מורגש מאד לכל, אע\"פ שהי' הגילוי ממקום ומדריגה היותר גבוה אך כל בחי' יש אפי' בסט' דקדושה יש מקום לעין הרע לשלוט והוא קנאה של נחש כו' כמו באדה\"ר שנתקנא בו נחש להיות שהי' גילוי אלקות מדבר בו בבחי' יש מורגש בהתגלות יותר מדאי כו' ובכל בחי' יש ודבר מה גם שהוא מסט' דקדושה יש מקום לסט' דקליפה לקנאות בזה ומזה יבא סיבת העדר גילוי האור והסתלקותו עד\"מ המלך שאוהב את עבדו הנאמן יותר מדאי אם יתגלה בכל לבבו הנאמן אליו ויתגלה<sup data-n=\"2244\">56</sup> באהבתו אליו יתקנאו בו ומוכרח להעלים ולהסתיר את האהבה בכמה לבושים שונים והוא להקטין אותו בכל מה שיוכל בכדי שיהא קיום לאהבתו אליו, וכיוצא בזה יובן בכל השפעה והמשכה אם היא נראית בבחי' יש ודבר גדול לא תתקיים אורה ושפעה בלתי אם לא שיעלים ויכסה להקטין בתחלה בכדי שלא יתראה ליש ודבר כלל, וכל זה משל ודמיון לסיבה הראשונה בענין השבירה שהוא מפני תוקף האור דהיינו בחי' התגלותו בבחי' יש ודבר גדול ואין זה בחי' יש ממש אלא מפני שהוא ענין ובחי' הגילוי כמו שהוא בעצם המאציל מבלי לבוש והעלם כלל וכנ\"ל בענין יו\"ד נקודות שהוא בחי' גילוי העצמות כו' להיות כי המשכות י\"ס דתהו הן בחי' אורות עצמיי' כנ\"ל וזהו מ\"ש וימלוך וימ\"ת וידוע דכל מלוכה הוא בחי' תוקף גדול כטבע המלך שהוא תקיף גדול ומחמת זה הי' סיבה הא' בשבירה דהיינו שלא יכול האור להתקיים ונסתלק למקורו כמבואר ומובן מתוך כל הנ\"ל וד\"ל. והסיבה השני' הוא מיעוט הכלי שלא הי' מכיל את האור מפני תקפו וכנ\"ל והכל א' דמפני תוקף וריבוי האור נעשה מיעוט הכלי' כנ\"ל באריכות אך ממה שאנו רואים שע\"י ריבוי הכלים דתיקון הרי נעשה מיעוט האור כמשי\"ת בבחי' התיקון, א\"כ יובן מזה גם בבחי' התהו דיש סיבה ג\"כ בתוקף האור מצד מיעוט הכלי מלבד תוקף עצמי כי לולי הי' הכלי רחב לא הי' האור בתוקף כ\"כ הרי סיבת תקפו של אור בא ג\"כ מצד מיעוט הכלי ומיעוט הכלי בא מסיבת תוקף האור ושניהם אמת, והענין הוא כי אם יעלים וילביש האור בכלי יותר לא הי' נרגש בבחי' ישות כ\"כ וד\"ל (וזהו שארז\"ל כי טוב כי טוב האור לגנוז בכלי כו' והוא שרש בחי' התיקון כמשי\"ת).",[["2241","53","<b>חרות על הלוחות חירות ממ\"ה</b>: שמו\"ר פמ\"א, ז."],["2242","54","<b>ממ\"ה</b>: בכת\"י ב' וכת\"י ג: חרות ממה\"מ חירות כו'."],["2243","55","<b>כדוגמת העוה\"ב</b>: ראה ברכות יז, א. לקו\"ת צו טו, ג. שם דרושים לש\"ש סו, א. ובכ\"מ."],["2244","56","<b>ויתגלה</b>: בכת\"י ב וכת\"י ג: ויתעלה."]]],[2101000349,"<b>ומעתה</b><sup data-n=\"2245\">57</sup> יש להבין ענין הנפילת הניצוצות רפ\"ח כו' שנפלו עם הכלים וענין נפילת הכלים עצמן כי לכאורה לא שייך באורות שבירה כלל רק שנסתלקו למעלה, ומקצת מן האורות נפלו וגם בהן לא שייך שבירה רק בכלים בלבד. ויובן זה ג\"כ בשתי סיבות סיבה הא' בהעדר והסתלקות האור להיותו בבחי' יש כנ\"ל הנה הוא עצמו גורם שמקצת ממנו יפול למטה עם הכלים, ויובן זה עד\"מ הידוע שאם יעמיק אדם באור שכל עמוק יותר מכדי קבלת כלי מוחו הנה לא יכול הכלי כלל לקבל ובהכרח שיסתלק אור השכל ההוא למקור דשכל, ואמנם הנה כבר הלבישו אותיות כלי ההשגה ונתכווצו ונתחברו יחד להכיל האור השכלי רק לקיצור הכלי לא יכלו להכיל א\"כ בהסתלק מהם האור ה\"ז כהסתלקות הצורה מן החומר כמו כח הראי' מכלי העין שבהכרח נשאר מעט מן הראי' בעין גם בשעת השינה וכה\"ג כך נשאר בהכרח מהארת אור השכל העמוק בכלי אותיות ההשגה מאחר שכבר הי' לאחדים וקיבלו האור רק שלא נתקיים בהם ונסתלק אבל גם שנסתלק נשאר קצה הארתו בהם גם לאחר פיזור כל האותיות לאחר שנתבלבלו מקוצר כחם לקבל (וראי' לדבר זה ידוע מעין דוגמא זו מענין החלומות<sup data-n=\"2246\">58</sup> שהן מעין הרהורי לבו ביום רק שהצירופים נתבלבלו כו' וכמ\"ש במ\"א ע\"פ ותחלימני<sup data-n=\"2247\">59</sup> ותחייני), ומזה יובן דמיון לבחי' נפילת הניצוצות רפ\"ח כו' שנשארו בכלים<sup data-n=\"2248\">60</sup> שנמשלו לאותיות כידוע וד\"ל. והסיבה הב' מפני מיעוט הכלי הנ\"ל הוא הגורם נפילת הכלים ושבירתן והיינו עד\"מ פיזור האותיות שמתפזרי' אנה ואנה כאשר לא יכילו אור השכל כנ\"ל, וענין הפיזור ידוע שבהיות האותיות יחד הי' מאיר כל אור השכל כמו שהוא ובהתפזרם נסתלק אור השכל כולו ואפס קצהו נשאר בהכרח באותיות כנ\"ל, אך גם זאת לא כולו ביחד אלא לחלקים כי בכל אות לבדו מאיר חלק ניצוץ פרטי לאחר הפיזור ואף גם הניצוץ הזה הרי הוא לאחר הירידה מעיקר השכל ויורד עוד יותר עם ירידת הכלי שהוא האות עד\"מ תיבת ויאמר מאיר בה שכל א' והיינו דוקא כאשר ה' האותיות דויאמר מחוברים יחד, אבל כשמתפזרים ומתפרדים הרי באות הוי\"ו דויאמר מאיר ניצוץ פרטי ואינו דומה כלל לאור שהאיר בוי\"ו זה בהיותו לאחדים בתיבת ויאמר עם שאר האותיות רק שעכ\"ז קצת הארה נשאר בו ואמנם בירידת הוי\"ו הזה בצירופי' אחרים ישתנה הארת השכל הנשאר בו לגמרי ועד\"ז בשאר האותיות כו' וכ\"ז משל ודמיון להבין ענין נפילת הכלים שנמשלים לאותיות עם מקצת מהאורות שנשאר בהם שנק' רפ\"ח ניצוצי' כו' ונמצא מובן שמסיבת ישות האור נפל ונתפזרו ניצוצות מהן בכלים ומסיבת מיעוט הכלים נפלו הכלים ונשברו ואז ממילא ירדו הניצוצות רפ\"ח עמהם כו', ולפ\"ז לא שהי' בחי' שבירה באורות כלל גם ברפ\"ח רק שירדו מעיקר מקור האור כמו הפרדת ניצוץ מן השלהבת בלבד אבל",[["2245","57","<b>ומעתה יש להבין. . לא שייך באורות שבירה כלל</b>: ראה ע\"ח ש\"ט פ\"ו ואילך. שער יח-יט."],["2246","58","<b>החלומות שהן מעין הרהורי לבו ביום</b>: ראה ברכות נה, ב. וראה תו\"א וישב כח, ג. תו\"ח שמות נב, א."],["2247","59","<b>ותחלימני ותחייני</b>: ראה ישעי' לח, טז."],["2248","60","<b>בכלים שנמשלו לאותיות כידוע</b>: ראה ג\"כ לקו\"ת מטות פב, ג. סה\"מ אתהלך לאזניא ע' נה. סה\"מ תקס\"ב ע' קפט. ביאוה\"ז לא, ד ואילך. תו\"ח וישב סה, ג. ובכ\"מ."]]],[2101000350,"בכלים שנק' אותיות הי' שבירה שהוא הפיזור והנפילה למטה כנ\"ל ומחמת זה נתהווה גם בחי' קליפת נוג\"ה ובריבוי הירידות והצמצומים למטה מטה נתהווה גם ג' קליפות הטמאות כו' כידוע וד\"ל.\n<b>והנה</b> בחי' התיקון הוא ע\"י שנעשה בחי' ריבוי הכלים ומיעוט האור, והענין הוא שממילא נעשה מיעוט האור מפני ריבוי הכלים כמובן בע\"ח לענין<sup data-n=\"2249\">61</sup> כללות התיקון המה<sup data-n=\"2250\">62</sup> ב' דברים הא' בחי' ריבוי ההתכללות והב' בחי' ריבוי ההעלמות כו' בחי' ריבוי ההתכללות היינו ע\"י שכאו\"א מתחלק לי' וי' ליו\"ד כמו חסד שבגבורה כו' וגבורה שבחסד כו' הרי החסד כלול מגבורה וגבורה מחסד, ועד\"ז יוכל להיות ריבוי ההתכללות עד אין שיעור כי כל א' כלול מחבירו בכל ריבוי חלקים בכמה אופנים שונים כמו דוגמת צירופי אותיות שבה'<sup data-n=\"2251\">63</sup> אותיות יש ק\"ך צירופים וכיוצא או כדמיון מזיגת דברים הרבה שיכולים למזוג בכמה אופנים שונים כו' וריבוי ההתכללות הוא הנק' ריבוי הכלים כי כל אור מתגלה בכמה אופנים שונים ולא באופן א' בלבד כאורות דתוהו, והב' הנק' ריבוי העלמות, והוא אשר יתעלם האור בכמה מיני העלמות ולבושים בהעלם אחר העלם ולבוש אחר לבוש ולא יתגלה כמו שהוא והוא ענין ירידת אור השפע מעילה לעילה בכמה מדריגות עד שהתגלות אור השפע בעילה האחרונה הוא בא בהעלם היותר אחרון לפי שנשתנה ממהותו הרבה פעמים כי בכל פעם שיורד מעילה לעילה נשתנה ונתעלם קצת אורו העצמי' ועד\"מ אור הרצון בירידתו להתלבש בשכל וטעם נשתנה מהותו ומן השכל יורד למדה שבלב נשתנה עוד וכן מן המדה שבלב לדיבור ומן הדיבור למעשה עד שבמעשה בא הרצון בשינוי מהות לגמרי דהיינו בעשי' גשמיות כו', וככה יובן למעלה בחי' ירידת כל אור מעילה לעילה משתנה ע\"י לבושים והעלמות שונות של כל עילה ועילה עד שכאשר בא בעילה אחרונה הוא בא בהעלם היותר אחרון כו', וזהו עיקר בחי' התיקון שהוא להעלים את האור בריבוי העלמות כדי שלא יאיר בתקפו כמו שהוא וכמ\"ש בזוהר בכמה דוכתי עבד לבושא לנהורא כו' עד שנעשה בחי' התיקון שהאור בא במיעוט ולא בתוקף כבחי' התהו מחמת התלבשות והעלמות רבות, ואז ממילא נעשה בחי' ריבוי הכלים שהוא מפני בחי' ריבוי ההתכללות מאד כנ\"ל והא בהא תלי' דאם הי' האור מאיר בתקפו בלי לבוש והעלם כלל לא הי' מתחלק ומתכלל זע\"ז כלל וכבחי' התהו שנאמר וימלוך<sup data-n=\"2252\">64</sup> תחתיו, תחתיו דוקא כי הן זה תחת זה כו' ואינן רק נקודות כו' כנ\"ל באורך אבל אם האור אינו מאיר רק ע\"י כמה לבושים והעלמות כי ירד מעילה לעילה מאד הרבה כנ\"ל שאז אינו מאיר בתוקף כלל אלא במיעוט הוא הגורם שיוכל להתחלק ולהתכלל הרבה והוא הנק' ריבוי כלים כנ\"ל וד\"ל (וזהו<sup data-n=\"2253\">65</sup> שמיעוט האור הוא ריבוי הכלים, אך מה שריבוי הכלים גורם מיעוט האור כמבואר למעלה היינו ע\"ד אחר שריבוי ההעלמות הנ\"ל נקראי' ריבוי כלים כי כל כלי הוא",[["2249","61","<b>לענין</b>: בכת\"י ב וכת\"י ג: וענין."],["2250","62","<b>המה</b>: בכת\"י ב: הי'."],["2251","63","<b>שבה' אותיות</b>: בכת\"י ב וכת\"י ג ליתא תיבות אלו."],["2252","64","<b>וימלוך תחתיו. . זה תחת זה</b>: ראה ג\"כ תו\"א וישלח כד, ד. שמות נב, א. בשלח סה, א. ובכ\"מ."],["2253","65","<b>(וזהו</b>: בכמה כת\"י אין כאן מוסגר."]]],[2101000351,"בחי' העלול המקבל מן העילה שמתעלם אור העילה בו כו', נמצא בריבוי הכלים והעלמות עושה מיעוט האור, או יובן כפשוטו דריבוי הכלים כמו בהתחלקות אותיות רבות וצירופים הרבה האור נעשה במיעוט עי\"ז עד\"מ כל מה שיאריך יותר לפרש הדבר יותר יקטן עצם אור השכל כנ\"ל וכמ\"ש במ\"א באריכות וד\"ל).\n<b>והנה</b> ידוע דעיקר שרש בחי' התיקון הוא ע\"י שם מ\"ה החדש שמאיר ממצחא דא\"ק והוא המלך השמיני הדר כו' כמ\"ש בע\"ח)<sup data-n=\"2254\">66</sup>. וביאור הדברים ידוע ומבואר במ\"א להיות שמבואר למעלה בסיבת הסתלקות אורות דתוהו להיותן מתגלי' בבחי' תקפן העצמי' והוא בבחי' ישות כו', ודוגמא לדבר לוחות הראשונות כנ\"ל באריכות הנה לזה עיקר בחי' התיקון הוא דוקא ע\"י הארת שם מ\"ה שהוא בחי' אי\"ן וכמ\"ש והחכ' מאין כו' כי החכמה הוא בחי' ביטול היפך הישות לגמרי, וע\"כ בשם מ\"ה דא\"ק שמאיר ממצחא כו' משם בא האור בבחי' אין האמיתי, ועי\"ז יש קיום חזק לאורות שלא יסתלקו כו' והוא גורם ג\"כ להיות בחי' ההתכללות מכמה הפכים יחד, והוא שם מ\"ה דז\"א שהוא הנק' אדם דאצי' שהוא עיקר בחי' התיקון אך שם מ\"ה דא\"ק הוא מקור הראשון לבחי' מ\"ה זה כידוע בע\"ח, וביאור כ\"ז מבואר במ\"א וד\"ל. והנה בחי' שם מ\"ה הזה<sup data-n=\"2255\">67</sup> הוא המברר לבחי' ב\"ן דנוגה דבריאה שנפל בשבירה והיינו בחי' הכלים דז' מלכים דתהו עם האורות רפ\"ח שירדו למטה ונפלו בעולם הבריאה כמ\"ש בע\"ח, וענין הבירור הוא בכל עולם ועולם לפי מה שהוא דהיינו בעולם האצי' בחי' מ\"ה מברר לב\"ן ונתעלה ונכלל באצי' כל מה שיוכל להתעלות ומחמת זה נעשה בחי' תוס' האור באצי' ובעולם הבריאה מתברר ונכלל כל מה שיוכל להתעלות שם ונעשה ע\"י תוס' אור<sup data-n=\"2256\">68</sup> בעולם הבריאה וכן ביצי' ועשי' עד שבעולם העשי' מתברר נוג\"ה דעשי' ע\"י המצות או תשובה לאהפכא חשוכא לנהורא כו', וזהו כל עיקר ענין בחי'<sup data-n=\"2257\">69</sup> בירורי נוג\"ה שעי\"ז נעשה בחי' תוס' אור באצי' כנ\"ל וכמ\"ש בע\"ח, ומה שלא יוכל להתברר עוד גם בעשי' הוא שנעשה שרש לבחי' ג' קליפות הטמאות כו'. אך יש להבין מהיכן נעשה בחי' תוס' אור באצי' הרי עיקר בחי' התיקון שבאצי' הוא במיעוט אור דוקא ואיך נאמר שע\"י הבירור דשם מ\"ה לב\"ן יהי' בחי' תוס' אור כו'. אמנם הענין הוא שאין זה מצד עצם התיקון דשם מ\"ה אלא ע\"י סיבת דבר המתברר והוא בחי' כלים דתוהו שנפלו למטה ונשברו המתבררים ועולים למעלה ע\"י שם מ\"ה כו' שהרי הן בבחי' ישות גמורה ובאים לבחי' ביטול והתכללות אל שרשם הראשון שהוא בחי' ס\"ג שלמעלה משם מ\"ה והוא אורות דתוהו שהן בחי' הישות דקדושה האלקי' כמו שהי' בלוחות הראשונות כו' דאע\"פ שנעשה<sup data-n=\"2258\">70</sup> עי\"ז בחי' פירוד למטה בעולם הפירוד אבל מצד שרשו למעלה הוא יותר גבוה מבחי' אי\"ן דחכמה המברר כו' ונק' יש האמיתי כידוע (וזהו שרמזו רז\"ל גדולים<sup data-n=\"2259\">71</sup> מעשה צדיקים ממעשה שמים וארץ כו', משום דמעשה צדיקים הוא",[["2254","66","<b>בע\"ח)</b>: בהכת\"י חסר התחלת המוסגר."],["2255","67","<b>הזה</b>: בכת\"י ג: הי'."],["2256","68","<b>אור בעולם הבריאה</b>: בכת\"י ב: אור האצי' בע\"ס דבריאה. ובכת\"י ג: אור באצי' ע\"ס דבריאה."],["2257","69","<b>בחי'</b>: בכת\"י ב: בחי' הקליפה. ובכת\"י ג' יש כאן מקום חלק."],["2258","70","<b>שנעשה עי\"ז</b>: בכת\"י ב: שהם בבחי'."],["2259","71","<b>גדולים מעשה צדיקים ממעשה שמים וארץ</b>: כתובות ה, א. וראה תו\"א בשלח סו, ב. לקו\"ת אמור לז, א. פינחס עז, ג. דרושים לש\"ש סז, א. אוה\"ת בא ע' רנה. יתרו ע' תתקכה. ויקרא ע' תקעד. ובכ\"מ."]]],[2101000352,"לאהפכא חשוכא לנהורא כו' שהוא היפך היש לאי\"ן, ומעשה שמים וארץ הוא מאי\"ן לי\"ש ומי\"ש לאי\"ן חוזר אל היש האמיתי שקודם לאין דחכמה משא\"כ מאין ליש גמור כו' וד\"ל), וזהו מ\"ש אשת<sup data-n=\"2260\">72</sup> חיל עט\"ב שהוא שם ב\"ן לאחר הבירור שהוא למעלה משם מ\"ה המברר כי עלה בס\"ג שהוא בחי' ז\"ת דבינה ששם הי' השבירה בז' מדות דתוהו כידוע וד\"ל. והנה להיות כן באי' בחי' הכלים דתוהו שנפלו למעלה בבחי' ס\"ג ומתרחבים הרבה יותר מכמו שהי' קודם שבירתן שהי' במיעוט כו' מצד בחי' העלאתן למעלה ע\"י בחי' התיקון שנעשה ריבוי הרחבת הכלים כנ\"ל, ועי\"ז<sup data-n=\"2261\">73</sup> יוכלו לקבל את האורות דתוהו אע\"פ שהן בתוקף גדול ובפרט אחרי הסתלקותן למעלה יותר כו' אך גודל ורוחב הכלים יעלימו וימעיטו את תוקף אורם כנ\"ל דריבוי הכלי עושה מיעוט האור כלומר התיישבות האור שאינו מאיר בבחי' העלם כ\"כ, וזהו ענין להוסיף אורות באצי' שנעשה ע\"י בירורי נוג\"ה ע\"י בחי' התיקון דשם מ\"ה דוקא הגם שמצד עצם התיקון שעושה ריבוי הכלים נעשה מיעוט האור היינו דוקא אור דתיקון הוא שבא במיעוט אבל בחי' האורות דתוהו הרי הן חזקים ותקיפים ביותר רק שלא יכלו הכלים לסובלם, אבל אחר הבירור הרי יכלו הכלים לקבלם ולסובלם מפני התרחבותם כנ\"ל, וא\"כ יש ע\"י בחי' אורות דתוהו בחי' תוס' אור באצי' גם בבחי' התיקון לפי שבחי' אורות דתוהו מתיישבי' בכלים דתיקון שנעשו ע\"י הבירור דוקא, ונמצא ע\"י בירורי נוג\"ה דוקא וע\"י התיקון דשם מ\"ה מאמצעות שניהם נעשה ונמשך בחי' תוס' אורות דתוהו באצי' דתיקון ג\"כ וז\"ש לריח ניחוח להוי' דתיקון ע\"י הקרבנות שהן בירורי נוג\"ה כמשי\"ת וד\"ל.\n<b>והנה</b> מבואר בע\"ח בשער מ\"ן ומ\"ד שיש ביחוד מ\"ן ומ\"ד ב' בירורים הא' בחי' העלאת המ\"ן בתחלה שנק' בירור הראשון ואח\"כ נמשך בחי' מ\"ד ומברר למ\"ן והוא בחי' בירור השני כו'. והנה ביאור הדבר ידוע עד\"מ בירור האודם<sup data-n=\"2262\">74</sup> שממנו בשר כו' שנעשה מן המאכלים שאוכלת שנהפך לדם ואח\"כ מתהווה זרע ונק' מ\"ן והוא מ\"ש אשה<sup data-n=\"2263\">75</sup> כי תזריע כו' ואח\"כ בא טפת הזכר על המ\"ן ומברר למ\"ן דהיינו שדוחה את הפסולת וקולט את המובחר ומתאחד בו והוא הנק' קליטה (והפסולת של המ\"ן ממנו מתהווה שליא של הולד כמ\"ש במ\"א), וכך יובן למעלה בבחי' העלאת מ\"ן של הנשמות ומלאכים דבי\"ע שהמל' מעלה מ\"נ כידוע שזה בא ע\"י בירורי נוג\"ה דוקא כשמתהפך חשוכא לנהורא כו' וכמו המאכל הגשמי שמתהפך לדם כו' ואז הוא כמו האודם כו' (ופסולת הדם הוא דם הטמא שממנו יניקת החיצונים) וכמ\"ש בע\"ח בכמה דוכתי שכל העלא' מ\"ן נעשה רק מבירורי נוג\"ה דוקא והוא הבירור הראשון שמתברר בהעלאת מ\"ן דמל' מבי\"ע ועולה באצי' והיינו בחי'",[["2260","72","<b>אשת חיל עט\"ב</b>: משלי יב, ד. וראה ע\"ח ש\"ה פ\"א. ש\"י פ\"ג. ש\"מ פ\"ד. לקו\"ת בחוקותי מז, ג. אוה\"ת בראשית מ, ב."],["2261","73","<b>ועי\"ז</b>: בכת\"י ב וכת\"י ג: ועד\"ז."],["2262","74","<b>האודם שממנו בשר</b>: נדה לא, א."],["2263","75","<b>אשה כי תזריע</b>: ויקרא יב, ב. וראה תו\"א תולדות יז, ג. שמות מט, ב. ובכ\"מ."]]],[2101000353,"שם ב\"ן המתברר כו' ואח\"כ נמשך בחי' מ\"ד דדכורא והוא בחי' המשכות אור הזרוע לצדיק חי עלמין מבחי' יסוד ז\"א במל' כידוע והוא בירור השני של המ\"ן דהיינו מה שבחי' מ\"ד מברר למ\"ן דמל' לקלוט את הטוב ולהתאחד בו, והוא כמארז\"ל דמיכאל<sup data-n=\"2264\">76</sup> כה\"ג מקריב נשמות ע\"ג המזבח ועולי' למעלה ונכללי' באור האצי' ממש כמאמר לאשתאבא<sup data-n=\"2265\">77</sup> בגופא דמלכא כו' או כמו ע\"י מס\"נ של הנשמות באחד כמו ר\"ע<sup data-n=\"2266\">78</sup> שיצאה נשמתו באחד ממש וכיוצא ואשר א\"א ליכלל ממש באור האצי' ממש יורד למטה כו' (והן הנפילים<sup data-n=\"2267\">79</sup> אשר היו בארץ כו' כמ\"ש במ\"א), והוא ענין שם מ\"ה דאצי' שמברר לב\"ן בכללות וכמו עד\"מ הוולד שנוצר ונתהווה מאמצעות חיבור מ\"ד ומ\"ן הגשמיי' כך למעלה נתהווה תולדות הנשמות מאמצעות מ\"ד ומ\"ן דזו\"נ ובכללות נק' יחוד מ\"ה וב\"ן כו' וד\"ל.\n<b>ובזה</b> יובן שרש ענין הקרבנות, דהנה הקרבנות כמו הבהמה והצאן והעופות כולם מבחי' נוג\"ה דעשי' כי התהוות נפש הבהמה שרשה בפני שור כו' והעופות שרשו בפני נשר כו' כידוע שכל חלקי דצח\"ם דעשי' נמשכים מבחי' נוג\"ה דעשי', והנה כאשר עולה הקרבן ע\"ג המזבח מצוה<sup data-n=\"2268\">80</sup> להביא אש מן ההדיוט שישרף הקרבן בו ע\"ג המזבח ע\"י הכהן המקריב והוא כמו בחי' העלא' מ\"ן הנ\"ל כך הקרבן עולה באש של מטה, והוא בחי' בירורי נוגה דעשי' שממנו שרש הקרבן כו' ונק' בירור הראשון כנ\"ל ואח\"כ נמשך אש של מעלה ואוכל הקרבן כמ\"ש<sup data-n=\"2269\">81</sup> בזוהר דארי' אכיל קרבנין אור י\"ה והוא שרשו מבחי' החסד דפני ארי' להימין כו', אמנם אכילה זו הוא הבירור השני שהוא כמו בחי' המשכת מ\"ד שמברר למ\"ן כנ\"ל שנקלט הטוב ונכלל באלקות ממש (וזהו מ\"ש האכל<sup data-n=\"2270\">82</sup> יאכל בשתי אכילות הכתוב מדבר אכילת מזבח והוא בחי' העלאת מ\"ן כמ\"ש אש<sup data-n=\"2271\">83</sup> תמיד תוקד על המזבח לא תכבה, והוא כח המעלה מ\"ן תמיד לא יכבה כו' וז\"ש עולת<sup data-n=\"2272\">84</sup> תמיד העשויה כו', ואכילת אדם שהוא בחי' ארי' דאכיל קרבנין כו' וז\"ש אדם<sup data-n=\"2273\">85</sup> כי יקריב מן הבהמה כו' אדם בחי' מ\"ה שמברר לב\"ן בגימ' בהמה כו'), וכמ\"כ יובן עכשיו שהתפלה<sup data-n=\"2274\">86</sup> במקום קרבן כי הנה\"ב שרשה בבחי' נוג\"ה דפני שור כו' וע\"י ההתלהבות שע\"י ההתבוננות הוא כמו אש של הדיוט שע\"ג המזבח ושורף ומעלה לנפש הבהמית למסור נפשו בא' באמרו",[["2264","76","<b>דמיכאל כה\"ג מקריב נשמות ע\"ג המזבח</b>: ראה זח\"א פ, א. פא, א. זח\"ב רלא, א. זח\"ג לג, א. תוס' מנחות קי, א בשם המדרש. אוה\"ת ויקהל ע' ב'קצט וש\"נ. וראה ס' מאמרי אדהאמ\"צ דברים ח\"א ע' עא, ובמ\"מ שם."],["2265","77","<b>לאשתאבא בגופא דמלכא</b>: זח\"א ריז, א."],["2266","78","<b>ר\"ע שיצאה נשמתו באחד</b>: ברכות סא, ב."],["2267","79","<b>הנפילים אשר הי' בארץ</b>: בראשית ו, ד. וראה אוה\"ת בראשית כרך ג' תקצה, א. מג\"א ע' ב'תכא."],["2268","80","<b>מצוה להביא אש מן ההדיוט</b>: עירובין סג, א. זח\"ג רנה, א, וראה ג\"כ לעיל ע' רלד ואילך."],["2269","81","<b>כמ\"ש בזוהר דארי' אכיל קרבנין</b>: זח\"א ו, ב. זח\"ב רעח, א. זח\"ג יז, א. וראה לקו\"ת בהעלותך ל, א."],["2270","82","<b>האכל יאכל בשתי אכילות</b>: זבחים יג, ב. ובכ\"מ."],["2271","83","<b>אש תמיד תוקד על המזבח</b>: ויקרא ו, ו."],["2272","84","<b>עולת תמיד העשויה</b>: במדבר כח, ו."],["2273","85","<b>אדם כי יקריב מן הבהמה</b>: ויקרא א, ב."],["2274","86","<b>שהתפלה במקום קרבן</b>: ברכות כו, ב. ובכ\"מ."]]],[2101000354,"ואהבת כו' ונק' העלאת מ\"ן בירור הא' הנ\"ל ואח\"כ נמשך בחי' מ\"ד בש\"ע שהוא בחי' אה\"ר שנמשכת מלמעלה למטה והיא המקשרת ומדבקת לבחי' הטוב שבנפש<sup data-n=\"2275\">87</sup> הבהמי' ודוחה את הפסולת כו' והיינו לאשתאבא בגופא דמלכא במס\"נ כנ\"ל וד\"ל.\n<b>והנה</b> להבין שרש ענין שמחה של מצוה שגדולה מן המצוה עצמה, והוא בשמחת החג בשמחת בית השואבה ובשמחת תורה ולא בכל השנה כמבואר<sup data-n=\"2276\">88</sup> (בתורה), הנה להבין זה הלא ידוע ומבואר ע\"פ תחת<sup data-n=\"2277\">89</sup> אשר לא עבדת את ה' אלקיך בשמחה וטוב לבב מרוב כל, דרוב כל הוא חיי העוה\"ב, ושמחה וטוב לבב מן המצות יותר טוב מחיי העוה\"ב וזה לכאורה כדבר פלא איך יהי' מעלת שמחה של מצוה גדולה מגופה של מעשה המצוה. אך הנה ארז\"ל דהעוה\"ב<sup data-n=\"2278\">90</sup> הוא שצדיקי' יושבי' ועטרותיהם בראשיהם ונהני' מזיו השכינה, ויש להבין מהו עטרות שבראשיהם ואיך נהני' מזיו השכינה, ומה חידש יש בו יותר מזיו השכינה בג\"ע עכשיו, ולמה מתייחס זה אל העוה\"ב דוקא. ותחלה יש להבין שרש העוה\"ב מהו, דהנה העוה\"ב הוא בא אחר תשלום כל בירורי נוג\"ה דבי\"ע בכל וא\"ש<sup data-n=\"2279\">91</sup> דהוי עלמא וכמ\"ש ואת<sup data-n=\"2280\">92</sup> רוח הטומאה אעביר כו' בלע<sup data-n=\"2281\">93</sup> המות כו' וכיוצא ומבואר למעלה דמבחי' בירורי נוג\"ה ע\"י שם מ\"ה דתיקון נתרחבו בחי' הכלים דתוהו ומתיישבי' בהן בחי' אורות תקיפי' דתוהו והוא מ\"ש אשת חיל עטרת בעלה כו', וזה ידוע דכל המצות מעשיות הן רק בחי' בירורי נוג\"ה לאהפכא חשוכא לנהורא בסו\"מ בשס\"ה ל\"ת ועשה טוב ברמ\"ח מ\"ע כו', והן הנה בחי' העטרות שע\"ג ראשי הצדיקים מכל המצות שנעשו בעוה\"ז כי בחי' העטרה הוא בחי' אור מקיף ע\"ג הראש, וכינו דבר זה לעטרה דוקא כמו עד\"מ שעושי' עטרה למלך מאבנים טובות כו' כך המצות שעושי' בדברים גשמיי' דנוג\"ה לאחר הבירור הן מאירים כאבנים טובות ונעשי' בחי' אור מקיף ע\"ג הראש מלמעלה דהיינו למעלה מהיות בחי' התגלות בכלי המוחי' כי שרש המצות לאחר הבירור הן מבחי' אורות דתוהו שהן אורות תקיפים עד שלא יכלו הכלים לסבול כו' כנ\"ל באריכות (וזהו שרש ענין וצדיק<sup data-n=\"2282\">94</sup> באמונתו יחי' כי האמונה בחי' עטרה ע\"ג הראש כי שרשה בחי' אור מקיף ובאמונתו שלמעלה מן השכל יחי' לעוה\"ב שאז יהי' הצדיקי' נהנין מאותו האור בבחי' גילוי כמשי\"ת), אך הנה אע\"פ שאין האור הזה בא בבחי' גילוי כמו שהוא להיותו בחי' אור מקיף כנ\"ל אבל הנה בא ע\"י אמצעות בחי' אותיות המביאים מבחי' ההעלם לבחי' הגילוי, והוא מה שאמר נהני' מזיו השכינה פי' שכינה הוא בחי' מל' דאצי' שמאיר בבחי' אותיות והוא הנק' זיו השכינה (כמו בג\"ע דעכשיו שמאיר ברקיע הג\"ע כ\"ב אתווין והוא נהירו עילאה וכמ\"ש ועל<sup data-n=\"2283\">95</sup> ראשי החיות רקיע כעין הקרח הנורא כו').",[["2275","87","<b>שבנפש הבהמי'</b>: בכת\"י ב וכת\"י ג ליתא תיבות אלו."],["2276","88","<b>כמבואר (בתורה)</b>: לעיל ד\"ה הללו."],["2277","89","<b>תחת אשך לא עבדת</b>: דברים כח, מז. וראה תניא פכ\"ו ובליקוט פירושים ומ\"מ שם."],["2278","90","<b>דהעוה\"ב הוא שצדיקים יושבים</b>: ברכות יז, א."],["2279","91","<b>וא\"ש דהוי עלמא</b>: ר\"ה לא, א. וראה לקו\"ש משפטים חכ\"א ע' 453."],["2280","92","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["2281","93","<b>בלע המות</b>: ישעי' כה, ח."],["2282","94","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["2283","95","<b>ועל ראשי החיות רקיע</b>: ראה יחזקאל א, כב."]]],[2101000355,"<b>וביאור</b> ענין האותיות ידוע שהן בחי' אמצעי לחבר העליון בתחתון או שני דברים נפרדים, והיינו כאשר אין ערך בין המשפיע והמקבל שיקבל האור כמו שהוא אזי יומשך האור ע\"י בחי' אותיות שנקראו ממוצעים והענין הוא עד\"מ האהבה בלב האדם אל דבר הנאהב הרי דבר הנאהב הוא דבר נפרד מן עצם אור האהבה והרי אנו רואי' שמתחברים יחד כי הרי נמשך אור וחיות האהבה בתוך דבר הנאהב ממש, והנה ודאי אין ערוך לדבר הנאהב לגבי האהבה הרוחניות, אך ע\"י בחי' אותיות מתחברת רוחניות האהבה בתוך דבר הנאהב והיינו ע\"י אותיות המחשבה שחושב ומהרהר את האהבה שבלבו שהרי ע\"י אותיות הללו יאיר ויבקע אור האהבה אל דבר הנאהב וע\"י יש לה חיבור וקשר עם דבר הנאהב כי האותיות מביאי' אותה מן העלם עצמותה לידי גילוי לחוץ ממנה בדבר נפרד כו', וכמ\"כ אותיות השכל מביאי' גילוי אור השכל להתחבר בדבר חוץ מן השכל כמו להשכיל לתינוק או להוליד אהבה וכיוצא בזה בכל עו\"ע שהוא ירידה ממהות למהות אינו אלא ע\"י בחי' אותיות העליון שמחברו לתחתון כו', וככה יובן למעלה בבחי' אותיות שבמל' דאצי' שהוא בחי' ממוצע להביא בחי' גילוי אור האלקי על הנשמות של הצדיקים, וזהו שאמר נהני' מזיו השכינה ע\"י אמצעות בחי' אותיות השכינה, והוא גילוי אור מקיפי' של המצות שנקראו עטרות כנ\"ל וזהו שאמרו דשכר<sup data-n=\"2284\">96</sup> מצוה בעוה\"ב היא המצוה בעצמה שבאה לידי גילוי להיות נהני' ממנה בזיו השכינה כנ\"ל וד\"ל, אבל בלתי בחי' האותיות לא יוכלו לקבל מאור המצות עצמן להיותן אור תקיף וגדול מערכם מטעם הנ\"ל שבאי' מבחי' בירורי נוג\"ה רק על ראשיהן נעשה עטרות בלבד בבחי' מקיף, אבל ע\"י האותיות מאיר להם בהגבלה כפי אשר יוכלו שאת בכלי השגתם כו', וזהו החידוש שבעוה\"ב יותר מג\"ע דעכשיו דהיינו שבחי' מקיף מתגלה, משא\"כ בג\"ע אינן מקבלי' רק מבחי' א\"פ שלאחר הצמצום כו' וד\"ל.\n<b>ואמנם</b> בעוה\"ז א' היום<sup data-n=\"2285\">97</sup> לעשותם בלבד שהאור בבחי' ההעלם ולמחר לקבל שכרם בבחי' הגילוי מפני שעכשיו בעוה\"ז לא נתברר עדיין בשלימות עד זמן העוה\"ב כו', וע\"כ כל עיקר העוה\"ב תלוי במצות דווקא ולזה אמרו ז\"ל דכל<sup data-n=\"2286\">98</sup> ישראל יש להם חלק לעוה\"ב שנא' ועמך כולם צדיקים כו' שאפי'<sup data-n=\"2287\">99</sup> פושעי ישראל מלאי' מצות כו' וד\"ל, אך הנה שרש בחי' שמחה של מצוה הוא בחי' גילוי אור המקיף ממש כמו שהוא ולא ע\"י אמצעות בחי' אותיות ע\"כ השמחה באה בלתי מוגבלת בהשגה כלל כמו בשמחת בית השואבה שהי' החסידים ממשיכים רוה\"ק ממש כמו הלל<sup data-n=\"2288\">100</sup> הזקן כשהי' שמח הי' אומר אם אני כאן כו' ורשב\"ג הי' זורק ח' אבוקות כו' ועיקר גילוי השמחה מכל המצות שעשו כל השנה הוא בשמחת תורה שמקיפי' בס\"ת ז' הקפות כו' והענין הוא כי כל השנה הגם דעשו מצות אבל מפני",[["2284","96","<b>דשכר מצוה. . היא המצוה בעצמה</b>: ראה אבות פ\"ד מ\"ב. תניא פל\"ז, פל\"ט."],["2285","97","<b>היום לעשותם. . ולמחר לקבל שכרם</b>: עירובין כב, א."],["2286","98","<b>דכל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין צ, א."],["2287","99","<b>שאפי' פושעי ישראל מלאי' מצות</b>: עירובין יט, א."],["2288","100","<b>הלל הזקן. . ח' אבוקות</b>: סוכה נג, א."]]],[2101000356,"העוונות שמבדילים אינו מאיר האור של המצות רק בהעלם בהסתר גדול מאד, אך בחג הסוכות שכבר נמחלו העוונות ביו\"כ ע\"י בחי' המשכת י\"ג מדה\"ר כידוע (וכמבואר<sup data-n=\"2289\">101</sup> בתורה) אזי יוכל להיות בחי' גילוי אור מקיף של המצות למטה וכמ\"ש וימינו<sup data-n=\"2290\">102</sup> תחבקני כו' כידוע וד\"ל, וזהו תחת אשר לא עבדת כו' בשמחה וטוב לבב מרוב כל דשמחה של מצוה יותר גבוה מחיי העוה\"ב שאין הגילוי רק ע\"י אותיות כנ\"ל (וע\"כ<sup data-n=\"2291\">103</sup> איתא בכתבי האריז\"ל<sup data-n=\"2292\">104</sup> שעיקר הטעם שנתגלו לו רזין דאורייתא הוא מפני שהי' שמח שמחה של מצוה כו' לפי שהיא בחי' מקיף של הנשמה וגילוי המקיף הוא יותר גבוה מרוה\"ק כו' וכמ\"ש במ\"א וד\"ל.\n<b>ומעתה</b> יש להבין שרש ענין ע' פרי החג ומה ולמה שמתמעטין והולכי' ובשמיני עצרת הוא פר אחד כו' וא'<sup data-n=\"2293\">105</sup> בזוהר משל לזה למלכא דעביד סעודתא לבני היכלא כו' ע\"ש. דהנה לכאורה יש להקשות בטעם הקרבת הע' פרים שהן לנגד ע' שרים דקליפה כידוע והיינו לברר הטוב מהם ולהעלותו למעלה כי שרש הע\"ש הוא מז' מלכים דתוהו וכל מדה כלולה מי' עולה מספר ע' וז' מדות דתיקון הן ע' נפש דיעקב, וז\"ש יצב<sup data-n=\"2294\">106</sup> גבולות עמים למספר בני ישראל כו', והנה בזוהר משמע בטעם הקרבת ע' פרים שהן כדי ליתן יניקה מן המותרות כו', ונמצא שזה כשני ענינים דסתרי אהדדי לכאורה דליתן להם יניקה הוא היפך בחי' הבירור לברר הטוב מהן שע\"י הבירור יאבד שרש יניקתם למעלה כידוע.\n<b>אך</b> התירוץ מובן ע\"ד קצרה ששניהם אמת ואינם תרתי דסתרי אהדדי כלל דמה שנותני' להם יניקה ע\"י הקרבת ע' פרים הוא רק בחי' השפעה בחיצוניות בלבד אבל בחי' הפנימי' מבררים מהם, ודוקא ע\"י השפעה חיצוניות שנותני' להם מבררים מהם בחי' הטוב והפנימי' שלהם כו', וכמו בענין הברכות שלקח יעקב במרמה כמ\"ש יצחק לעשו בא<sup data-n=\"2295\">107</sup> אחיך במרמה ולקח ברכתיך כו' מפני שלבש בגדי עשו החמודות כו' (וכמו שנאמר אם<sup data-n=\"2296\">108</sup> רעב שונאך האכילהו לחם שהוא לחם הקרבנות כי בזה גחלים אתה חותה כו'). ולהבין ביאור זה יש להקדים תחלה בשרש ענין הקרבת ע' פרים שהבירור בהן בע' שרים<sup data-n=\"2297\">109</sup> הוא בבחי' מקיפי' דקליפה דוקא אע\"פ שאין בירור שייך רק בבחי' א\"פ מ\"מ כאן עיקר הכוונה בע' פרי החג הוא לברר ז' מקיפי' דז' מדות דקליפה ששרשם מז' מדות דתוהו כנ\"ל וע\"כ מספרם ע' דוקא דהיינו להוציא ניצוצות דמדות דתוהו מהם ועי\"ז יתבטלו והיינו מפני שבז' ימי החג מתגלים בחי' ז' מקיפי' דקדושה הנק' בזוהר בשם אושפיזין כמשי\"ת בסמוך ע\"כ יש ביכולתם לברר",[["2289","101","<b>וכמבואר בתורה</b>: לעיל ד\"ה הללו."],["2290","102","<b>וימינו תחבקני</b>: שה\"ש ב, ו."],["2291","103","<b>וע\"כ</b>: בהכת\"י חסר סיום המוסגר."],["2292","104","<b>וע\"כ איתא בכתבי האריז\"ל</b>: ראה ג\"כ תו\"א תולדות כ, ב. שער האמונה ספמ\"א. לקוטי שיחות ח\"ט ע' 252."],["2293","105","<b>וא' בזוהר משל לזה</b>: זח\"ג קד, ב."],["2294","106","<b>יצב גבולות עמים</b>: דברים לב, ח."],["2295","107","<b>בא אחיך במרמה</b>: בראשית כז, לה. וראה ג\"כ לקו\"ת בלק עד, ג. סה\"מ תקס\"ד ע' קפב ואילך. סה\"מ תקס\"ה ע' מא ואילך. ובכ\"מ."],["2296","108","<b>אם רעב שונאך האכילהו לחם</b>: משלי כה, כא."],["2297","109","<b>שרים</b>: בכת\"י ב: פרים."]]],[2101000357,"לבחי' מקיפי' דז' מדות דתוהו המלובש בע' שרים כו'. ולהבין זה הנה יש להקדים תחלה מ\"ש דאת זלע\"ז עשה האלקי' דהקליפה הוא לעומת הקדושה בבחי' היפך ומנגד ממש דהיינו בסדר אופן ההשתלשלות, דהנה ידוע שבסט' דקדושה יש בכללות ההשתלשלות ד' עולמות אבי\"ע ושרש כולם הוא בחי' הקו והחוט המאיר מעצמות אא\"ס, והנה באצי' מאיר הארת הקו בגילוי משום דאיהו<sup data-n=\"2298\">110</sup> וחיוהי חד כו' כידוע, ע\"כ בחי' האור באצי' בבחי' תוקף ההתגלות ובהארה מרובה מאד, אבל כל מה שהאור יורד ומשתלשל למטה יותר הולך ומתמעט יותר ואינו מאיר בתוקף כ\"כ כמו מאצי' לבריאה הרי בירידת האור בבריאה שם נתמעט האור ביותר ואינו מאיר רק בצמצום גדול עד שאין לו ערך עם אור האצי' כידוע, והטעם הוא מפני שיש מסך מפסיק בין אצי' לבריאה ועי\"ז נפסק בחי' הארת הקו שם ואין האור בתוקף וגם הוא מצומצם מאד וכמ\"כ בירידת האור בהשתלשלות יותר מבריאה ליצירה ע\"י מסך שני נתמעט האור עוד יותר בצמצום ויותר אינו מאיר בתוקף עד שבעולם העשי' בא האור בתכלית המיעוט והצמצום ובהעדר תוקף מאד להיותו האחרון ביותר בירידת האור בהשתלשלות, ומלבד כל זאת הנה יש עוד הפרש גדול בעצם המספר של האורות הנק' ע\"ס שבאצי' מאירים בגילוי כל הע\"ס דכח\"ב כו' עד בחי' המל', אבל בעולם הבריאה אינו מאיר בגילוי רק מבחי' אור אימא ולמטה, אבל למעלה מבחי' אור אימא אינו מאיר בגילוי רק בהעלם (וכמבואר בהיכלות דפ' פקודי דג\"ר כח\"ב הן בהעלם כו' דהיינו בהיכל הז' שנק' היכל ק\"ק כו' וכמ\"ש במ\"א) וכמאמר<sup data-n=\"2299\">111</sup> הידוע בזוהר דבחי' אור אימא מקננא בכורסייא שהוא עולם הבריאה בג' ספירן כו' ובירידת ההשתלשלות מבריאה ליצי' מתמעט מספר האורות עוד יותר שאין הגילוי אור ביצירה רק בבחי' ו\"ק בלבד וגם אור אימא אינו מאיר בגילוי רק בהעלם וכמאמר דז\"א מקנן ביצי' בשית ספירן שהוא בחי' מט\"ט דיצירה כידוע עד שבעשי' אינו מאיר בגילוי רק בחי' המל' בלבד, והט\"ס הן בהעלם וכמאמר דמל' מקננא באופן שהוא בעשי' וכן בסדר כללי דשם הוי' יו\"ד באצי' ה\"א בבריאה וי\"ו ביצי' ה\"א בעשי' שהן בחי' או\"א וזו\"נ<sup data-n=\"2300\">112</sup> אור אבא מקנן באצי' אימא בבריאה כו' וכ\"ז בסט' דקדושה דוקא משום דבסט' דקדושה כל מה שהאור יורד יותר למטה יותר מתמעט ויותר מתעלם כנ\"ל, אבל הנה בסט' דקליפה מאחר שנאמר את זלע\"ז עשה כו' ה\"ז בחי' מנגד בסדר ההשתלשלות דהיינו שבסט' דקליפה באה סדר ההשתלשלות דאבי\"ע דקליפה בהיפך מסדר ההשתלשלות דאבי\"ע דקדושה. והענין הוא כמ\"ש בע\"ח דבסט' דקליפה בקליפה דאצי' האור במיעוט מאד ובחלישות גדולה וכל מה שהאור דקליפה בא למטה יותר מתגבר ומאיר בגילוי יותר ובריבוי המספר יותר שהרי האור דקליפה דבריאה תקיף וחזק יותר מאור דקליפה דאצי' ואור דקליפה דיצי' תקיף וחזק יותר מאור דקליפה דבריאה עד שאור דקליפה דעשי' תוקף יותר מקליפה דיצי' וכערך תוקף אור דאצי' דקדושה על אור דעשי' דקדושה כך ערך תוקף אור",[["2298","110","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["2299","111","<b>וכמאמר הידוע בזוהר. . אימא מקננא בכורסייא</b>: ת\"ז ת\"ו (כג, א). תל\"ח (עט, א). וראה מק\"מ זח\"ב רכ, ב. נצוצי אורות זח\"ג קיז א. תניא פל\"ט. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 81."],["2300","112","<b>זו\"נ</b>: בכת\"י ב: ז\"ת."]]],[2101000358,"דקליפה דעשי' על תוקף אור דקליפה דאצי', וכמ\"כ בענין מספר וריבוי האורות דבקליפה דאצי' האורות במיעוט המספר מאד דהיינו שאינו מאיר שם רק בחי' ז' אורות בלבד והן בחי' זו\"נ דקליפה, אבל בבריאה דקליפה מאיר שם גם בחי' חו\"ב דקליפה (והן<sup data-n=\"2301\">114</sup> עמון ומואב והן נק' ענקים ורפאים והן<sup data-n=\"2302\">113</sup> הקיני והקניזי כו' שהוא בחי' ג\"ר דקליפה כמ\"ש במ\"א), ובירידת האור דקליפה יותר מבריאה ליצי' ניתוסף עוד מספר האור עד שמאיר בגילוי גם בחי' הכת\"ר דקליפה ביציר' והוא כמו נבוכדנצר<sup data-n=\"2303\">115</sup> שנא' בו אנת ריש\"א כו' (או פרעה<sup data-n=\"2304\">116</sup> שנאמר הנני עליך התנים הגדול כו' כמ\"ש בזוהר) עד שבקליפה דעשי' מאיר בגילוי גם בחי' עתיק דקליפה, והכל מטעם א' לפי שכל מה שהאור דקליפה יורד יותר למטה יותר מתגבר ויותר מתגלה והוא היפוך הקדושה שכל שהאור יותר עליון הוא יותר בתוקף ויותר בגילוי, והיינו באצי' ששם מאירי' כל הע\"ס בגילוי ובתוקף גדול ואת זלע\"ז כנ\"ל בקליפה דאצי' האור בתכלית הצמצום והמיעוט רק בירידתו למטה מטה בעשי' שם יתרבה ומתגבר כמו שהאור דקדושה מאיר בתוקף למעלה באצי' כו' וד\"ל.\n<b>ושרש</b> הדברים הללו יובן בהקדים הידוע בשרש בחי' קליפה מהו, דהנה פי' קליפה ידוע שהוא כמו הקליפה הגשמי' של הפרי שהוא בחי' חיצוניות ושומר לפרי מבחוץ וקודם שיצמח הגרעין יפרח<sup data-n=\"2305\">117</sup> הקליפה כידוע דקליפה<sup data-n=\"2306\">118</sup> קדמה לפרי כו' וברוחניות היינו בחי' הישות והגסות המורגש מאד כמו ראיתי<sup data-n=\"2307\">119</sup> איש חכם בעיניו כו' שמרגיש בעצמו לחכם ביותר והוא חכם בעיניו בהרגשה גדולה והוא הנק' בחי' ישות של החכמה כשהוא בבחי' י\"ש גדול וכמו\"כ מדת החסד כשמרגיש שפע חסדו לזולתו בבחי' יש ודבר גדול עד שמתפאר לעני<sup data-n=\"2308\">120</sup> כו' ומשבח א\"ע בגודל חסדו שעושה, ומכ\"ש כשעושה יש ודבר למקבל חסדו לומר ראה כמה טובה גמלתיך וכיוצא או כמו חסד דלגרמי' עביד לקנות לו שם כחסד דישמעאל כידוע כ\"ז נק' חסד דקליפה שהוא רק בחי' הישות של החסד הנראה ליש ואז מעורב טו\"ר וכיוצא בזה בכל המדות דקליפה ויש בהן בחי' אורות וכלים, בחי' הכלים הוא בחי' גופו של אותו המציאות הנגלה לחוץ כמו גופו של החסד הנראה ליש כו', ובחי' האור הוא בחי' המשכות האור והחיות ברוחניות להיות בחי' יש כ\"כ במציאות כו' (כמו שמבואר בכמה דוכתי בענין אורות וכלים דקדושה כו'), והנה בחי' אורות דקדושה",[["2301","114","<b>והן</b>: בכת\"י ב: שהן נק' ענקים ורפאים וכן."],["2302","113","<b>והן עמון ומואב. . ג\"ר דקליפה</b>: ראה בארוכה ס' מאמרי אדהאמ\"צ דברים ח\"א ע' יו\"ד ובהנסמן שם."],["2303","115","<b>נבוכדנצר שנא' בו אנת רישא</b>: דניאל ב, לח. וראה לקו\"ת בהעלותך לה, ד. סידור קמג, ד. מאמרי אדהאמ\"צ שם ע' יג ובהנסמן במ\"מ שם. אוה\"ת נ\"ך ע' א'קמא."],["2304","116","<b>פרעה שנאמר הנני עליך התנים הגדול</b>: ראה יחזקאל כט, ג. וראה זח\"ב כח, א. לד, א ואילך."],["2305","117","<b>יפרח</b>: בכת\"י ב: יפרד."],["2306","118","<b>דקליפה קדמה לפרי</b>: לקו\"ת להאריז\"ל ס\"פ וישלח וס' הליקוטים שם. וראה זח\"ב קח, ב. תו\"א סא, א. ביאוה\"ז קיז, ג ואילך. ובכ\"מ."],["2307","119","<b>ראיתי איש חכם בעיניו</b>: משלי כו, יב."],["2308","120","<b>לעני כו'</b>: בכת\"י ב וכת\"י ג: לעיני כל."]]],[2101000359,"הוא היפך הקליפה שהקליפה עיקרה בחי' יש ולגרמי' ה\"ב ה\"ב וכנ\"ל (שעיקר סיבת הישות הוא רק הרגשת עצמו ביותר, ומזה כל חפצו רק לעצמו ולגרמי' וא\"א לו להיות רצון בדבר שאינו נוגע לעצמו כלל כו' וז\"ש לעלוקה<sup data-n=\"2309\">121</sup> שתי בנות הב הב לעצמו כו' וסימן הקדושה הוא להיפך להשפיע דוקא לחוץ מן עצמותו להיות בבחי' האין בלתי ישות כלל כו' וד\"ל), אבל בחי' הקדושה הוא בבחי' האין האמיתי מושלל מבחי' ישות לגמרי, ולהיות האורות דקדושה קרובים אל הקו וחוט שנמשך מאא\"ס שהוא בבחי' האי\"ן האמיתי כו' ע\"כ כל הקרב קרב יותר אל עצמות אא\"ס יותר הוא בבחי' האין (ונק' פרי לגבי בחי' הקליפה כמ\"ש בזהר בכמה דוכתי) דהיינו באורות דאצי' מפני שהן קרובים יותר ומיוחדים יותר באא\"ס ע\"י הקו כנ\"ל יש בהן בחי' האין יותר ובבריאה שנפסק שם האור דקו הנ\"ל ע\"י מסך כנ\"ל אין האור שם בבחי' אין כ\"כ וביציר' ועשי' מתמעט יותר כנ\"ל, והוא שרש ענין הנ\"ל דכל שהאור יורד יותר למטה בסט' דקדושה אינו מאיר בתוקף ובגילוי כ\"כ אלא מתמעט וגם במספר מתמעט כנ\"ל, אבל בחי' הקליפה מאחר שהוא בחי' היש היפך האי\"ן הרי כל מה שיורד יותר ומתרחק יותר מבחי' הקו הנ\"ל יותר הוא בא לבחי' תקפו דהיינו לבחי' הישו\"ת ביותר עד שהוא בחי' יש גמור בבחי' הפירוד גמור בעולם העשי' כנ\"ל, אבל באצי' מפני שבחי' אור דקדושה מאיר שם בתוס' גילוי אור ובתוקף יותר כנ\"ל ממילא אין מקום לבחי' אור דקליפה להאיר שם רק בצמצום ובמיעוט גדול כנ\"ל. וביאור הענין מובן עפ\"י הנ\"ל דבבחי' הקדושה הוא בבחי' האי\"ן שהוא היפך היש, ע\"כ כל מה שאא\"ס מאיר בגילוי יותר ובתוקף יותר יותר מתמעט בחי' היש דקליפה ולכך בחי' קליפה דאצי' אינו בחי' י\"ש גמור שהוא הנק' י\"ש נפרד אלא הוא רק בחי' יש מורגש בלבד (וכמ\"ש<sup data-n=\"2310\">122</sup> במ\"א בפי' ופילגשו ושמה ראומ\"ה רא\"ו מ\"ה רא\"ו שהוא בחי' הביטול דמ\"ה, והוא שמרגיש את הביטול, אבל מ\"מ הרי הוא בבחי' הביטול), וזהו ענין מיעוט וחולשת האור דקליפה באצי' כאשר איננו בבחי' יש מורגש כ\"כ משא\"כ בבריאה שהוא יש גמור בהרגש גדול יותר רק שאינו בבחי' פירוד גמור אלא במקצת וכמ\"ש<sup data-n=\"2311\">123</sup> בע\"ח דנוג\"ה דבריאה רובו טוב ומיעוטו רע כו' משא\"כ באצי' אינו רע כלל וכמ\"ש לא<sup data-n=\"2312\">124</sup> יגורך רע כו', וע\"ז א' שטן<sup data-n=\"2313\">125</sup> ופנינה לש\"ש ממש נתכוין כו' אבל נוג\"ה דבריאה יש בו קצת בבחי' יש נפרד וע\"ז אמרו נתקנא בו נח\"ש באדה\"ר כו' או בא<sup data-n=\"2314\">126</sup> נחש על חוה כו' שהוא בחי' אלקים דקטנות בחי' אחוריים דשם שד\"י דבריאה, והוא ענין מ\"ש ויעש<sup data-n=\"2315\">127</sup> משה נח\"ש הנחושת כו' כמ\"ש במ\"א, ובנוג\"ה דיצי' יש בחי' הפירוד בחציו כי חציו טוב וחציו רע, וע\"ז א' נתן<sup data-n=\"2316\">128</sup> עיניו במקדש והחריבו",[["2309","121","<b>לעלוקה שתי בנות</b>: משלי ל, טו. וראה זח\"א קיא, א. תניא פי\"ט. תו\"א ה, ד."],["2310","122","<b>וכמ\"ש במ\"א בפי' ופילגשו ושמה ראומה</b>: בראשית כב, כד. וראה ס' מאמרי אדהאמ\"צ דברים ח\"א ע' ח, ובהנסמן במ\"מ שם."],["2311","123","<b>וכמ\"ש בע\"ח דנוגה דבריאה רובו טוב</b>: שער הקליפות פ\"ג. ובכ\"מ."],["2312","124","<b>לא יגורך רע</b>: תהלים ה, ה. וראה לקו\"ת במדבר ג, ג."],["2313","125","<b>שטן ופנינה לש\"ש</b>: ב\"ב טז, א."],["2314","126","<b>בא נחש על חוה</b>: שבת קמו, א. וראה שערי זהר שם."],["2315","127","<b>ויעש משה נחש הנחושת</b>: במדבר כא, ט."],["2316","128","<b>נתן עיניו במקדש ראשון והחריבו</b>: סוכה נב, א."]]],[2101000360,"וכמ\"ש במ\"א באריכות עד שבחי' נוג\"ה דעשי' רובו בבחי' הפירוד ומיעוטו טוב בבחי' הביטול ושם נק' מקטרג או יצה\"ר או מלאך המות וכיוצא והיינו שבקשו<sup data-n=\"2317\">129</sup> אנשי כנה\"ג שימסרוהו בידם וכמ\"ש אליהם הנביא זאת<sup data-n=\"2318\">130</sup> הרשעה כו' וממנו נמשך שרש לע\"ז הנק' אלקי' אחרים כו', וכ\"ז מפני שהאור דקדושה תרד יותר למטה יותר מתרבה אור דקליפה ומפני שבאצי' האור דקדושה מאיר בתוקף בבחי' אין אז ממילא אין מקום להתפשטות הישות דקליפה כלל, ע\"כ האור דקליפה באצי' במיעוט מאד כנ\"ל אבל בבריאה שבחי' האור דקדושה במיעוט ולא בתוקף כ\"כ ממילא האור דקליפה דבריאה בהתגברות ובתוקף בבחי' יש יותר דהיינו שהוא קצת בפירוד כנ\"ל, וביצי' שאור דקדושה מתמעט יותר שם מתגבר האור דקליפה בבחי' היש יותר והוא להיות חצי' בפירוד כנ\"ל עד שבעשי' האור דקדושה במיעוט יותר שם הוא ריבוי האור דקליפה יותר עד שנק' רע גמור כנ\"ל, וזהו הכלל דכל שהאור דקדושה מתמעט והולך האור דקליפה מתרבה והולך וכ\"ז מטעם הנ\"ל וד\"ל.\n<b>ואחר</b> שנתבאר בטעם תוקף הקליפה בעשי' יותר מבאצי' יובן ג\"כ הטעם למ\"ש בע\"ח בענין מספר האורות דקליפה שבאצי' אינם רק ז' זו\"נ כנ\"ל, ובבריאה ניתוסף חו\"ב כו' כנ\"ל עד שבעשי' מאיר גם בחי' עתיק דקליפה כנ\"ל, דהנה מבואר בע\"ח דמפני שבבריאה דקדושה אינו מאיר בגילוי רק מאור אימא ולמטה אבל בחי' אור אבא אינו מאיר שם בגילוי רק בהעלם כנ\"ל ע\"כ בבחי' קליפה דבריאה ניתוסף בחי' אורות דאו\"א דקליפה, ועד\"ז ביצירה מפני שאינו מאיר בקדושה גם מבחי' אור אימא רק מבחי' ז\"א כנ\"ל נתרבה עוד בסט' דקליפה להיות מאיר שם גם בחי' כתר דקליפה עד שבעשי' מפני שבקדושה אינו מאיר רק בחי' המל' כנ\"ל ע\"כ ניתוסף בקליפה דעשי' היותר עליון והוא בחי' עתיק דקליפה ובאצי' הוא להיפך ממש מבעשי' שריבוי מספר האורות בקדושה גורם מיעוט מספר האורות בקליפה להיות רק ז' והעיקר הוא בחי' מל' דקליפה בלבד (וע\"ז רמזו שטן<sup data-n=\"2319\">131</sup> ופנינה שהוא בחי' דכר ונוק' דקליפה דאצי' לש\"ש נתכוונו וכמ\"ש וכעסתה<sup data-n=\"2320\">132</sup> צרתה כו' כי חנה בגי' ס\"ג בחי' בינה שבמלכות דקדושה וצרתה בחי' מל' דקליפה ועלי' אמר ורבת<sup data-n=\"2321\">133</sup> בנים אומללה כו' וד\"ל). וביאור כ\"ז מובן עפ\"י הנ\"ל משום דעיקר בחי' הקליפה הוא בחי' היש בלבד, וע\"כ באצי' שמאירים כל הע\"ס גם בחי' ג\"ר אין להקליפה בחי' התפשטות כלל רק להיות בעצם מציאותם בלבד שהן בחי' המדות שבתוהו שנפל בשבירה להיות בבחי' יש אנא אמלוך כו' כידוע, אבל אין להם תוס' אור להגדילם כמו המוחין חב\"ד או הכת\"ר שמגדילים התפשטות ותולדות המדות כידוע אלא הן רק כהווייתן בבחי' מדות בלבד וגם זאת בבחי' הביטול העדר ההתפשטות רק בחי' המל' של המדות מתגלה בלבד, אמנם בבריאה לפי שבחי' הקדושה אינו מאיר בבחי' ג\"ר כח\"ב רק מבחי' בינה ולמטה אזי יש מקום להארת תוס' מוחי' למדות דקליפה והן בחי' או\"א דקליפה שמאירים במדות דקליפה וכמ\"ש כי<sup data-n=\"2322\">134</sup> הגדיל אויב שנמשך",[["2317","129","<b>שבקשו אנשי כנה\"ג</b>: יומא סט, ב."],["2318","130","<b>זאת הרשעה</b>: זכרי' ה, ח."],["2319","131","<b>שטן ופנינה. . לש\"ש נתכוונו</b>: ב\"ב טז, א."],["2320","132","<b>וכעסתה צרתה</b>: שמואל-א א, ו."],["2321","133","<b>ורבת בנים אומללה</b>: שמואל-א ב, ה."],["2322","134","<b>כי הגדיל אויב</b>: איכה א, ט."]]],[2101000361,"לו בחי' מוחי' דגדלות מחו\"ב דקליפה כו' וביצירה שגם בחי' בינה אינו מאיר בקדושה עי\"ז נמשך במדות דקליפה מהיותר עליון גם מחו\"ב והוא מבחי' הכתר דקליפה שהוא הרצון דקליפה שלמעלה מן הטעם כידוע ובעשי' שגם המדות דקדושה הן בהעלם רק בחי' המל' שהוא בחי' המעשה בלבד עי\"ז יגבר ביותר בקליפה להאיר בהם מבחי' היותר עליון גם מבחי' הכת\"ר והוא בחי' עתיק דקליפה שהוא פנימי' הכת\"ר דהיינו בחי' התענוג שלמעלה מן הרצון כידוע (וכמ\"כ להיפך באצי' מפני שמאיר שם בחי' עתיק דקדושה אין מקום להארת הקליפה רק בחי' המל' בלבד כנ\"ל וד\"ל), וכל זה ענין א' עם טעם הנ\"ל בענין תוקף אור הקליפה בעשי' יותר מבאצי' מפני שנתמעט תוקף אור דקדושה בעשי' יותר מכולם מפני ריבוי המסכים שמבדילים ומפסיקים אור הקו הנ\"ל וממילא בעשי' דוקא הוא ריבוי התפשטות היש דקליפה עד שמאיר בהם מבחי' עתיק וא\"א דקליפה שמהם נמשך בחי' אורות המקיפים דז' מדות דקליפה כמשי\"ת (ובכ\"ז יובן מאמר<sup data-n=\"2323\">135</sup> הזוהר ע\"פ הנני עליך פרעה תנים הגדול הרובץ בתוך יאוריו כו' ע\"ש).\n<b>ויובן</b> כ\"ז למעלה בתוס' ביאור ממה שאנו רואים באדם התחתון בנפש האלקי' ונפש הבהמי' שהן ג\"כ ב' מנגדים ובשרשם הם מתנגדים כי שרש הנפש האלקית מבחי' ע\"ס דאבי\"ע דקדושה ושרש הנה\"ב מבחי' נוג\"ה דאבי\"ע כידוע ועליהם אמר ולאום<sup data-n=\"2324\">136</sup> מלאום יאמץ כשזה קם כו' שאם הנפש האלקי' מאירה בתוקף גדול ממילא נופל אור וחיות הנפש הבהמיות ומתמעט אורה במאד וכמ\"ש<sup data-n=\"2325\">137</sup> בזוהר דתוקפא דנפשא חולשא דגופא כו' ובהיפך כשהנפש הבהמיות מאירה בתוקף ממילא תתמעט אור נפש האלקי' וזהו תוקפא דגופא חולשא דנפשא כו', וכמ\"כ בגילוי אור בריבוי או במיעוט במספר הי' כחות כחב\"ד חג\"ת כו' כשהנפש האלקי' מאירה בכל י' כחות שבה גם מהיותר עליון והוא בחי' התענוג והרצון להתענג על ה' בכלות הנפש כו' אזי ממילא יפול האורות והכחות הנה\"ב כמו רצון ושכל ומדות דקליפה עד שלא יאיר רק בחי' המל' שבנה\"ב שהוא בחי' אותיות מחדו\"מ וכיוצא ולהיפך כאשר הנפש הבהמיות דנוג\"ה מאיר בה מהיותר עליון והוא בחי' התענוג והרצון בהנאות טבעיי' וגשמי' וממילא לא יאיר האור דנפש האלקי' רק בבחי' האחרונה שבה כו', וזהו דרך כלל ומזה יובן ג\"כ דרך פרט כאשר יחסר אור החכ' דנפש האלקי' בחי' ביטול דמ\"ה כו' יתוסף אור החכמה בנה\"ב וכמ\"ש ארמי<sup data-n=\"2326\">138</sup> אוב\"ד אבי כו' וכמ\"ש במ\"א וכאשר יחסר גם אור הבינה בנפש האלקי' ואין המדות שבה רק בבחי' הקטנות בלא טעם ודעת אז יתוסף עוד אור יותר עליון בנה\"ב והוא בחי' הרצון שלמעלה מן הטעם וכאשר יחסרו גם התפעלות המדות בנפה\"א יתוסף גם בחי' התענוג בנפש החומריות וז\"ש שמנת<sup data-n=\"2327\">139</sup> עבית כו' אע\"פ שבחי' המעשה עדיין בשלימות בנפש האלקי' (והוא בחי' נפש דעשי' שנק' עשי' שבאצי' בכלל, אבל מי",[["2323","135","<b>מאמר הזוהר ע\"פ הנני עליך פרעה</b>: ראה זח\"ב כח, א. לד, א ואילך."],["2324","136","<b>ולאום מלאום יאמץ כשזה קם</b>: בראשית כה, כג. פירש\"י שם. מגילה ו, א. ובכ\"מ."],["2325","137","<b>וכמ\"ש בזוהר דתוקפא דנפשא חולשא דגופא</b>: זח\"א קפ, ב. קמ, ב."],["2326","138","<b>ארמי אוב\"ד אבי</b>: דברים כו, ה."],["2327","139","<b>שמנת עבית</b>: דברים לב, טו."]]],[2101000362,"שהוא בבחי' רוח דיציר' שהן המדות לא יאיר בנפשו הבהמיות מבחי' התענוג, ומי שהוא בבחי' נשמה שבבריאה לא יאיר בנפשו הבהמיות גם מהרצון ובבחי' חי' בחי' חכמה שבאצי' לא יאיר בנפשו הבהמיות גם מחו\"ב ובבחי' יחידה שבאצי' לא יאיר גם המדות כו', וז\"ש מיד<sup data-n=\"2328\">140</sup> כל\"ב יחידת\"י כי כל\"ב הוא בחי' נוג\"ה אחוריים דשם ב\"ן כידוע. וכמ\"כ בדוגמא זו יובן למעלה בהפרש שבין סט' דקדושה לסט' דקליפה בסדר ההשתלשלות דאבי\"ע מאחר שבצלם אלקי' עשה את האדם כו', וכיוצא בכ\"ז יובן בכללות נש\"י הכלולי' בשיעור קומה של אדם העליון שנק' אדם דאצי' וכמארז\"ל אתם<sup data-n=\"2329\">141</sup> קרוים אד\"ם שעכשיו בזמן עקבות משיחא שהאור אינו מאיר רק בבחי' נהי\"ם<sup data-n=\"2330\">142</sup> בבחי' האחרונה יש התקשרות<sup data-n=\"2331\">143</sup> לאדם דקליפה דעשי' גם בבחי' אור עתיק דקליפה כנ\"ל וזהו ענין המאמר דרישא<sup data-n=\"2332\">144</sup> שכיבת לעפרא וזנבא שליט כו' וז\"ש קולה<sup data-n=\"2333\">145</sup> כנח\"ש ילך כו', והוא ענין מ\"ש אל הנחש דקליפה הוא ישופך ראש ואתה תשופנו עקב בעקבות משיחא, אבל בימות המשיח שמאיר בכללות נש\"י מבחי' ג\"ר דע\"י כו' כמ\"ש ונחה<sup data-n=\"2334\">146</sup> עליו רוח חכמה כו' והריחו כו' אז יהי' מיעוט האור דקליפה בתכלית וכמ\"ש ואת<sup data-n=\"2335\">147</sup> רוח הטומאה אעביר כו' וז\"ש הוא ישופך ראש בבחי' ג\"ר דקליפה כו' (ומה שאמר עשו הכי<sup data-n=\"2336\">148</sup> קרא שמו יעקב ויעקבני זה פעמים את בכורתי לקח כו' כי הנה ביעקב נאמר וידו אוחזת בעקב עשו ע\"כ קרא שמו יעקב והוא בחי' בירור דשם מ\"ה שמברר לבחי' נוג\"ה דעשו עד בחי' העקביים שבו שנק' עקב עשו וז\"ש ועלו<sup data-n=\"2337\">149</sup> מושיעים בהר ציון לשפוט את הר עשו ואז והיתה לה' המלוכה כו', וזהו פי' יעקב<sup data-n=\"2338\">150</sup> יו\"ד עקב כידוע, והיינו מ\"ש עת<sup data-n=\"2339\">151</sup> אשר שלט האדם באדם לרע לו כי בהתלבשות השכינה בגלות בע\"ש דקליפה דעשי' מתבררים עי\"ז, וז\"ש ויעקבני זה פעמיים את בכורתי בחי' חכמה דקליפה והוא בימי שלמה ועתה לקח ברכתי מבחי' עתיק כו' והוא בימות המשיח כנ\"ל, וז\"ש בא אחיך במרמה כו', וכ\"ז מטעם הנ\"ל בשרש ההפרש בין סט' דקדושה לסט' דקליפה כו' וד\"ל).\n<b>ואחר</b> כל הנ\"ל בענין ההפרש בין סט' דקדושה לסט' דקליפה שבקליפה כל שירד ומתרחק יותר יגדל האור ויתרבה גם במספר עד שבעשי' מאיר שם גם מבחי' עתיק דקליפה שממנו נמשך בחי' המקיפים ז' מדות דקליפה כנ\"ל, מעתה יובן",[["2328","140","<b>מיד כל\"ב יחידת\"י</b>: תהלים כב, כא. וראה ג\"כ לקו\"ת ראה כה, א."],["2329","141","<b>אתם קרוים אד\"ם</b>: יבמות סא, א."],["2330","142","<b>נהי\"ם</b>: בכת\"י ב: נו\"ה."],["2331","143","<b>התקשרות</b>: בכת\"י ב וכת\"י ג: התגברות."],["2332","144","<b>דרישא שכיבת לעפרא</b>: זח\"ג קיט, ב. וראה ע\"ח שמ\"ח פ\"ג. וראה סה\"מ אתהלך לאזניא ע' קמו. ביאוה\"ז קמג, א ואילך. אמ\"ב שער הק\"ש ס\"פ צג. תו\"ח שמות נח א. אוה\"ת נ\"ך ע' שפז."],["2333","145","<b>קולה כנח\"ש ילך</b>: ירמי' מו, כב. ראה בהנסמן לעיל."],["2334","146","<b>ונחה עליו רוח חכמה</b>: ישעי' יא, ב ואילך. וראה סה\"מ תקס\"ב ע' סב. ובכ\"מ."],["2335","147","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["2336","148","<b>הכי קרא שמו יעקב</b>: בראשית כז, לו. וראה לקו\"ת בלק עד, ג. ובכ\"מ."],["2337","149","<b>ועלו מושיעים בהר ציון</b>: סוף עובדי'. וראה אוה\"ת נ\"ך כרך ב' ע' תתצט."],["2338","150","<b>יעקב יו\"ד עקב</b>: ע\"ח ש\"ג ספ\"ב. פרדס שעה\"כ בערכו."],["2339","151","<b>עת אשר שלט האדם באדם לרע לו</b>: קהלת ח, ט. וראה זח\"ב צה, ב. פרדס שט\"ז פ\"ז."]]],[2101000363,"שרש טעם הקרבת ע' פרים החג שהן לנגד ע' שרים דקליפה דעשי' כנ\"ל שהן לנגד ע' נפש דיעקב כו' דהיינו שע\"י הע' פרים מבררים בהן מבחי' המקיפים דוקא כי הרי בעשי' מאיר שם מבחי' ג\"ר דקליפה שהוא בחי' עתיק שנמשכים ממנו י\"ג ת\"ד דקליפה (ע\"ד שנמשכים י\"ג ת\"ד מבחי' עתיק דאצי' המלובש במו\"ס, וז\"ש ביום<sup data-n=\"2340\">152</sup> ההוא יגלח בתער השכירה במלך אשור כו' וגם הזקן ושער הרגלים כו', וכמבואר<sup data-n=\"2341\">153</sup> בגמרא דחלק ובזהר פ' תזריע ולטעם זה נק' מלך זקן וכסיל כו' כי פי' זקן שקנ\"ה חכמ\"ה דקליפה שנק' כסילות כמ\"ש שיש יתרון לחכמה מן הסכלות כו'), וטעם מספר ע' מבואר למעלה מפני ששרשם מבחי' ז' מדות דתוהו שכאו\"א כלול מי' כנ\"ל וכמ\"ש ואלה המלכים כו' כידוע וד\"ל.\n<b>אך</b> הנה עדיין י\"ל תירוץ הקושי' הנ\"ל שבע' פרי החג אע\"פ שניתנו להם יניקה בחיצוני' עי\"ז מתברר מהם בחי' הפנימי' שנפל מז' מלכים דתוהו כו'. והנה תחלה יש להבין למה דווקא בז' ימי החג בסוכות דווקא מקריבין הע' פרים בשביל הע' שרים ולא בזמן אחר כו'. אך הנה מבואר הטעם למעלה משום דבז' ימי החג מאיר בבחי' הקדושה מבחי' אורות המקיפי' דאימא שהוא בחי' אור גדול ותקיף ביותר ע\"כ יש ביכולתם לברר ז' מקיפי' דמדו' דקליפה המלובש בע' שרי' דעשי' ולהוציא הטוב הגנוז בהן משא\"כ בשאר ימות השנה שאין ההארה רק בבחי' ז' מדו' דז\"א שאינם אורות תקיפי' אינן ביכולתן לברר לז' מקיפי' דקליפה כ\"כ, וזהו ענין הז' אושפיזין שנק'<sup data-n=\"2342\">154</sup> ז' רועי' אברהם ויצחק כו' להיותם מבחי' ז' מקיפי' דבינה כידוע וביאור זה ידוע שיש ב' מיני מדות הא' המדו' שנולדי' מן השכל שהן בבחי' הצמצום והקטנות מפני צמצום המשכת השכל להוליד המדה ולמעלה היינו בחי' מדות דז\"א שנולדי' מאימא עילאה אבל המדות שבשכל הן המתהווים עם גוף השכל כמו התפעלות אהבה בשכל עצמו שהוא התפעלות שכלי' ונק' חסד דאימא ועד\"ז בחי' התפעלות יראה בשכל ונק' גבו' דאימא כו' ועד\"ז כל הז' מדות דבינה ולהיותם בבחי' שכל ממש הם רחבי' בהתפשטות יתירה ונק' בשם בחי' מקיפי' על ז' המדות שנולדו מצמצום הארת השכל הנק' ז' מדות דז\"א כנ\"ל, ונק' ג\"כ בשם ז' רועים מפני שמפרנסי' וממשיכים תמיד אור וחיות אל המדות שבלב שנק' בנים לאימא עילאה וכנראה בחוש הטבעיו' של המדו' שבלב כמו האהבה התלוי' בדבר שאם בטילה דבר בטילה ממילא האהבה אבל מ\"מ עדיין נשאר בחי' אור המקיף של האהבה כמו שהיא בהרחבה בשכל ואז לא תבטל לגמרי כי תוכל לחזור ולהתעורר בלב כמו הדלקת והבערת הניצוץ מן הגחלת או השלהבת שהוא המשכה מהעלם המקיף לגילוי או\"פ כנ\"ל כו', אבל אם גם המקיף נסתלק אז יש לה ביטול עולמית (וז\"ש אם<sup data-n=\"2343\">155</sup> תעירו ואם תעוררו את האהבה כו' וכיוצא) ועד\"ז יש בחי' מקיף לכל מדה מז' המדות",[["2340","152","<b>ביום ההוא יגלח בתער השכירה</b>: ראה ישעי' ז, כ."],["2341","153","<b>וכמבואר בגמ' דחלק ובזוהר פ' תזריע</b>: סנהדרין צה, ב ואילך. זח\"ג מח, ב ואילך. וראה ביאוה\"ז שם (עא, ב). דרוש דתער השכירה באוה\"ת נ\"ך כרך ב' ע' תשעט ואילך."],["2342","154","<b>שנק' ז' רועים. . מפני שמפרנסים</b>: ראה סוכה נב, ב. תניא פמ\"ב."],["2343","155","<b>אם תעירו ואם תעוררו</b>: שה\"ש ב, ז. ג, ה."]]],[2101000364,"שבלב וכללותם נק' ז\"ת דבינה והן הנק' למעלה בשם אושפיזין עד\"מ האורח החשוב שאינו רגיל לבא תמיד רק לפרקים ועיתים רחוקי' לצורך גדול כמו לעזור או לשמחה כו', וכך בז' ימי הסוכות באים ומאירי' בז\"א מבחי' ז' מקיפי' דאימא שנק' ז' רועים, וע\"כ הוא זמן שמחתינו כמו ששמחים באורח חשוב, ונק' אושפיזין עילאי' כמו בחי' חסד דאברהם ביום הא' הוא בחי' חסד דאימא המאיר מן ההעלם המקיף לחסד דז\"א וביום הב' מאיר מבחי' גבו' דאימא לגבו' דז\"א והן אברהם ויצחק ועד\"ז כל ז' הימים וד\"ל.\n<b>ומעתה</b> יש להבין למה הטעם שביום הא' דסוכות מקריבי' י\"ג פרים וביום הב' י\"ב פרים ועד\"ז מתמעטי' והולכי' עד שביום הז' אין מקריבי' רק ז' פרים ובשמ\"ע רק פר א' כו'. הענין הוא משום דעיקר התגלות ז' מקיפי' דאימא בסוכות הוא בשביל עזר הבירורים דע' שרים דעשי' להוציא מהם הטוב שנפל מז' מלכי' דתוהו שמתו כנ\"ל, ולפי שעיקר השבירה הי' בבחי' ס\"ג דבינה והוא בחי' ז\"ת דבינה דנקודי' כמ\"ש בע\"ח ולכך א\"א שיבורר מהם כ\"א בבחי' מדות דבינה דקדושה להיותם אורות תקיפי' יש ביכולתם לברר גם לבחי' מדות דבינה דתוהו שנפלו בע\"ש דעשי' כנ\"ל, והנה בוודאי כל אור היותר גבוה במדריג' במדות דאימא יותר הוא יורד ומברר לאור הקליפה התקיף יותר למטה, וע\"כ ביום הא' דסוכות שמאיר אור חסד דאימא שהוא הראשון במדריגה והוא אור תקיף ביותר מבחי' המשכת החסד בתוקף אור גדול ביותר לירד שמגבוה לנמוך ביותר יותר יש ביכולתו לברר לאור הקליפה הנמוך ותקיף יותר, והוא בחי' עתיק דקליפה דעשי' הנ\"ל, והיינו ענין י\"ג פרים שמקריבי' ביום הא' שהם לנגד בחי' י\"ג מקיפי' דקליפה שנמשכי' מבחי' י\"ג ת\"ד דעתיק דעשי' דקליפה שהן באי' מבחי' מותרי מו\"ס דא\"א דקליפה דעשי' (כמו שבקדושה נמשכי' י\"ג מדה\"ר בי\"ג ת\"ד ממותרי מו\"ס דא\"א כו'), וזהו<sup data-n=\"2344\">156</sup> דווקא ביום הא' אבל ביום הב' שמאיר מבחי' גבו' דאימא שלמטה מבחי' חסד שאין כחה גדול כ\"כ אין ביכולתה לברר כ\"כ ונתמעט הבירור בפר א', ועד\"ז מתמעט הבירור בכל יום עד שביום הז' להיות שהאור המאיר בו הוא מדריגה האחרונה שהוא בחי' מל' דאימא אין הבירור רק ז' פרים בלבד וד\"ל.\n<b>(ובכ\"ז</b> יתורץ גם הקושי' הנ\"ל דאעפ\"י שנותני' להם יניקה בחיצוניו' הנה עי\"ז נברר מהן בחי' הפנימיו' כי ע\"י הקרבן וזריקת דם לא נמשך להם יניקה רק מחיצוני' המדות דז\"א שנופל בבחי' מותרות כידוע בענין הקרבנות, אבל עי\"ז נבדל מהם בחי' הפנימיו' שיש בהן מז' מלכים דתוהו ונכללי' בז' מדות דאימא דקדושה הנק' אושפיזין, וזהו ענין המשל הנז' בזוהר למלך שעשה סעודה לבני היכלא כו', וז\"ש אם<sup data-n=\"2345\">157</sup> רעב שונאך האכילהו לחם, הקרבנות<sup data-n=\"2346\">158</sup> שנק' לחמי כו' כי גחלים אתה חותה כו' לברר עי\"ז בחי' הטוב וישאר ריקם כו', ועד\"מ באדם התחתון",[["2344","156","<b>וזהו. . בלבד וד\"ל</b>: בכת\"י ב וכת\"י ג ליתא קטע זה."],["2345","157","<b>אם רעב שונאך</b>: משלי כה, כא."],["2346","158","<b>הקרבנות שנק' לחמי</b>: ראה לקוטי שיחות חי\"ב ע' 18 ובהנסמן שם."]]],[2101000365,"שמתחזק שכלו ע\"י המאכל שנברר ממנו הטוב והפנימיו' אע\"פ שהי' עלי' למאכל ליכלל בבחי' אדם אבל עלי' זו ירידה היא להוציא ממנו הטוב והפסולת נדחה כו' כידוע, והיינו ע\"י האושפיזין הנ\"ל שמבררי' כל ז' מלכים דתוהו מע' שרים דעשי' כנ\"ל וד\"ל).\n<b>ועוד</b> יובן ענין מיעוט הפרים בכל יום עד יום הז' שאינן רק ז' פרים ע\"ד הנ\"ל בסדר ההשתלשלות דקליפה שבאצי' אינם רק ז' זו\"נ ובעשי' בע\"ס דקליפה מאיר גם בחי' העלם דג\"ר כח\"ב לעומת מספר י\"ג דאחד דקדושה כמ'ש במ\"א וע\"כ מתמעטי' והולכי' עד שביום הז' לא נשאר בקליפה רק ז' מדות כעצם מציאותן בתחלת השבי' כמו שהן באצי', ובחי' חסד דאימא ביום הא' מברר לקליפה דעשי' שהם י\"ג כנ\"ל וביום הב' בחי' גבו' דאימא מברר קליפה דיצי' שנחסר שם אור עתיק כנ\"ל, וביום הג' ת\"ת דאימא מברר לקליפה דבריאה שהן י\"א ארורים דהיינו חב\"ד חג\"ת כו' והכתר שעליהם מאיר בבחי' מקיף והן ג' מדריגות נר\"נ ובאצי' מתבררי' ע\"ס הנשארי' ביום הד' ע\"י בחי' נצח דאימא וביום הה' מתבררי' ט\"ס הנשארים וביום הוי\"ו מתבררי' ח' ספירות שהן בינה וז' מדות עד שביום הז' מתבררי' גם ז' מדות דקליפה שנק' ז' פרות הרעות כו' והן בחי' זו\"נ דקליפה כנ\"ל וד\"ל.\n<b>ומעתה</b> יש להבין טעם הקרבת פר א' בלבד בשמ\"ע וכמשל דעביד סעודתא לברי' יחידאה כו' כמ\"ש בזוהר, דהנה חג שמ\"ע הוא חג בפ\"ע לשמחה והוא שמחה שני' כמבואר דהיינו שמחה של ישראל כי בז' הימים הי' השמחה על בירור הטוב מע' שרי' בלבד שהוא הבירור בז' מלכים כנ\"ל אבל בשמ\"ע הוא הבירור בישראל שהן מבחי' התיקון דקדושה, וזהו פי' עצרת לשון קליטה ובירור, אך עצרת הזה לכם דווקא, ולא יפלא למה צריך בירור בקדושה הלא אין רע למעלה כלל, הענין הוא שגם בקדושה שייך בירור בשביל ההעלאה בעילוי יותר ממדריגה הראשונה כו' כמו שמצינו במשה<sup data-n=\"2347\">159</sup> שלא אכל לחם בהר סיני אלא לחם שמלאכי השרת אוכלין והרי המלאכים הם כוחות אלוקיי' והאיך שייך לומר שיאכלו הרי האכילה היא בחי' בירור כידוע וכמו\"כ אנו מוצאי' בבחי' המן שלא הי' מבחי' נוג\"ה כלל כמו שאר המזונות שמעורבי' טו\"ר וע\"כ יש בהם פסולת אבל המן אין בו פסולת ואעפ\"כ אכלוהו בבחי' אכילה שנק' בירור, ונמצא יש בחי' בירור גם בדבר שהוא בבחי' הקדושה ממש (והיינו<sup data-n=\"2348\">160</sup> ענין בחי' בירור שני הנ\"ל בענין מ\"ד שמברר למ\"נ בקרבנות כמו ארי' דאכיל קרבנין כו', והוא הנק' בחי' קליטה שקולט המ\"ד את המ\"נ והמ\"ן נקלט בו כו', וז\"ש עצרת תהי' לכם דווקא וד\"ל, וזהו ענין שמחה הב' בשמ\"ע שהוא בחי' הבירור בקדושה לבנ\"י דוקא, והיינו המשל למלך שעושה סעודה לבנו כו' וד\"ל, ולזה הטעם אין מקריבי' רק פר א' לנגד ישראל בלבד כי הנה בחי' ז' אושפיזין הנ\"ל שהן ז' מקיפי' דאימא בכל ז' ימי החג מפני שמבררי' לטוב שבע' שרים דעשי' אינן מאירי' בז' מדות דז\"א רק בהעלם ולא בגילוי בבחי' אור פנימי'",[["2347","159","<b>במשה. . לחם שמלאכי השרת אוכלין</b>: ראה יומא עה, ב. לקו\"ת דרושים לש\"ש סו, א. לקוטי שיחות ח\"ד ע' 1037."],["2348","160","<b>(והיינו</b>: בהכת\"י חסר סיום המוסגר."]]],[2101000366,"וע\"כ נאמר ז' ימים תשבו בסוכות בצל המקיפי' בבחי' ההעלם עדיין, אך בשמ\"ע שהוא לנגד ישראל שא\"צ בירור כי לא היו בבחי' השבירה כמ\"ש הפח<sup data-n=\"2349\">161</sup> נשבר ואנחנו נמלטנו כו' וכמו שאמ' למכה<sup data-n=\"2350\">162</sup> מלכים גדולים כו' ונתן ארצם לנחלה לישראל וכן לגוזר ים סוף כו' והעביר ישראל בתוכו כמ\"ש במ\"א אזי נמשכי' ומאירי' כל הז' מקיפי' הנק' אושפיזין במדות דז\"א שנק' ישראל בבחי' הגילוי בבחי' או\"פ שהוא בחי' הקליטה שנק' עצרת כנ\"ל, וזהו עצרת תהי' לכם דווקא, וע\"כ אינו אלא פר א' בלבד כו' כי הקרבן הזה בשביל ישראל שנק' אחד, והוא ענין הסעודה שעושה לברי' יחידאה כמ\"ש בזוהר וד\"ל.\n<b>ובכל</b> זה מובן פי' הללו את ה' כל גוים כו' שהן ע' פרי החג שמתברר מהם כל בחי' הטוב כנ\"ל ועי\"ז יגבר עלינו חסדו בבחי' הארת ז' מקיפי' בסוכות שנק' זמן שמחתינו כנ\"ל ובשמ\"ע נמשך בבחי' קליטה ממש וזהו ואמת ה' בא בגילוי לעלמא דנוק' שהן כנ\"י כידוע וד\"ל.",[["2349","161","<b>הפח נשבר ואנחנו נמלטנו</b>: תהלים קכד, ז."],["2350","162","<b>למכה מלכים גדולים</b>: תהלים קלו, יז ואילך."]]],[2101000367,"<h3>ביאור על ד\"ה צדקת פרזונו תקס\"ט - מכ\"ק אדמו\"ר הצ\"צ</h3>\n<b></b><b>ביאור מכ\"ק אדמו\"ר הצ\"צ לד\"ה צדקת פרזונו תקס\"ט להדרוש צדקת פרזונו בביכעל מו\"ח מן תקס\"ט<sup data-n=\"2351\">1</sup> </b>\nהעתק<sup data-n=\"2352\">2</sup> על פערטיל כת\"י רנ\"ח ושם דס\"ה ע\"ב\nועיין<sup data-n=\"2353\">3</sup> בש\"ע אאזמ\"ו סי' א' המתחיל יהודא בן תימא ושם ס\"ח כי עת רצון שלמעלה וכו' למעלה מגדר המקום והזמן, וצ\"ע אם הוא למעלה מגדר הזמן א\"כ איך שייך וישבות ביום השביעי, וג\"כ א\"כ למעלה תמיד הוא שבת ופסח, וגם חול, ואיך יתכן זה. ואפ\"ל דהנה בתשובת הרשב\"א ח\"א סי' ט' כתב וז\"ל וגדולה מזו דבר הכתוב תילים סי' ק\"ב ואתה הוא ושנותיך לא יתמו, ושנותיך הכוונה בא\"ס ובאין תחלה ואיך אמר שנותיך כנגד ההתחלה ואז לא הי' שנים למאמיני החדוש, ויותר מזה שהוא יתברך לא יפול בו מנין שנים וזמן, שאינו בזמן כי הוא אדון הזמנים, ולמעלה מהם ית' עילוי רב מכל אלה הדמיונות, אלא שדיבר הכתוב דרך אמירה זהו שרז\"ל קורין לזה שברות האוזן באמרם בכמה מקומות כדי לשבר את האוזן במה שהיא יכולה לשמוע עכ\"ל, הרי מ\"מ המכוון מהפסוק שמציאותו ית' קיים המשך בלי תכלית לו כאלו עברו עליו שנים בלי גבול, באין תחלה ובאין סוף רק שאינו בבחי' מנין שנים וזמן כ\"א למעלה מהן עילוי רב, ולכן נאמר כן ושנותיך כי האוזן אינה יכולה להבין המשך וקיום בלי גבול ובלי תכלית רק בבחי' זמן, ולכן נאמר כן שכמו שיצייר האדם המשך בלי תכלית בבחי' זמן כאלו תאמר זמן בלתי מוגבל, שאי אפשר לאדם לצייר המשך בלי תכלית רק בבחי' זמן, וכך הוא המשך וקיום הבורא ית' בלי גבול ותכלית, רק שהמשך זה הבלתי מוגבל מרומם לאין קץ מבחי' זמן, כמו שמרומם מבחי' מקום, ולפי שא\"א להאדם לצייר המשך בלי גבול שאינו בבחי' זמן, ע\"כ אמר הכתוב בלשון זמן בלתי מוגבל, וזהו ואתה הוא ושנותיך לא יתמו. וכ\"כ הרמב\"ם במ\"נ ח\"ב פי\"ג וז\"ל, שהזמן עצמו ג\"כ מכלל הנבראים כו', ושזה אשר יאמר הי' הבורא קודם שיברא העולם, וכן כל מה שיעלה בשכל מהמשך מציאותו קודם בריאות העולם המשך אין תכלית לו כל זה שער זמן או דמות זמן לא אמתת זמן עכ\"ל, ופי' שער זמן או דמות זמן כתב האפודי רוצה לומר שלא הי' שם זמן במציאות כלל, אלא שהשכל משער הזמן או הדמיון מדמהו אע\"פ שאין הענין כן כי הזמן נברא בלא ספק עכ\"ל. וא\"כ הרי הרמב\"ם שסובר ג\"כ שהזמן נברא ומחודש עכ\"ז כ' ג\"כ דפי' הי' הבורא קודם שנברא העולם הוא ענין המשך מציאותו קודם",[["2351","1","אולי הכוונה לד\"ה זה הנדפס בתו\"ח שמות שמט, ב. וראה ג\"כ אוה\"ת בשלח ע' תרפה. אוה\"ת נ\"ך ע' יג.\nהביאור דלקמן נדפס ג\"כ באוה\"ת נ\"ך (כרך ג) ע' א'קסז."],["2352","2","<b>העתק על פערטיל כת\"י רנ\"ח</b>: ראה להלן ברשימת המאמרים ומ\"מ הכת\"י, הע' 17."],["2353","3","<b>ועיין בש\"ע אאזמ\"ו</b>: לכללות הבא להלן ראה ג\"כ ספר החקירה להצ\"צ קיא, ב ואילך. דרמ\"צ מצות האמנת אלקות פי\"א ואילך. אוה\"ת דרושים לש\"ש ע' א'תקכא. ד\"ה מים רבים תשי\"ז (קרוב לסיומו). לקוטי שיחות ח\"י ע' 176 ואילך. חט\"ז ע' 98."]]],[2101000368,"בריאת העולם המשך אין תכלית לו, רק שאינו בבחי' זמן, וא\"כ עכ\"פ שייך הלשון המשך מציאותו המשך אין תכלית לו, כמו המשך שאין לו תכלית בזמן, אלא שזה הוא למעלה מבחי' זמן. ועד\"מ ענין הימים למעלה הם ז' ספירות חג\"ת נהי\"ם הן שרש לשבעה ימי בראשית, אבל הם אינן כלל בבחי' זמן אלא הם ז' מדות עליונות, וביום השבת הוא עליות המדות לבחי' בינה שהיא למעלה מבחי' מדות ושם מאיר מבחי' דלאו מכל אלין מדות איהו כלל, גם שייך למעלה ענין י\"ב חדשים שהם י\"ב גבולי אלכסון או הם י\"ב מלאכים דבריאה שבמרכבה הנק' י\"ב בקר והים עליהם מלמעלה, ועד\"ז יש שנים ושמיטות ויובלות, א\"כ לפי\"ז שייך ענין שבת למעלה דווקא בבחי' מיוחדת מימי החול, אע\"פ שאין שם זמן, והיינו כי ימי החול הם ו\"ק חג\"ת נה\"י ושבת הוא בינה, היינו עליות המדות בבינה, וכן שייך ענין יוהכ\"פ שהוא התגלות עתיקא, ואפ\"ל ג\"כ שאין כל בחי' אלו תמיד יחד כ\"א כשנק' ימי המעשה אינו שבת, וכשנק' שבת למעלה אינן ימי המעשה, כי כל מדה ומדריגה היא בחי' בפ\"ע, ומאחר שלימדנו הראשונים ששייך לומר המשך בלי תכלית למעלה שנמשל בפסוק להמשך זמן ממש בלי תכלית, היינו מ\"ש ושנותיך לא יתמו, וא\"כ בהמשך בלי תכלית שבזמן ודאי שייך ימי החול ויום השבת ור\"ח ופסח ור\"ה, א\"כ מאחר שהפסוק אומר משל לקיום מציאותו ית' מזמן בלתי גבול, א\"כ יש לנו לייחס בחי' אלו דחול ושבת ור\"ח למעלה, אלא שלפי האמת המשך זה הבלי גבול גבהה הרבה מהמשך הזמן, ואין השכל משיג איך הוא, כמו שאינו משיג איך שאינו בבחי' מקום כלל, לכן עכ\"פ שייך יום השבת למעלה מה שאינו מאיר בימי המעשה והכל הוא למעלה מהזמן, והיינו הארת המדות זהו ימי המעשה וכשמתעלים בבינה נק' וישבות ביום השביעי, שהבינה נק' שביעאה עילאה בזח\"ג פ' תזריע דמ\"ז ע\"ב, ובזח\"א פ' בראשית דמ\"ז ע\"ב, ועיין בהביאור ע\"פ אכלוהו היום שבת\"א פ' בשלח ושם בהביאור כ' בענין הזמן ג' בחי', וזה סדרן מלמטה למעלה, הא' בבי\"ע שם שייך זמן ממש יום ולילה, הב' באצי' שם הוא למעלה מהזמן, ומ\"מ שייך שם קודם ומתאחר כמו תחלה נאצל מדת חסד ואח\"כ גבורה ואח\"כ רחמים כו', וע\"כ נקראים ששת ימים, הג' בחי' כתר וכ\"ש בחי' אור א\"ס שם אין שייך קודם ומתאחר, כי שם עבר הוה ועתיד הכל בבת אחת, דהיינו ענין שם הוי' שהוא היה הוה ויהיה, אבל מ\"מ שייך גם הענין שיאמר בלשון בני אדם המשך מציאותו המשך אין תכלית לו, אע\"פ שאין שייך בהמשך זה קודם ומתאחר כלל, כמ\"ש בס' העקרים מאמר שני פרק<sup data-n=\"2354\">4</sup> וכ\"ש לפ\"ד האפודי.\n<b>ומעתה</b> י\"ל ענין יום השבת זהו עליות ו\"ק דאצילות שבהם שייך קודם ואיחור כשעולים לקבל מאוא\"ס, משא\"כ בימי המעשה אין בהם גילוי אור א\"ס בערך זה כלל, וכעד\"ז היו\"ט ור\"ה ויוהכ\"פ, ומ\"מ הכל למעלה מהזמן דבי\"ע, אך כשנמשך משם להאיר בבי\"ע מאיר לכל מקום בזמנו ממש, כמו בשבת מאיר הבינה הנק' יום השביעי היא מאירה למטה ביום השביעי דווקא, וכן ענין יום הדין מאיר בר\"ה באחד לחודש השביעי, והסליחה דווקא ביוהכ\"פ שלמטה מאירים כל בחי' אלו שהם למעלה מהזמן רק הם מכונים יום השביעי מטעם הנ\"ל שהבינה היא שביעאה,",[["2354","4","<b>פרק</b>: בגוכי\"ק יש כאן מקום פנוי לתיבה אחת, וצ\"ל: פרק י\"ח."]]],[2101000369,"וכן מכונים באחד לחודש השביעי כל בחי' אלו מאירים למטה בזמן ומקום דווקא, היינו מה שהוא למטה יום השביעי ממש בבחי' זמן אזי דווקא מאיר בו הבינה, וכן עד\"ז בר\"ה והיינו ע\"י שהארה זו שנמשכה מלמעלה מהזמן היא מאירה דווקא ע\"י בחי' מלכות דאצי' מקור דבי\"ע אשר בה כבר יש שורש לבחי' זמן ממש בבי\"ע, ועיין מזה בסש\"ב ח\"ב פ\"ז וז\"ל, והנה אע\"פ שהוא יתברך למעלה מהמקום והזמן, אעפ\"כ הוא נמצא גם למטה במקום וזמן דהיינו שמתייחד במדת מלכותו ית' שממנה נמשך ונתהווה המקום והזמן וכו' עכ\"ל. וזה קרוב למ\"ש בעה\"ק ח\"א רפ\"ח וז\"ל א\"ס הוא שלימות מבלי חסרון, ואם תאמר שיש לו כח בלי גבול ואין לו כח בגבול אתה מחסר שלימותו כו' והגבול הנמצא ממנו תחילה הם הספירות, עכ\"ל. וא\"כ מצד הכח הנמצא ממנו להאיר בגבול שייך מקום וזמן, דדוקא מצד בחי' הנקרא אין סוף ובלי גבול אין שייך מקום וזמן, אבל מצד כח הגבול י\"ל שייך מקום וזמן, ומ\"מ היינו מקום רוחני כמו מעלה ומטה במדריג' כמ\"ש בת\"א פ' וארא בד\"ה וארא אל אברהם, אבל מצד עצמותו מעלה ומטה שוין, וא\"כ מדת מלכותו שהוא שורש המקום והזמן י\"ל שרשה מבחי' מה שיש באוא\"ס ב\"ה ג\"כ כח הגבול, וכענין<sup data-n=\"2355\">5</sup> שיעור קומה רל\"ו אלפים רבבות פרסאות, ומה שמתייחד עם מדת מלכותו זהו מה שמאיר בחי' א\"ס בכח שבבחי' גבול כו', או עכ\"פ תוספת וריבוי אור כו'.\n<b>והנה</b> הזמן שבבחי' מל' ג\"כ גבוה מזמן הגשמי וכענין אלף שנים בעיניך כיום אתמול, וא\"כ עפי\"ז יובן איך שייך וישבות ביום השביעי, כיון מצד כח הגבול שבא\"ס שהוא בחי' מל' שייך זמן, והוא ית' עצמו שלמעלה מהזמן מאיר בבחי' זמן ג\"כ, והיינו ענין השבת ויו\"ט, וז\"ש ביו\"ט מקדש ישראל והזמנים, וכיון שמ\"מ זמן ובחי' יום השביעי שבמ' אינו כזמן גשמי שלנו, ע\"כ א\"ש שבחי' זו מאיר בזמן שלנו שלמטה לכל מקום כפי זמנו כו', ואע\"פ שיש מקום כשאצלינו מתחיל יום השבת אצלם הוא עדיין אינו שבת, מאיר להם שבת בזמנם, כי בחי' שבת שבמל' אף ששם שייך זמן אינו ממש כזמן שלנו כו', א\"כ נק' ג\"כ למעלה מהזמן לגבי זמן שלנו כו'.\n<b>וז\"ש</b> רבינו ז\"ל בש\"ע שלו סי' א' סעיף ח' כי עת רצון שלמעל' ויחודים עליונים שבק\"ש ותפלה וקדושת שבת ויו\"ט הוא למעלה מגדר המקום והזמן וכו' עכ\"ל, דקשה הא היחודים עליונים זהו מה שמתייחד במדת מלכותו והרי ביאר בסש\"ב ח\"ב פ\"ז שבמדת מלכותו שייך מקור לבחי' זמן וכו'. אלא צ\"ל לפי שגם הזמן שבמדת מל' הוא ג\"כ למעלה מהזמן שלנו רק שנק' סדר זמנים, ע\"כ היחודים הם למעלה מהזמן שלנו כו', ומ\"מ מאיר למטה לכל מקום ומקום בזמנו הראוי לו, שהרי עכ\"פ בחי' מלכותו היא שורש לבחי' הזמן שלמטה ממש כמ\"ש בסש\"ב, ועיין בלק\"ת בדרושי עשי\"ת בד\"ה להבין פי' הפסוק. ועפ\"ז י\"ל מ\"ש ושנותיך לא יתמו, לשון ושנותיך שייך ג\"כ מצד בחי' מלכותו, ואין צריך לדחוק כמ\"ש הרשב\"א שהוא שבירת האוזן לבד.",[["2355","5","<b>וכענין שיעוד קומה רל\"ו אלפים</b>: נסמן לעיל ע' נח."]]],[2101000370,"<h3>רשימה קצרה ע\"ד הכת\"י </h3>\nרוב המאמרים שבספר זה נעתקו מבוך 1052.\n<b>בוך</b> זה כולל מאמרי אדה\"ז, מלוקט מכמה שנים, ורק על אחדים מהם רשום זמן אמירתם (תקס\"ה, ועוד).\n<b>על</b> הכריכה רשום: מלוקט. ויהי כל הארץ שפה (ע\"ש התחלת המאמר הראשון שבהבוך).\n<b>רובו</b> כת\"י מעתיק, ובכמה מקומות רשימות הגהות ותקונים בגוכתי\"ק אדמו\"ר הצ\"צ, וכן המפתח שבראש הספר חלקו בגוכתי\"ק אדמו\"ר הצ\"צ.\n<b>גדלו</b> 2418 ס\"מ. כולל קצג דף. בתחילתו נוסף מפתח הדרושים דף אחד.\n<b>מדף</b> קמג עד הסיום כולל מאמרים דשנת תקס\"ט, ולחלק זה נתייחס להלן:\n<b>על</b> מאמרים אלו לא רשום בהבוך השנה שבה נאמרו, אך רשום במקומות אחרים על רוב מאמרים אלו שהם משנת תקס\"ט (כמפורט להלן ברשימת המאמרים).\n<b>בכמה</b> מקומות חסרים דפים (התחלות וסיומים של מאמרים), וגם הדפים הנמצאים בו נכרכו שלא עפ\"י הסדר, ורישום מספרי העמודים נעשה לאחר הכריכה, ולכן א\"א לעמוד על סדרם של המאמרים, וכן א\"א לקבוע אם היו עוד מאמרים בהמשך זה.\n<b>על</b> כמה מאמרים רשום בכמה מקומות שהם הנחות כ\"ק אדמו\"ר האמצעי, וכדלהלן:\nא) <b>ד\"ה</b> מים רבים, בסיום מאמר זה בבוך 524 (ט, ב) רשום, חסר בגוף כתיבת ידי קדשו של אדמו\"ר נבג\"מ.\nב) ד\"ה קול דודי, ראה אוה\"ת שה\"ש ע' רסד.\nג) <b>ד\"ה</b> זכור את יום השבת (השני), בסיום מאמר זה בבוך 554 (כז, ב) רשום: תם ונשלם תורת זכור את יום השבת לקדשו שמאדמו\"ר שי\"נ. וכנראה כוונתו שהי' בגוכתי\"ק אדמו\"ר האמצעי.\nד) <b>ד\"ה</b> ואולם, באוה\"ת שלח ע' תקי נדפסו הגהות למאמר זה, ובמ\"מ הכת\"י שם מצטט מה שרשום ע\"ז בכת\"י (בוך רח\"ל): הגהות לד\"ה ואולם חי אני מו\"ח ז\"ל מתקס\"ט.\n<b>ולפי</b> זה יש להניח שכל מאמרים אלו משנת תקס\"ט הם רשימות כ\"ק אדמו\"ר האמצעי."],[2101920057,"<h3>האזינו השמים</h3>\n<b>בס\"ד שבת שובה</b>\n<b>האזינו</b><sup data-n=\"1\">1</sup> השמים<sup data-n=\"2\">2</sup> ואדברה, ותשמע הארץ אמרי פי, יערוף כמטר לקחי תזל כטל אמרתי. הנה השמים אלו מארי תורה כי תורה היא מן השמים, והארץ אלו אנשי המעשה העוסקים במצות גשמיות, כי הנה על<sup data-n=\"3\">3</sup> ג' דברים העולם עומד כו'. והנה עבודה הן הקרבנות בטלו בחורבן בהמ\"ק ולא נשאר לנו כ\"א תו' וגמ\"ח שהם נק' שמים וארץ, וכשם שבשמים וארץ גשמי' פעם כתי' בראשית<sup data-n=\"4\">4</sup> ברא אלקים את השמים ואת הארץ שמים קדמו לארץ, ופעם כתי' ביום עשות ה' אלקים ארץ ושמים, ארץ קדמה כו'. כך הענין בתומ\"צ, כי פעם אמרו רז\"ל ות\"ת<sup data-n=\"5\">5</sup> כנגד כולם, ופעם אמרו תכלית<sup data-n=\"6\">6</sup> חכ' תשובה ומע\"ט, וגדול<sup data-n=\"7\">7</sup> תלמוד שמביא לידי מעשה דוקא, ושניהם אמת שיש בחי' ומעלה יתירה בעסק התורה על קיום המצות במעשה, ויש בחי' ומעלה יתירה במעשה המצות כנודע, ועל שניהם הוא אומר יערוף כמטר כו'.\n<b>והענין</b> הוא דכתיב כאשר<sup data-n=\"8\">8</sup> ירד הגשם כו' כן יהי' דברי אשר יצא מפי כו', הוא בחי' עסק התורה שנמשל לגשם ומטר. ולהבין איך הנמשל דומה למשל שיהי' דברי אשר יצא מפי הוא בחי' עסק התורה כמו הגשם והשלג שהרוה את הארץ והולידה והצמיחה כו'. הנה פעולת המטר היא ללחלח להארץ לעורר כח הצומח שבה להצמיח כעין הגרעין הנזרע שם אחרי החרישה<sup data-n=\"9\">9</sup> דמרפי ארעא, כי עיקר הצמיחה הוא מכח הצומח אשר בארץ שהוא המגדל ומצמיח את הגרעין בתוס' וריבוי, רק שא\"א להוציא הצמח מכח אל הפועל ומההעלם אל הגילוי בלתי המטר היורד ללחלח הארץ שהוא המעורר והמחזק את כח הצומח, וגם צריך",[["1","1","<b>האזינו השמים</b>: ראה גם ד\"ה זה בלקו\"ת האזינו עד, ב (שם עניני המאמר בשינויים). וראה עניני המאמר באריכות בס' עטרת ראש לז, ב. וביאור על המאמר בס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'רו."],["2","2","<b>האזינו השמים ואדברה</b>: האזינו לב, א."],["3","3","<b>על ג' דברים העולם עומד</b>: אבות פ\"א מ\"ב."],["4","4","<b>בראשית ברא אלקים . . שמים קדמו לארץ .ֿ. ביום עשות ה' אלקים ארץ ושמים</b>: בראשית א, א. חגיגה יב, א. בראשית ב, ד."],["5","5","<b>ות\"ת כנגד כולם</b>: פאה פ\"א מ\"א."],["6","6","<b>תכלית חכ' תשובה ומע\"ט</b>: ברכות יז, א"],["7","7","<b>וגדול תלמוד שמביא לידי מעשה</b>: קידושין מ, ב."],["8","8","<b>כאשר ירד הגשם</b>: ישעי' נה, י."],["9","9","<b>החרישה דמרפי ארעא</b>: ראה מו\"ק ב, ב."]]],[2101920058,"תחילה לחרישה דמרפי ארעא. וככל המשל הזה יובן בעסק התורה, כי הנה כאו\"א מישראל יש לו נפש אלקי', וכמאמר אלקי<sup data-n=\"10\">10</sup> נשמה שנתת בי טהורה היא אתה בראת כו', עד ואתה משמרה בקרבי, והנה מי הוא האומר בי ובקרבי שאין זה הגוף שהרי אין בו אומר ודברים אלא זו היא הנפש החיוני' והשכלי' המדברת כו', שהנשמה שהיא חלק אלוק' ממעל מלובשת בה והיא כעין הגרעין הנזרע בכח הצומח אשר בארץ, שכח הצומח הוא הנה\"ב דייקא שהיא היא המקיימת כל המצות מעשיות בפו\"מ (שהמצות<sup data-n=\"11\">11</sup> הן הפירות כו' כמ\"ש במ\"א), וגם מצות ת\"ת שעיקר המצוה היא בדיבור בפה דהרהור<sup data-n=\"12\">12</sup> לאו כדיבור דמי, רק יש איזו מצות השייכות ומתייחסות לנפש אלקי' כמו אמונה ודעת ה', ואף גם הן דוקא בהתלבשות הנפש בגוף ונה\"ב שאז שייך הציווי וידעת<sup data-n=\"13\">13</sup> היום והשבות כו', משא\"כ הנשמה עצמה א\"צ ציווי ואזהרה (כי מהות הנפש ועצמותה היינו בחי' מוחין ומדות, והמוחין הן השגות אלקות כו', והאמונה<sup data-n=\"14\">14</sup> היא בחי' רגלין כו' כמ\"ש במ\"א, וכ\"ז הוא מעצמיות הנפש, משא\"כ בחי' ציווי הוא כמו שמצוה לחבירו שבלתי הציווי לא הי' עושה מעצמו), וכן מצות אהוי\"ר משכנם בלב בחלל השמאלי המלא דם ששם הוא יסוד האש וצמאון האהבה כו', וגם פחד ה' עיקרו בלב, הגם דיראה שריא במוחא אית<sup data-n=\"15\">15</sup> יראה ואית יראה כו' וראשית היראה במוחו ומסיימת בלב כו', הרי שכל המצות מתקיימות בנה\"ב דוקא, והיינו לפי שבה מלובש כח הצומח להצמיח בתוס' וריבוי, כי יש בחי' ומעלה יתירה בנה\"ב על הנפש האלקי' כמו ארץ שקדמה לשמים שיכולה להמשיך מבחי' אוא\"ס ממש ביתר שאת מנפש האלקי', והגם שירדה מטה מטה בשכל גשמי וניזון מדברים גשמיים מאכלים ומשקי' כו', אמנם יסודתה בהררי קודש מאופנים וחיות הקודש שבמרכבה מבחי' פני שור, שכשם שיש פני שור בשרפים וחיות כך באופנים כתי' על<sup data-n=\"16\">16</sup> ארבעת רבעיהם, וכתיב פני<sup data-n=\"17\">17</sup> הכרוב, וזהו פני שור כדאיתא בזו'<sup data-n=\"18\">18</sup> ומשם נמשך הנה\"ב בישראל.\n<b>והנה</b> האופנים<sup data-n=\"19\">19</sup> ברעש גדול מתנשאים לעומת השרפים, והרעש הגדול הזה הוא מחמת ששומעים את השרפים שאומרים ג\"פ קדוש עד שהוי' צבאות כו'. והענין כי פי' צבאות הוא אות<sup data-n=\"20\">20</sup> הוא בצבא דילי', דהיינו שכל צבאי צבאות",[["10","10","<b>אלקי נשמה שנתת בי טהורה היא</b>: נוסח ברכות השחר."],["11","11","<b>שהמצות הן הפירות כו' כמ\"ש במ\"א</b>: ראה תו\"א שמות נג, ג (מגמ' סוטה מו, א). לקו\"ת שה\"ש טז, א ואילך."],["12","12","<b>דהרהור לאו כדיבור דמי</b>: ברכות כ, ב."],["13","13","<b>וידעת היום והשבות</b>: ואתחנן ד, לט."],["14","14","<b>והאמונה היא בחי' רגלין כו' כמ\"ש במ\"א</b>: ראה תניא אגה\"ק ס\"א (ובנסמן בליקוט פירושים ומ\"מ (חיטריק) לשם). לקו\"ת ר\"ה סג, ד. ובכ\"מ."],["15","15","<b>אית יראה ואית יראה</b>: ראה תניא פמ\"א (נז, סע\"א). לקו\"ת פ' ראה יט, ד. ובכ\"מ. וראה זח\"א יא, ב."],["16","16","<b>על ארבעת רבעיהם</b>: יחזקאל א, ח."],["17","17","<b>פני הכרוב</b>: יחזקאל י, יד."],["18","18","<b>כדאי' בזו'</b>: בכת\"י ב: כדאי' בגמ'. חגיגה יג, ב."],["19","19","<b>האופנים ברעש גדול</b>: נוסח ברכות ק\"ש."],["20","20","<b>אות הוא בצבא דילי'</b>: ראה חגיגה טז, א. וחדא\"ג מהרש\"א שם. מאו\"א מע' א, סנ\"ב."]]],[2101920059,"שלמעלה אלף<sup data-n=\"21\">21</sup> אלפין וריבוי רבבן ולגדודיו אין מספר כולם הם רק בחי' אות אחת משמו ית' ובאתא קלילא דלית בה מששא<sup data-n=\"22\">22</sup> היא אות ה\"א שהיא רק בחי' הבל הלב וברוח<sup data-n=\"23\">23</sup> פיו כל צבאם, אבל הוא עצמו ית' רם ונשא קדוש ומובדל כו', וג\"פ קדוש כנגד ג' אותיות ראשונות של שם הוי' צמצום והתפשטות המשכה כו', להמשיך בבחי' ה' אחרונה אות היא בצבא כו', אתא קלילא כו', מבחי' סוכ\"ע מבחי' קדוש ומובדל להיות את השמים ואת הארץ אני מלא, אני ממש הוא בחי' סוכ\"ע בבחי' עולם שנה נפש, בבחי' עולם להיות התפשטות מלכותו ית' למעלה עד אין קץ ולמטה עד אין תכלית, ובבחי' שנה בחי' זמן להיות גילוי א\"ס ב\"ה אתה<sup data-n=\"24\">24</sup> הוא קודם שנבה\"ע ואתה הוא כו', כי<sup data-n=\"25\">25</sup> אני הוי' לא שניתי, ובבחי' נפש הוא בחי' השגת הנפש באלקות, וכמה מיני השגות לאין קץ בגעה\"ע שמתענגים בהשגתם תענוג נפלא ועצום ובגעה\"ת כו', ובכ\"ז נמשך מבחי' ג\"פ קדוש להיותו הוי' צבאות, וגם מלא<sup data-n=\"26\">26</sup> כל הארץ כבודו הוא הארץ הלזו התחתונה הגשמי', שכמו שנמשך הוי' בצבאות העליונים, כך נמשך להיות מכה\"כ לפי שהמשכה זו היא מבחי' קדוש שהוא בחי' סוכ\"ע שלפניו כחשיכה כאורה ואין גשמיות העוה\"ז וחומריותו מחשיכים ומעלימים ומסתירים על אור ה' וקדושתו דלית<sup data-n=\"27\">27</sup> אתר פנוי מיני' והוא השוה<sup data-n=\"28\">28</sup> ומשוה כו'. וכל הארה והמשכה זו הוא רק בבחי' זיו כו', כי הוא ית' עצמו רם ונשא למעלה מגדר עלמין לא בגדר ממלא ולא בגדר סובב כו'.\n<b>והנה</b> כשהאופנים שומעים זה מרעישים בקול רעש גדול, כמ\"ש ביחזקאל קול<sup data-n=\"29\">29</sup> המולה כקול מחנה כו', מחמת גדולת א\"ס ב\"ה ורוממותו עד אין קץ ותכלית, ומתנשאים ברעש זה יותר מהשרפים, כי עם היות שמדריגתם למטה ממדריגת השרפים אמנם שרשם למעלה ממקום עליון יותר דהיינו מבחי' לפני<sup data-n=\"30\">30</sup> מלוך מלך כו', ועי\"ז החיות<sup data-n=\"31\">31</sup> נושאות את הכסא, פי' כסא כס א' כי א' היינו בחי' אלופו ש\"ע בבחי' יחו\"ע שם הוא בבחי' הסתר פנים ובבחי' כיסוי, לפי שעם היות שנמשך שם הביטול באוא\"ס ב\"ה, וכמ\"ש וצבא<sup data-n=\"32\">32</sup> השמים לך משתחוים, מ\"מ מאחר",[["21","21","<b>אלף אלפין וריבוי רבבן ולגדודיו אין מספר</b>: דניאל ז, י. חגיגה יג, ב."],["22","22","<b>ובאתא קלילא דלית בה מששא</b>: [בכת\"י ב: ממשא]. פיוט אקדמות לשבועות. וראה ב\"ר פי\"ב, י. תניא אגה\"ת פ\"ד."],["23","23","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["24","24","<b>אתה הוא קודם שנבה\"ע</b>: נוסח תפילת השחר. וראה של\"ה ג, ב. ס' מאמרי אדה\"ז על מארז\"ל ע' שלו. ובכ\"מ."],["25","25","<b>כי אני הוי' לא שניתי</b>: מלאכי ג, ו."],["26","26","<b>מלא כל הארץ כבודו</b>: ישעי' ו, ג."],["27","27","<b>דלית אתר פנוי מיני'</b>: ראה תקו\"ז תנ\"ז (צא, ב). ת\"ע (קכב, ב). וראה ס' האמונות והדעות להרס\"ג מאמר ב' פי\"ג. לקו\"ת ויקרא הוספות נב, ג. ובכ\"מ."],["28","28","<b>השוה ומשוה</b>: פיוט ”וכל מאמינים\" בתפילת ימים נוראים."],["29","29","<b>קול המולה כקול מחנה כו'</b>: יחזקאל א, כד."],["30","30","<b>לפני מלוך מלך</b>: בראשית לו, לא."],["31","31","<b>החיות נושאות את הכסא</b>: לשון הפיוט במוסף דר\"ה אחר קדושת כתר (נוסח אשכנז) ד\"ה והחיות. וראה שמו\"ר פכ\"ג, טו. בחיי תרומה כה, יו\"ד בשם פדר\"א."],["32","32","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."]]],[2101920060,"שמתלבשים בבחי' גוף כמ\"ש וגוויתו<sup data-n=\"33\">33</sup> כתרשיש, ולכן הם בבחי' גבול כמו מלאך הגדול הנק' סנדל גדול מהלך<sup data-n=\"34\">34</sup> ת\"ק שנה, ויש מלאך<sup data-n=\"35\">35</sup> שהוא בשליש עולם שליש מת\"ק כו', ולכך אין אוא\"ס ב\"ה מאיר בהם בבחי' יחו\"ע ממש בבחי' גילוי אלא בבחי' הסתר פנים וכיסוי, וע\"י התנשאות האופנים וחיות הקודש נושאות הכסא כס א' להיות גילוי בחי' אדם שעל הכסא הוא בחי' התורה כי זאת<sup data-n=\"36\">36</sup> התורה אדם דרמ\"ח<sup data-n=\"37\">37</sup> מ\"ע הן רמ\"ח אברים דמלכא, דהיינו כמו שהאברים נמשך בהם חיות הנפש עד שמתאחדים עם הנפש ובטילים אליה להתנהג ע\"פ רצונה בלבד ואין להם רצון אחר כלל כך המצות הן איברים דמלכא שבהן נמשך ומלובש חיות מאוא\"ס ב\"ה ממש הסוכ\"ע הוא רצוה\"ע ב\"ה ממש והמצות הן המשכות מאוא\"ס ב\"ה הסוכ\"ע לבחי' ממכ\"ע. ונק' שמי<sup data-n=\"38\">38</sup> וזכרי, זכרי עם ו\"ה רמ\"ח מ\"ע שהן בבחי' זכר והארה בעלמא, אבל שמי עם י\"ה ל\"ת שהן למעלה יותר בבחי' שמי הוא<sup data-n=\"39\">39</sup> ושמו בלבד כמ\"ש במ\"א.\n<b>והנה</b> לכן אחר התנשאות האופנים אומרים ברוך כבוד ה' ממקומו, ברוך היינו המשכה מהעלם אל הגילוי, כבוד ה' הוא בחי' התלבשות בבחי' מכסה והסתר פנים ובחי' לבוש נק' כבוד, דר\"י<sup data-n=\"40\">40</sup> קארי למאני מכבדותא, והיינו מה שנתלבש במלא כל הארץ הלזו הגשמיות שמכה\"כ, כי הגם שלפניו ית' כחשיכה כאורה ואין הסתר פנים לפניו ית', מ\"מ אין זה אלא לפניו אבל לגבי הנבראים הוא בחי' התלבשות בבחי' לבוש ומכסה בבחי' הסתר פנים והעלם אור ה' וקדושתו ונראה גשמיות העולם וחומריותו ליש ודבר לעיני בשר כו', והסתר פנים ולבוש זה נק' בשם כבוד, כבוד<sup data-n=\"41\">41</sup> בגימ' ל\"ב שהן ל\"ב נ\"ח, כי המכסה והלבוש הוא בחכ' כמ\"ש ה'<sup data-n=\"42\">42</sup> בחכ' יסד ארץ, כולם<sup data-n=\"43\">43</sup> בחכ' עשית דאבא<sup data-n=\"44\">44</sup> יסד ברתא, והענין כי אנו רואים בחוש שהבהמה שאין לה השכל היא בבחי' ביטול יותר שאפי' תינוק יכול למשול עליה משא\"כ האדם לפי שהוא בעל שכל הנה השכל עושה אותו לבחי' יש ודבר בפ\"ע המעלים ומסתיר את בחי' האין ובחי' הביטול, כי בחי' חכ' זו כבר נתלבשה ונמשכה מבחי' עה\"ד טו\"ר. וע\"ז הם מבקשים שיהא ברוך ונמשך",[["33","33","<b>וגוויתו כתרשיש</b>: דניאל י, י."],["34","34","<b>מהלך ת\"ק שנה</b>: חגיגה יג, ב."],["35","35","<b>מלאך שהוא בשליש עולם</b>: ראה חולין צא, ב. ב\"ר פס\"ח, יב. סה\"מ תש\"ח ע' 280 ובהערה שם."],["36","36","<b>זאת התורה אדם</b>: חוקת יט, יד."],["37","37","<b>דרמ\"ח מ\"ע הן רמ\"ח אברים דמלכא</b>: ראה תקו\"ז ת\"ל (עד, א). ועוד."],["38","38","<b>שמי וזכרי, זכרי עם ו\"ה רמ\"ח מ\"ע</b>: תקו\"ז בהקדמה (ד, ב). ועוד."],["39","39","<b>הוא ושמו בלבד כמ\"ש במ\"א</b>: פדר\"א פ\"ג. וראה במ\"מ בס' מאמרי אדה\"ז ח\"א ע' שיג. מאמרי אדהאמ\"צ דברים ח\"ד ע' א'רעא. תו\"ח שמות (הוצאת שנת תשס\"ג) נג, ב."],["40","40","<b>דר\"י קארי למאני מכבדותא</b>: שבת קיג, א."],["41","41","<b>כבוד בגימ' ל\"ב</b>: פרדס שער ערה\"כ (שכ\"ג) ערך כבוד. מאו\"א אות כ' סי\"ב. וראה מאמרי אדהא\"מ בראשית ע' ג ואילך. ובכ\"מ."],["42","42","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["43","43","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["44","44","<b>דאבא יסד ברתא</b>: זח\"ג רמח, ב. רנו, ב. ועוד."]]],[2101920061,"כבוד הוי' ממקומו העליון הוא בחי' ח\"ע שהוא ג\"כ בחי' כבוד והוא בחי' הביטול. וכמארז\"ל איזהו<sup data-n=\"45\">45</sup> חכם הרואה את הנולד מאין כו', כי חכ' זו היא כח מ\"ה והחכ'<sup data-n=\"46\">46</sup> מאין תמצא, וח\"ע זו היא בחי' כבוד ה' ומקומו העליון שהוא בחי' ביטול תהי' נמשכת ומתלבשת בבחי' כבוד ולבוש החכ' המעלמת ומסתרת לצאת מהעלם אל הגילוי שיהא גילוי אוא\"ס ב\"ה למטה בבחי' ביטול כמו למעלה, שכמו שלמעלה קמי' כולא כ\"ח ואין שם הסתר פנים כך למטה לא יעלים ולא יסתיר גילוי זה שיהא נראה לעיני בשר בעליל דכולא קמי' כ\"ח כיון שהוא באמת לפניו ית' ולא יהא נראה ליש כו'.\n<b>והנה</b> הכח הזה שיש לאופנים להמשכה זו הוא מחמת שהם מתנשאים לעומת השרפים ברעש גדול, שהרעש הזה מגיע ועולה למעלה לרום המעלות עד אא\"ס ב\"ה הסכ\"ע ממש ומשם נמשך למטה ג\"כ גילוי המשכת אוא\"ס ב\"ה הסוכ\"ע כו', וע\"ז נא' ורב<sup data-n=\"47\">47</sup> תבואות בכח שור שמבחי' פני שור שבאופנים שבמרכבה נמשכו רב תבואות דהיינו ריבוי ותוס' הארה מלמעלה מעלה מאוא\"ס ב\"ה ממש.\n<b>ובזה</b> יובן ג\"כ כח נה\"ב החיוני' שבאדם שנלקחה מבחי' פני שור שבאופנים כנ\"ל שיש לה ג\"כ בחי' רעש גדול, כי הנה נודע תכלית ירידת הנשמה לעוה\"ז להתלבש בגוף ונה\"ב הוא בשביל קיום המצות מעשיות בפו\"מ המתקיימות ע\"י נה\"ב דוקא, כי<sup data-n=\"48\">48</sup> היום לעשותם כתיב, והוא כדי להמשיך אוא\"ס ב\"ה על נפשו וגופו דווקא. והנה הגוף הגשמי הוא רחוק מאד מאוא\"ס ב\"ה מחמת חומריותו וגסותו וא\"א להאיר בו אור התו\"מ כשהגוף בתקפו, ולכן ארז\"ל כל האומר<sup data-n=\"49\">49</sup> אין לי אלא תורה אפי' תורה אין לו, שאינו מאיר בו אור התו', וצריך לבטש הגוף ולהכניעו ולהשפילו בבחי' ונפשי<sup data-n=\"50\">50</sup> כעפר לכל תהי' ולב נשבר כדי שיהי' תחת ממשלת הנפש האלקי' המשכלת ומתבוננת בגדולת ה' א\"ס ב\"ה, כי לאום<sup data-n=\"51\">51</sup> מלאום יאמץ ובינוני זה וזה שופטן כו', וזו היא בחי' תשובה כנודע<sup data-n=\"52\">52</sup> שבחי' תשובה אינה על עבירות דוקא אלא השבת הנפש שתשוב אל האלקים לדבקה בו, וזה תכלית ירידת הנשמה לעוה\"ז להשיב את נה\"ב שיאיר בה אוא\"ס ב\"ה, כי הנשמה עצמה א\"צ תיקון שהיא בבחי' צדיקים שבטבעה לעלות אל ה' כו', משא\"כ נה\"ב היא בבחי' בע\"ת דאתכפי' ואתהפכא מזה שהיתה תחת ממשלת קליפות נוג\"ה כו',",[["45","45","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א. ועוד."],["46","46","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["47","47","<b>ורב תבואות בכח שור</b>: משלי יד, ד."],["48","48","<b>כי היום לעשותם כתיב</b>: עקב ז, יא. עירובין כב, א."],["49","49","<b>האומר אין לי אלא תורה</b>: יבמות קט, ב. וראה לקו\"ת ויקרא ה, א."],["50","50","<b>ונפשי כעפר לכל תהי'</b>: נוסח תפילת אלקי נצור."],["51","51","<b>לאום מלאום יאמץ ובינוני זה וזה שופטן</b>: תולדות כה, כג. ברכות סא, ב. וראה תניא פי\"ג."],["52","52","<b>כנודע שבחי' תשובה אינה על עבירות</b>: ראה גם לקו\"ת פ' ראה כד, ד. לג, א. נצבים מח, ד. דרושים לר\"ה ס, ד. דרושים לש\"ש סה, ג. סו, ג. האזינו עז, ב. שה\"ש מד, ד. וראה מאמרי אדהאמ\"צ על נ\"ך ע' רו. וש\"נ."]]],[2101920062,"ונודע משארז\"ל<sup data-n=\"53\">53</sup> במקום שבע\"ת עומדים כו' כמ\"ש בזוהר<sup data-n=\"54\">54</sup> דמשכין בחילא יתיר, והיינו בבחי' רעש גדול ובחי' צעק לבם על ירידת הנה\"ב מאיגרא רמא מאוא\"ס ב\"ה בבחי' נפש הבהמה ממש, ועי\"ז היא מתנשאת למעלה מעלה לדבקה באוא\"ס ב\"ה בתשוקה וצמאון האהבה עזה ביתר שאת מנפש האלקי', כי יש בחי' ומעלה יתירה בנה\"ב הנלקחה מבחי' האופנים מפני שור מבנפש האלקי' וכדכתי' אחור וקדם צרתני<sup data-n=\"55\">55</sup> כו', דמשכין לי' בחילא יתיר כו', וע\"י העלאות והתנשאות הנה\"ב לאוא\"ס ב\"ה ממש הנה רוח<sup data-n=\"56\">56</sup> אייתי רוח ואמשיך רוח להמשיך גילוי בחי' ביטול למטה כמו למעלה, והוא בחי' בכל נפשך להיות דביקות הנפש מח' במח' דבור בדבור, ודברי<sup data-n=\"57\">57</sup> אשר שמתי בפיך כו', ושלא יעלים גשמיות העולם את אור ה' זו התורה, כי הגם שמלובשת בעניני עולם יש ודבר נפרד מ\"מ מאחר שהן הן רצונו וחכמתו ית' אין שם בחי' הסתר פנים כלל.\n<b>וזהו</b> ענין ברכת המצות ברוך אתה, שברוך ונמשך בבחי' גילוי להיות הוי' אלקינו דהיינו שנהי' אנחנו בבחי' ביטול אליו בבחי' פנימיות ובחי' יחו\"ע ממש שלא להיות רצון וחפץ אחר זולתו כלל, וכמשל האברים שמתאחדים עם הנפש הנשמעים לרצון הנפש שהנפש היא היא המנהגת את האברים ע\"פ רצונה בלבד ואין להאברים רצון זולתה כלל, כך יאיר עלינו אוא\"ס ב\"ה בבחי' פנימיות ממש שתהא הנפש מתאחדת וממולאת באוא\"ס ב\"ה בלבד שלא יהא לה רצון אחר כלל, וכמ\"ש מי<sup data-n=\"58\">58</sup> לי בשמים כו', ומלך העולם היינו בחי' יחו\"ת מחמת שהוא מלך כו', ואין<sup data-n=\"59\">59</sup> מלך בלא עם כו', והיינו ע\"י התבוננות כי גם העולם שמים וארץ וד' רוחות העולם הם הם בבחי' התפשטות והארת בחי' מלך עצמו כי כולם אינם רק י\"ס דמל' דעשי', ואינם יש ודבר בפ\"ע על צד האמת, אק\"ב אשר הוא עונג העליון ב\"ה המשיך קדושתו ית' עלינו להיותינו קדושים במצותיו ממש, כי הנה כל המצות כמו ציצית ותפילין כו' שרשן הוא למעלה מעלה באוא\"ס ב\"ה ממש כנודע, אך הגורם לזה שנתלבשו בדברים גשמיים להגיע עד הנה\"ב לקיים אותן בעשי' גשמיות היינו מחמת אתעדל\"ע<sup data-n=\"60\">60</sup> נשיאות והתעלות הנפש בבחי' בכל לבבך רוח אייתי רוח ואמשיך רוח להיות גילוי גם למטה שיהא נמשך גילוי בחי' ביטול למטה ג\"כ. וזהו ושמרתם<sup data-n=\"61\">61</sup> את חוקותי ואת משפטי אשר יעשה אותם האדם, שהכתוב נותן טעם איך יבוא האדם לקיום ושמרתם את חוקותי ואת משפטי ממש שהן הן אא\"ס ב\"ה ממש, אלא היינו מפני אשר יעשה אותם האדם, שהאדם הוא העושה אותן למצות שממשיך אותן ע\"י אתעדל\"ת ועי\"ז נעשו המצות כלים ומכון",[["53","53","<b>משארז\"ל במקום שבע\"ת עומדים כו'</b>: ברכות לד, ב. וראה לקו\"ש חי\"ד ע' 361 וע' 363. חי\"ז ע' 186. חכ\"ד ע' 530. ועוד."],["54","54","<b>בזוהר דמשכין בחילא יתיר</b>: זח\"א קכט, ב."],["55","55","<b>אחור וקדם צרתני</b>: תהלים קלט, ה."],["56","56","<b>רוח אייתי רוח</b>: ראה זח\"ב קסב, ב."],["57","57","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["58","58","<b>מי לי בשמים</b>: תהלים עג, כה."],["59","59","<b>ואין מלך בלא עם</b>: בחיי וישב לח, ל. ור\"פ בלק. תניא שעהיוה\"א רפ\"ז. ובכ\"מ."],["60","60","<b>אתעדל\"ע</b>: בכת\"י ב: אתעדל\"ת."],["61","61","<b>ושמרתם את חוקותי</b>: אחרי יח, ה."]]],[2101920063,"לשבתו ית', וזהו ורב תבואות בכח שור הוא בחי' נפש הבהמי' הנלקחה מבחי' פני שור מאופנים שבמרכבה להמשיך גילוי אלקות רב ועצום ואוא\"ס ב\"ה ממש, אלא שהנה\"ב בעצמה לא הי' בה כח להעלות ולהמשיך בלתי התלבשות נפש האלקי' המתלבשת בה שהיא נפש המשכלת ומתבוננת בגדולת ה' ורוממותו עד אין קץ והיא המנהגת את נה\"ב, נמצא שהנפש אלקי' היא כעין גרעין הנזרע ומתלבש בכח הצומח שבארץ, שכח הצומח הוא הוא העיקר להצמיח כל מיני תבואות הנזרעים בו אלא שהגרעין הנזרע בו מעוררו להוציאו מכח אל הפועל ומההעלם אל הגילוי להצמיח כעין הגרעין ההוא (ומ\"ש<sup data-n=\"62\">62</sup> במ\"א שהמצות הן הפירות הנצמחי' כו', הכל הולך אל מקום אחד כי מחדו\"מ של התו\"מ הן הן לבושי נפש האלקית אף שגבהו ממנה כמ\"ש בלק\"א והן הן הנזרעות בתוך נה\"ב).\n<b>והנה</b> הגם שכל אדם צ\"ל כל ימיו בתשובה, מ\"מ עת וזמן ושעת הכושר שמלמעלה לכך הוא בימים נוראים ועשי\"ת, כי ר\"ה הוא חידוש כללות החיות של כל השנה ולכן נק' ר\"ה כמו ראש שהוא גילוי כללות המוחין שבהם גילוי כללות החיות של כל האברים ומהם נמשך לכל אבר בפרטיות לפי מזגו ותכונתו כך בר\"ה נמשך גילוי כללות החיות של כל השנה, והמשכה זו באתעדל\"ת תלי' מלתא (שלכן הוא יום המשפט, משפט<sup data-n=\"63\">63</sup> לאלקי יעקב לפי המעשים של שנה העברה כמ\"ש במ\"א), ולכן מתחילים לתקוע בו בשופר גנוחי<sup data-n=\"64\">64</sup> גניח וילולי יליל, גנוחי גניח השברים לבטש ולשבר את הגוף בבחי' לב נשבר והוא בחי' חרישה דמרפי ארעא וילולי יליל בבכיה לעורר ר\"ר על ירידת הנפש מאיגרא רמא מאא\"ס ב\"ה כו', וכן כל<sup data-n=\"65\">65</sup> ימי עשי\"ת דרשו את ה' בהמצאו כתיב, וע\"כ תקנו להתענות בהם ואף שלא ישלימו כי אין תענית זה אלא קבלת צער בעלמא, והיינו כי הזמן גרמא לבטש את הגוף להכניע כחו שלא ימשך אחרי הנאת גופו למלאות כל צרכי כי שמנת<sup data-n=\"66\">66</sup> עבית כשית כתי', כשית בשמאל לשון כיסוי שנעשה מכסה וחיפוי על הלב לטמטמו כאבן, וכמ\"ש כי<sup data-n=\"67\">67</sup> כל הגוים ערלים וכל בית ישראל ערלי לב, וערלי לב היינו שיש להם בחי' ערלה ומותרות החופפת על הלב שאין לו רעו\"ד לפתוח לבו לאהבת ה' בתשוקה וצמאון הבאים מהתבוננות בגדולת ה', שאף שמתבונן ברוממות א\"ס ב\"ה ושהוא קדוש ומובדל כו', שמזה נעשה בחי' רעש גדול כו' כנ\"ל, אעפ\"כ אין לבו פתוח אצלו שיהי' לו בחי' רעש זה, שאין לבו צועק בקרבו אלא עומד בתקפו ובגבורתו כתולדתו ואינו מתפעל כו', והיינו מפני שיש בחי' ערלה החופפת על הלב ומסך מבדיל שאין ההתבוננות מגעת לעצמיות הלב, וערלה זו וחיפוי וכיסוי זה הוא מחמת כי שמנת עבית בחלב ודם שהחלב שמן והדם עב וגס שלא",[["62","62","<b>ומ\"ש במ\"א שהמצות הן הפירות הנצמחי'</b>: ראה לעיל (קרוב לתחילת המאמר) ”שהמצות הן הפירות\" וש\"נ."],["63","63","<b>משפט לאלקי יעקב לפי המעשים של שנה העברה כמ\"ש במ\"א</b>: תהלים פא, ה. וראה לקו\"ת נצבים נא, ד. דרושים לר\"ה נו, א. נח, ב. ובכ\"מ."],["64","64","<b>גנוחי גניח וילולי יליל</b>: ר\"ה לג, ב."],["65","65","<b>כל ימי עשי\"ת דרשו את ה' בהמצאו כתיב</b>: ישעי' נה, ו. ר\"ה יח, א."],["66","66","<b>שמנת עבית כשית</b>: האזינו לב, טו."],["67","67","<b>כי כל הגויים ערלים</b>: ירמי' ט, כה."]]],[2101920064,"נתמעט חלבו ודמו ולא נחלש כח הגוף להיות נשבר ונכנע תחת ממשלת הנפש האלקית המשכלת ומתבוננת בגדולת ורוממות א\"ס ב\"ה, ולכן צריך להתענות ולסגף נה\"ב בעשי\"ת למעט חלבו ודמו, וגם בכל הימים שאינו מתענה לא ימשך אחר הנאת גופו במילוי הכרס ובשמירת זמן הסעודה בבקר ובערב בכ\"י תמיד רק ידלג לפעמים זמן סעודה אחת שלא ירגיל גופו ונה\"ב למלאות להם תמיד די מחסורם אשר יחסר להם, ואז יכנע לבבו הערל תחת ממשלת הנפש האלקי' המשכלת בגדולת ורוממות א\"ס ב\"ה ואזי תהי' נשיאת הנה\"ב בתשוקה וצמאון באהבה עזה ברעש גדול ביתר שאת מנפש האלקית כי רב תבואות בכח שור הוא בחי' פני שור מהשמאל דהיינו בחי' שמאל דוחה כו'.\n<b>והנה</b> מבחי' ר\"ה ועשי\"ת נמשך להיות אח\"כ חג הסוכות זמן שמחתינו הוא השמחה הגדולה לאלקים בגילוי אוא\"ס ב\"ה על נפשו, אך מתחילה בימים הראשונים של חג הוא בבחי' מקיף בצלו<sup data-n=\"68\">68</sup> חמדתי וישבתי בחי' צל שמיצל מלמעלה ואינו נתפס ואינו נקלט לעצמיות הנפש בבחי' פנימי' (דהיינו שאין השמחה מתאחדת עם עצמות נה\"ב שיהא כח השמחה שבנה\"ב ממש שש ושמח מבחי' גילוי אלקות בלבד, ושיהא הגוף ממש נהנה ומתענג בשמחה של מצוה ולא יערב לו שמחה אחרת ותענוג אחר כלל), רק השמחה היא מפני הארת בחי' המקיף בצלו חמדתי שהוא צל נחמד כו' (שחופף על נפשו בחי' השמחה הגם שהוא בטבעה כתולדתה ולא נהפכה כלל מ\"מ בטילה היא באא\"ס ב\"ה השורה ומקיף על נפשו בבחי' השראה בלבד ואי לזאת היא שמחה, והיינו כענין וצדיק<sup data-n=\"69\">69</sup> באמונתו יחי' כי בחי' אמונה לבדה שלמעלה מהדעת היא בחי' מקיף כו'). אבל ביום השמיני עצרת תהי' לכם בחי' קליטה בבחי' פנימיות שמחה וטוב לבב מרוב כל כו' (הבאה מבחי' דעת המתפשט בתוך המדות שהוא קיום המדות וחיותן ממש כו'), וכ\"ז היינו מחמת קדימת ר\"ה ועשי\"ת חרישה דמרפי ארעא ורב תבואות בכח שור הוא הנה\"ב שע\"י המרירות והביטושים בבחי' ונפשי כעפר לכל תהי' ולב נשבר תתעלה הנפש ותתנשא ברעש גדול ובאהבה עזה כו', ומחמת זה נמשך גילוי אוא\"ס ב\"ה ממש, וז\"ש וירם<sup data-n=\"70\">70</sup> קרן לעמו שהרים ונשא אותם עד אא\"ס ב\"ה ממש למטה כמו למעלה, ותהי השמחה גדולה לאלקים ישמח<sup data-n=\"71\">71</sup> ישראל בעושיו, וכמאמר ותתן<sup data-n=\"72\">72</sup> לנו ה' אלקינו כלומר שנתן לנו א\"ע כביכול. וזהו לקחי פי' מה שלוקחים אותי, וכמאמר ותתן לנו הוי' אלקינו דהיינו גילוי המשכת אוא\"ס ב\"ה בנפש האדם. וגילוי זה יערוף כלומר שיומשך בבחי' עורף ואחוריים הוא בחי' חיצוני' העולמות דהיינו בתו\"מ המלובשים בענינים גשמיים ציצית ותפילין כו', ועריפה והמשכה זו היא בבחי' מטר ובבחי' טל, מטר ממטה למעלה כי אד<sup data-n=\"73\">73</sup> יעלה מן הארץ, וטל הוא מלמעלה למטה שנוזל מלמעלה בלבד.",[["68","68","<b>בצלו חמדתי וישבתי</b>: שה\"ש ב, ג."],["69","69","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["70","70","<b>וירם קרן לעמו</b>: תהלים קמח, יד."],["71","71","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."],["72","72","<b>ותתן לנו ה' אלקינו</b>: נוסח תפילת שלש רגלים."],["73","73","<b>אד יעלה מן הארץ</b>: בראשית ב, ו."]]],[2101920065,"<b>והענין</b> כי בעסק התורה יש ב' בחי' מטר שממטה למעלה דבאתעדל\"ת תליא מילתא ומעיקרא<sup data-n=\"74\">74</sup> כי עביד אינש אדעתי' דנפשי' עביד שעיקר כוונתו בעסק התורה להשיגה בלבד לקשר נפשו ומחשבתו שתהא תפיסא בתורה ומצותיה, ובאתעדל\"ת אתעדל\"ע הוא המשכת אור התורה ע\"י בחי' זו היא בחי' מטר היורד ללחלח הארץ, וכמארז\"ל משכהו<sup data-n=\"75\">75</sup> לבהמ\"ד אם אבן הוא נימוח כו', כי כמו הארץ אחרי החרישה דמרפי ארעא עוד היא צריכה למטר ללחלחה ולעורר כח הצומח שבה, כך אחרי כל הביטושים והמרירות שיעשה האדם בנפשו להיות לב נשבר ונפשי כעפר לכל תהיה, עוד זאת צריך שיערה עלינו רוח ממרום להתיש כח הגוף ע\"י התו' שהיא חכ' אלקית ואינה שכל אנושי, ולכן היא היא שמתשת<sup data-n=\"76\">76</sup> כח הגוף ומהפכת את כח נפש התאוה כו'. אך עדיין עסק התורה בבחי' זו נק' שלא לשמה, אבל מתוך שלא לשמה בא לשמה הוא בחי' טל שהוא המשכת אוא\"ס ב\"ה ממש בלבד בביטול הנפש אליו, וכמ\"ש והיו<sup data-n=\"77\">77</sup> הדברים האלה אשר אנכי ממש מצוך היום וכאלו היום נתנה שאף שכבר נתנה בסיני, מ\"מ הרי אומרים ודבריו<sup data-n=\"78\">78</sup> חיים וקיימים לעד ולעולמי עולמים, וכמ\"ש ודברי<sup data-n=\"79\">79</sup> אשר אנכי שמתי בפיך, ודברי ממש כו'.\n<b>ועל</b> שני בחי' הללו הוא אומר האזינו השמים ותשמע הארץ, שב' בחי' הללו נעשות ונמשכות בין בבחי' שמים הם בעלי התורה שעליהם נאמר ואדברה, כלומר שהוא ית' מדבר בהם לפי שהן בבחי' ביטול כנ\"ל, ובין בבחי' ארץ הם בעלי עסקים רק שעוסקי' במצות וגמ\"ח הנה גם בצדקה נא' אני<sup data-n=\"80\">80</sup> מדבר בצדקה, כלומר שע\"י צדקה גורם שדבר ה' אשר ידבר האדם בין בתורה בין בתפילה יהי' אני המדבר בהם, והם יהיו רק בבחי' שמיעה ותשמע הארץ, השמע לאזניך מה שאתה מוצא מפיך בחי' אתה כו', וכמ\"ש במ\"א.\n<b>וזהו</b> כל<sup data-n=\"81\">81</sup> הקורא ושונה הקב\"ה קורא ושונה כנגדו, ופי' כנגדו כי הגם שאינו מתלבש בנפשו ממש גילוי זה מ\"מ הרי הוא כנגדו, ואע\"ג<sup data-n=\"82\">82</sup> דאיהו לא חזי מזלי' חזי, וענין קורא ושונה הוא ענין התלבשות אוא\"ס ב\"ה בחכ' ע\"י עסק התורה דאורייתא<sup data-n=\"83\">83</sup> מחכמה נפקת שהרי אוא\"ס ב\"ה כשמו כן הוא אין לו סוף כו', ולאו<sup data-n=\"84\">84</sup> מכל מדות כלל, אלא הגורם להיות אנת הוא חכים כו' באתעדל\"ת תלי' מלתא ע\"י",[["74","74","<b>ומעיקרא כי עביד אינש אדעתי' דנפשי' עביד</b>: פסחים סח, א."],["75","75","<b>משכהו לבהמ\"ד אם אבן הוא נימוח</b>: סוכה נב, ב. קידושין ל, ב."],["76","76","<b>שמתשת כח הגוף</b>: ראה תו\"א יתרו סז, ב. ובכ\"מ."],["77","77","<b>והיו הדברים האלה . . וכאלו היום נתנה</b>: ואתחנן ו, ו. ספרי ופירש\"י עה\"פ."],["78","78","<b>ודבריו חיים וקיימים</b>: נוסח ברכות ק\"ש."],["79","79","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["80","80","<b>אני מדבר בצדקה . . השמע לאזניך מה שאתה מוצא מפיך . . וכמ\"ש במ\"א</b>: ישעי' סג, א. ברכות יג, א. ראה תו\"א וארא נז, ג. והוספות למג\"א קיח, א. לקו\"ת ויקרא ב, ב. פ' ראה לא, ג. סה\"מ תקס\"ז ע' צב."],["81","81","<b>כל הקורא ושונה</b>: תדא\"ר רפי\"ח."],["82","82","<b>ואע\"ג דאיהו לא חזי</b>: מגילה ג, א."],["83","83","<b>דאורייתא מחכמה נפקת</b>: סב, א. פה, א. קכא, א."],["84","84","<b>ולאו מכל מדות כלל</b>: ע\"פ תקו\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101920066,"עסק התורה שלמטה. וזהו ונתן<sup data-n=\"85\">85</sup> זרע לזורע ולחם לאוכל, פי' לחם לאוכל ע\"ד ישראל<sup data-n=\"86\">86</sup> מפרנסים כו' רעייתי פרנסתי כו', שכמו שהלחם מחבר ומשיב הנפש אל הגוף כך התורה היא מחברת אוא\"ס ב\"ה דלאו מכל מדות להתלבש במדות, וכמ\"ש כי<sup data-n=\"87\">87</sup> אמרתי עולם חסד יבנה, ע\"י כי אמרתי עולם דהיינו מה שאומר ד\"ת המלובשין בעניני עולם, חסד יבנה נבנה להיות מדות חסד ולהיות אנת הוא חכים כו'.\n<b>והנה</b> זו היא מדת כל יום יערוף כמטר בבחי' עורף וחיצוני', אך בחג הסוכות זמן גילוי בחי' פנימי' היא גילוי השמחה וסוכה<sup data-n=\"88\">88</sup> תהי' לצל יומם, יומם הוא בחי' החסד יום דאזיל עם כולהו יומין, והוא ענין כי אמרתי עולם חסד יבנה ע\"י כי אמרתי עולם כנ\"ל. וצל הוא ענין מקיף על יומם שהוא בחי' החסד ולמעלה הוא בחי' השמחה הבאה מלמעלה בהגלות אוא\"ס ב\"ה ממש זמן שמחתינו. אך שמחה זו עדיין היא מפני גילוי בחי' המקיף בצלו חמדתי כו', אבל ביום<sup data-n=\"89\">89</sup> השמיני עצרת וקליטה כו' דהיינו שיהי' נתפס ונקלט גילוי זה בפנימי' הלב ממש, ואז הוא זמן שמחתינו ממש שמחה<sup data-n=\"90\">90</sup> וטוב לבב מרוב כל.\n<b>כשעירים</b><sup data-n=\"91\">91</sup> עלי דשא, דשא נק' העשב בשעה שצומח מן הקרקע ועדיין לא נתגדל כראוי, ושעירים הם גשמי' דקי' כשערות, וזה רומז ללימוד הלכות פסוקות, קווצותיו<sup data-n=\"92\">92</sup> תלתלי' ושער רישי'<sup data-n=\"93\">93</sup> סלסלה<sup data-n=\"94\">94</sup> כאדם המסלסל בשערו כו', כי כמו שהשערות נמשכות מן המוח כך ההלכות נמשכות מח\"ע כו', וכרביבים הם גשמי' גדולים עלי עשב שהוא הנגדל כראוי עד שהוא מזריע זרע והוא רומז לבחי' לימוד בעיון. וביאור הדבר כי הנה יש ב' מיני זריעה שהתבואה היא צומחת מן גרעינים שנזרעו ממש אלא שהם בתוס' וריבוי מאד משא\"כ פירות האילן והארץ וכדומה הנה מגרעין הנזרע נגדל ונעשה פרי כגון תפוח וכיוצא, כך הנה משעירים שהם גשמי' דקים דהיינו לימוד הלכות פסוקות נגדל דשא עשב שאינו מזריע זרע שהזרע כעין הגרעין שנזרע דהיינו שיודע הלכה שלומד, אבל מלימוד העיון יכול להוציא דין חדש. וזהו ההפרש בין מארי משנה למארי תלמוד, שמארי משנה הם בעלי הלכות פסוקות אבל מארי תלמוד הם בעלי עיון ומוציאים דין חדש, ושניהם צריכים להיות וכמ\"ש ועשה<sup data-n=\"95\">95</sup> לי מטעמים הרבה מטעמים שאין דרך המלך לטעום הכל ממין א' ומטעם א' רק הרבה מיני מטעמים, ולכך צריך ללימוד המשנה וגם תלמוד כו'.",[["85","85","<b>ונתן זרע לזורע</b>: ישעי' נה, י."],["86","86","<b>ישראל מפרנסים כו' רעייתי פרנסתי</b>: זח\"ג ז, ב. שהש\"ר עה\"פ א, ט."],["87","87","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["88","88","<b>וסוכה תהי' לצל יומם</b>: ישעי' ד, ו."],["89","89","<b>ביום השמיני עצרת</b>: פינחס כט, לה."],["90","90","<b>שמחה וטוב לבב מרוב כל</b>: תבוא כח, מז."],["91","91","<b>כשעירים עלי דשא</b>: האזינו שם לב, ב."],["92","92","<b>קוצותיו תלתלי'</b>: שה\"ש ה, יא."],["93","93","<b>ושער רישי'</b>: דניאל ז, ט."],["94","94","<b>סלסלה</b>: משלי ד, ח."],["95","95","<b>ועשה לי מטעמים</b>: תולדות כז, ד."]]],[2101920067,"<h3>בשם הה\"ק ר' מענדיל</h3>\n<b></b><b>יום ב' י\"ב תשרי תקע\"ב</b>\n<b>בשם</b><sup data-n=\"96\">1</sup> הה\"ק ר' מענדיל<sup data-n=\"97\">2</sup> בארער נ\"ע. שהי' נוהג א\"ע שלא הי' אומר ד\"ת כ\"א במקום שנותנים לו נדבה, וסמך הדבר ע\"פ שלח<sup data-n=\"98\">3</sup> תשלח את האם ואת הבנים תקח לך, פי' תורה ומצות נק' בנים, ובחי' אם הוא בחי' הסיבה ע\"י מה שהתומ\"צ באים ונמשכים, ובזמן שבהמ\"ק הי' קיים היתה הסיבה מלמעלה כמו בנביאים שה' ית' ציוה אותם מלמעלה כמו הלוך<sup data-n=\"99\">4</sup> וקראת כו' וכיוצא, מפני שבחי' אם העליונה לא היתה בבחי' גלות וממנה הוא שנמשך להיות בחי' בנים, אבל משחרב בהמ\"ק ואזי סוכת דוד הנופלת מטה מטה ונתלבשה בגשמיות, לכן גם הסיבה לתורה ומצות הוא בבחי' סיבות גשמיי' שהמוכיח והדורש צריך לפרנסה ומוכרח להיות מקבל מההמון ועי\"ז צריך להיות מוכיח ודורש להם, והיינו מפני שבחי' אם שהיא הסיבה להבנים ירדה מטה מטה וד\"ל. ומ\"מ כתיב שלח תשלח את האם כו' שלא יעשה עיקר ח\"ו מן הסיבה שהוא לקיחת הממון וצ\"ל שלח תשלח כו', כי באמת אין זה תכלית הכוונה רק שהכוונה שעי\"ז יכול להיות אח\"כ ואת",[["96","1","<b>בשם הה\"ק</b>: נדפס בס' דרמ\"צ קצו, ב [ובהוצאות הקודמות בדף קיב, ב] בכותרת ”יום ב' י\"ב תשרי תקע\"ב\". [ונדפס שם ע\"י המו\"ל מתוך דף של ”כי\"ק ביכל תקע\"א תקע\"ב\", שהם הנחות של כ\"ק אדמו\"ר הצ\"צ ממאמרי אדה\"ז תקע\"א-תקע\"ב]. נוסחאות אחרות של תוכן המאמר בשינויים נדפסו בס' מאמרי אדה\"ז הקצרים ע' קטז וע' קמט.\nבע' קטז שם מתחיל: אחרי ה' תלכו כו', דהנה כתיב שלח תשלח את האם ואת הבנים תקח לך, ואמרו בשם המהר\"מ (בארי') שכל העולמות הם מעורבים טוב ורע ואנחנו עמו בני ישראל מחוייבים לברר כו'.\nובע' קמט שם מתחיל בפסוק: אלביש שמים קדרות ושק אשים כסותם. ובתוך המאמר שם: הלוך וקראת כו' כי בלא ציווי אין לו להתעורר מעצמו ולומר כו' והנה ידוע אע\"פ שפסקה הנבואה נשאר עדיין רוה\"ק וידיעת העתידות בצדיקים המופלגים בכל דור ודור כו' והענפים כו' בחי' ראשי אלפי ישראל שבכל דור המלמדים בתורה ברבים כו' המלמדים ליראה את ה' כו' והם המוכיחים כו', ואנו רואים שהת\"ח הן כפופים לע\"ה והם נצרכים לבריות בפרנסה ומזונות עד שהם נשכרים בעבודתם בקודש עבור קבלת פרס השכירות הקצובה וא\"כ מההכרח להם להשפיע להם שפע אלקי' בתורה ויראה מבלתי ציווי כו', והטעם לזה ע\"פ הנ\"ל שבזמה\"ג התלבשות כל שפע אלקי' הוא בלבושים זרים מאד בסיבה טבעית כו', וזהו שהיו גדולי הצדיקים נזהרים מאד מלהשפיע תורה ויראה כ\"א כשיקרה סיבה טבעית כמו הרר\"מ נ\"ע לא הי' דורש כ\"א בעיר שנתנו לו נדבה אף מעט מזעיר כו'. ע\"כ. במאמר זה הוא באריכות יותר מבמאמר שלפנינו, אך לא נזכר שם ע\"פ שלח תשלח את האם. [ואפשר מאמר זה איננו הנחה אחרת, כ\"א אותו תוכן שנאמר ע\"י כ\"ק אדה\"ז בזמן שונה]."],["97","2","<b>ר' מענדיל בארער נ\"ע</b>: ב”ציונים והערות\" מכ\"ק רבינו שבסו\"ס דרמ\"צ, מציין: מגדולי תלמידיו של הבעש\"ט נ\"ע, רב ומגיד בעיר באר, הבעש\"ט כותב אליו: להרב הקדוש מופת הדור איש אלקים וכו' מוהר\"ר מנחם מענדיל נ\"י מבאר. במכתב אחר: אל כבוד הרב המגיד הקדוש איש חי רב פעלים בו\"ק וכו' מו\"ה מנדיל נ\"י מ\"מ דק\"ק באר. ראה התמים חוברת שני' ע' לא. ח\"ד ע' יב. ח\"ה ע' כ, כב, כד."],["98","3","<b>שלח תשלח את האם</b>: ראה כב, ז."],["99","4","<b>הלוך וקראת</b>: ירמי' ב, ב. ועוד."]]],[2101920068,"הבנים תקח לך שהוא בחי' התורה ומצות שיוכיח וילמד להעם וד\"ל (אבל בלא סיבה אין ראוי מעצמו להגיד לעם ולהוכיחם מכמה טעמים שיש בדבר חדא דכתיב התקוששו<sup data-n=\"100\">5</sup> וקושו קשוט עצמך כו' ועוד והוא העיקר שאין מהצורך להתחיל מלחמה עם הס\"מ שהרי להוציא<sup data-n=\"101\">6</sup> יקר מזולל, היינו להוציאם מבחי' שכנגדו הנק' זולל, זהו ענין מלחמה ויש חשש בדבר. כ\"א כשהוי' ית' ציוה להנביאים ואמר להם הלוך וקראת כו'. וגם עתה כשיש סיבה בדבר שע\"י אותו סיבה צריך הוא להגיד להם (ולכן הר' מענדיל נ\"ע הנ\"ל אתרחיש נסע בעיר א' שלא הי' להם מה ליתן לו רק שהעבירו סחורה עניש שהי' מוליך בלא מכס אזי דרש להם שם הגם שהדרוש שלו הוא ענינים שעומדים ברומו של עולם) כי אז יודע שבמקום זה ראוי לו להוציא ההבל והאותיות הקדושים, ואפשר ששם יש מי שיתפעל מזה ואז יש צורך בזה וד\"ל.\n<b>(שרש</b><sup data-n=\"102\">7</sup> הענין אפשר כי הבנים הם זו\"נ שהוא בחי' תורה שהיא בחי' ז\"א ומצות שהם מל' מצות<sup data-n=\"103\">8</sup> המלך ובינה<sup data-n=\"104\">9</sup> היא אם הבנים, וזהו שעל ידה נמשכו הבנים, אבל באמת המשכה זו היא רק דרך מעביר, כי שרש המדות למעלה מהשכל רק שנמשכים דרך השכל, וכידוע שהשכל אינו אלא כמו מראה מקום להמדות כו', ולכן בזמן שבהמ\"ק קיים שאז הי' הנבואה שנמשכת מבינה ומשם התעוררות לתורה ומצות, אבל אחר החורבן שהשכינה בגלות בע' שרים ובחי' אימא מלובשת בגשמיות, וע\"כ התעוררות לתורה ומצות צ\"ל ג\"כ ע\"י סיבות גשמיים כו', ומ\"מ שלח תשלח את האם כו', כי הרי האם אינה רק פעולה שע\"י נמשכו המדות שהם הבנים בדרך מעביר לבד, אבל שרשם נעלה יותר כו' וד\"ל, על כן את הבנים תקח לך).",[["100","5","<b>התקוששו וקושו קשוט עצמך</b>: צפני' ב, א. ב\"מ קז, ב. וש\"נ."],["101","6","<b>להוציא יקר מזולל</b>: ע\"פ ירמי' טו, יט. וראה ב\"מ פה, א."],["102","7","<b>שרש הענין</b>: מכאן ואילך, כפי הנראה הוא הגהת והוספת כ\"ק אדמו\"ר הצ\"צ."],["103","8","<b>מצות המלך</b>: ראה תו\"א מקץ לד, א. ויקהל פז, ב. לקו\"ת ויקרא ב, א. ובכ\"מ. וראה ס' מאמרי אדהאמ\"צ שמות ח\"א ע' יא. סה\"מ ה'ש\"ת ע' 48."],["104","9","<b>ובינה היא אם הבנים</b>: ראה זח\"א ריט, א. ובכ\"מ."]]],[2101920069,"<h3>המצנפת של כה\"ג</h3>\n<b>המצנפת</b><sup data-n=\"105\">1</sup> של כה\"ג ארכה ט\"ז אמה, האבנט ל\"ב אמה מקיפו ומחזירו כרך ע\"ג כרך (רמב\"ם פ\"ט<sup data-n=\"106\">2</sup> מהלכות כלי המקדש). תחלה צ\"ל כל עיקר ענין הבגדים מהו, בהיות כי מצינו באדם עד שלא טעם מעה\"ד נאמ' ויהיו<sup data-n=\"107\">3</sup> שניהם ערומים ולא יתבוששו, ומשטעמו מעה\"ד אזי ותפקחנה<sup data-n=\"108\">4</sup> עיני שניהם וידעו כי ערומים הם. וכן מצינו בנביאי' כשהי' רוח נבואה לובשתם היו ערומים כמ\"ש גבי שאול כשנעשה גם הוא נביא ע\"ש בשמואל א סי' יט כד<sup data-n=\"109\">5</sup>. וזהו לפי שמעלת הנביא הוא שמגיע כמו שהי' בחי' אדה\"ר לפני החטא (ע' הקושיא במו\"נ<sup data-n=\"110\">6</sup>). הרי שהבגדים באי' דוקא מחמת השכל שלכן הנביאי' שנמנע מהם השכל של עה\"ד ע\"ד שהי' אדה\"ר טרם שטעם מעה\"ד שאז ותפקחנה עיניו, הולכים ערומים, אלא שהבגדים גשמיי' שלנו באים מחמת השכל דטו\"ר (ובחי' אדה\"ר לפני החטא וכן הנביאי' הוא למעלה מבחי' חכמה זו), אבל כן<sup data-n=\"111\">7</sup> למעלה שהלבושים הוא מבחי' חכמה, ולכן בגדי כה\"ג נק' בגדי קדש<sup data-n=\"112\">8</sup> דוקא.",[["105","1","<b>המצנפת של כה\"ג</b>: מאמר זה נדפס כאן מגוכי\"ק אדמו\"ר הצ\"צ בס' תקע\"ב (כת\"י מס' 1116 יא, א). ונמצא בשינויים באוה\"ת חה\"ס ע' א'תשטו (שם הוא הנחת כ\"ק אדמו\"ר האמצעי משנת תקע\"ב בתוס' הגהות מאת כ\"ק אדמו\"ר הצ\"צ), וקיצורים למאמר זה נדפסו באוה\"ת תצוה (כרך ח) ע' ג'פב ואילך. ונדפס עוד חלק מהמאמר בשינויים כו' בסה\"מ תרל\"ב ע' עז (ד\"ה ולבני אהרן תעשה כתנות). סה\"מ תרל\"ד ע' קצט (ד\"ה כהן גדול משמש בשמונה). ובאריכות הביאור בעטרת ראש לאדהאמ\"צ כח, א ואילך. חלק מתחילת המאמר (פיסקא ראשונה) נמצא בתוס' ביאור בסה\"מ תרס\"ב ע' רצה ואילך. וכמה ענינים מסיום המאמר נמצא בשינויים ואריכות בס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'רלב ואילך. ח\"ג ע' א'קלד ואילך. עטרת ראש כח, א ואילך. וראה גם ד\"ה כתונת בד קודש ילבש — ש\"פ אחרי תשל\"ו (סה\"מ תשל\"ו ע' 188 ואילך). וראה גם ברשימת הכת\"י שבסו\"ס הלקו\"ת לפ' אחרי כח, ב [שם מציין לביאור ד\"ה כי ביום הזה יכפר מאדמו\"ר הצ\"צ שמיוסד על ד\"ה מצנפת שלפנינו]."],["106","2","<b>פ\"ט</b>: צ\"ל פ\"ח. (וכ\"ה באוה\"ת סוכות ובשאר מקומות שנסמנו בתחילת המאמר)."],["107","3","<b>ויהיו שניהם ערומים</b>: בראשית ב, כה."],["108","4","<b>ותפקחנה עיני שניהם וידעו כי ערומים הם</b>: בראשית שם ג, ז. וראה עוד בכ\"ז בסה\"מ תרל\"ג ח\"א ע' קנא. המשך מים רבים תרל\"ו ס\"ע קכב ואילך. סה\"מ תרנ\"ח ע' רי-ריא. תרפ\"ג ע' קעה-קעו. תרצ\"ט ע' 127. תש\"י ע' 118. תשט\"ו ע' 239 ואילך."],["109","5","<b>ע\"ש בשמואל א סי' יט כד</b>: שם: ויפשט גם הוא בגדיו ויתנבא גם הוא לפני שמואל גו' ע\"כ יאמרו הגם שאול בנביאים."],["110","6","<b>(ע' הקושיא במו\"נ)</b>: ח\"א פ\"ב, וז\"ל: הקשה לי איש חכם כו' קושיא גדולה כו' יראה מפשוטו של כתוב כי הכוונה הראשונה באדם שיהי' כשאר בעלי חיים ללא שכל וללא תבונה ולא יבדיל בין טוב ורע, וכאשר המרה [בחטא עה\"ד] הביא לו מריו את השלימות העצומה המיוחדת לאדם והוא שיהא לו כח ההבחנה כו', והנה זה תימא שיהא ענשו לתת לו שלימות שלא היתה לו והיא השכל. עכ\"ל. ותירוצו שם בארוכה שחכמה זאת אינה מעלה שניתוסף בהם רק שכל אנושי והרגש גשמי. (והובא גם באוה\"ת סוכות שם ועד\"ז בהמשך תרל\"ו ובסה\"מ תרס\"ב שם)."],["111","7","<b>אבל כן למעלה</b>: אוצ\"ל: אבל לא כן למעלה. (ראה אוה\"ת סוכות שם ע' א'תשטו)."],["112","8","<b>בגדי קדש</b>: תצוה כח, ב. ד. אחרי טז, ד. ועוד."]]],[2101920070,"<b>והנה</b> הן היו מפשתן דוקא כמ\"ש כתונת<sup data-n=\"113\">9</sup> בד קדש ילבש ומכנסי בד, ובאבנט בד, ובמצנפת בד וכו'. כי הפשתן מובדל בא'<sup data-n=\"114\">10</sup> מכל מיני צמחה כמו חטים ודגן וכיוצא שכולם יכול להיו' שיהי' גדל מזרע א' כמה שבלים משא\"כ בפשתן שאינו גדל יותר משבולת א' מזרע א' ולכן נק' בד כמארז\"ל שגדילי'<sup data-n=\"115\">11</sup> בד בבד, והענין לפי שבחי' זו נמשכת מעולם האחדות ולכן הי' הכה\"ג צריך להיות לבוש ביוכ\"פ מבגדי' שמהם דוקא כי אז הוא נכנס לפני ולפנים בעולם האחדות לכפר על כל פשעי בנ\"י וכמ\"ש<sup data-n=\"116\">12</sup> ונסלח כו' והיינו בבגדי פשתן דוקא. ולכך הן בגדי לבן כי בחי' הלבן אינו כשארי המראות שהוא בחי' עצמיות של אותו דבר הלבן שהרי א\"א לעשות גוון לבן כמו שאפשר לעשות בכל המראות שיש גווני' שצובעי' בהם משא\"כ בלבן<sup data-n=\"117\">13</sup> שאין שום גוון לבן כלל (רק שהפשתן<sup data-n=\"118\">14</sup> בלייח\"ט מען) והיינו מפני שהוא<sup data-n=\"119\">15</sup> בחי' עצמיות, ולכן נק' בגדי קדש, והכה\"ג ביוכ\"פ הי' נכנס בבחי' עצמיות אלקותו ית' לכך הי' נכנס בבגדי לבן דוקא כי אין שם למעלה שום גוון כלל רק בחי' עצמיות ומשם הי' הכפרה ונסלח כו'.\n<b>ומעתה</b> יובן ג\"כ ענין המצנפת והאבנט כי האבנט פעולתו לחבר הלבושי' עם הגוף שלא יהי' חלל ביניהם, והענין שהלבושי' הם בחי' מקיפים ושיהיו מתחברים עם הפנימי' הוא ע\"י המשכת מקיפי' עליוני' יותר, שלהיותו עליון יותר יכול להכריח את המקיף שתחתיו להתחבר עם הפנימי כי יש כמה מדרגות מקיפי' זה עליון מזה כו', משא\"כ המצנפת הוא רק סובב לראש לחממו, ולכן שם רק י\"ו אמה ובאבנט צ\"ל כל ל\"ב אמה שאז יוכל לחבר וד\"ל. והענין כי יש ל\"ב נתי'<sup data-n=\"120\">16</sup> ד\"פ",[["113","9","<b>כתונת בד</b>: אחרי שם. בהבא להלן (עד סיום הפיסקא) ראה גם (בנוסף להנסמן בתחילת המאמר): לקו\"ת אחרי כח, סע\"ב ואילך. תו\"ח שמות שז, א (הוצאת תשס\"ג). אוה\"ת אחרי (כרך ב) ע' תקנו. אוה\"ת שה\"ש (כרך א) ע' קסב. סה\"מ תרל\"ב ח\"א ע' רלח. ח\"ב ע' תקצא."],["114","10","<b>בא'</b>: באחת."],["115","11","<b>שגדילי' בד בבד</b>: בגמ' זבחים יח, ב: דאמר קרא בד דבר העולה מן הקרקע בד בבד, ובפירש\"י שם: קנה יחידי מכל גרעין ואין ב' קנים עולים מגזע אחד. וע\"ש בתוס'."],["116","12","<b>וכמ\"ש ונסלח כו'</b>: ע\"פ שלח טו, כו: ונסלח לכל עדת בנ\"י גו'. ונתקן אמירת פסוק זה בתפילות יוהכ\"פ. וכן הובא פסוק זה לענין עבודת כה\"ג ביוהכ\"פ בלקו\"ת שם כח, רע\"ג. ובאוה\"ת דרושים לחה\"ס שם ע' א'תשיז."],["117","13","<b>בלבן שאין שום גוון לבן כלל</b>: בסה\"מ תרל\"ב (ע' עט) הל' הוא: משא\"כ בלבן שאין שום צבע שיוכלו לצבוע גוון לבן כלל, והיינו מפני שגוון זה הוא עצמיות (רק שהפשתן בלייחט מען והוא רק להוציא מההעלם את גילוי גוון עצמותו כו')."],["118","14","<b>שהפשתן בלייחט מען</b>: ראה עד\"ז באוה\"ת סוכות שם: שמלבנים הפשתן (מעבלייכט לאוינט). ועד\"ז בעטרת ראש שם לא, ב."],["119","15","<b>שהוא בחי' עצמיות</b>: ראה גם לקו\"ת ואוה\"ת אחרי שם. עטרת ראש שם פ\"ה. תו\"א ויצא כד, ב. מאמרי אדה\"ז פרשיות ח\"ב ע' תרנא. תשעט. תקס\"ג ח\"ב ע' תקלג. תקס\"ד ע' טו. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תפד. תקטו ואילך. תו\"ח ויצא לז, ד. המשך תרס\"ו ע' שעג. תער\"ב ח\"א ע' רכט. ועוד."],["120","16","<b>כי יש ל\"ב נתי'</b>: ראה ס' יצירה רפ\"א. זח\"ב קעד. א. זח\"ג רצ, א. [וראה בהנסמן עוד בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתקא. דברים ח\"ד ע' א'רמב]."]]],[2101920071,"הוי' אדני<sup data-n=\"121\">17</sup> וכנודע בענין ד' מוחי' דתפילין<sup data-n=\"122\">18</sup>, אך סיבת התחלקו' לד' מוחי' הוא לפי שהדעת<sup data-n=\"123\">19</sup> מתחלק לב' ונעשה ב' בחי' חו\"ג ולכן במוח יש ב' בחי' ימין ושמאל חו\"ב אבל לא יותר וע\"כ הם י\"ו אמה ב\"פ הוי' א\"ד אבל בלב צ\"ל יותר כדי לחבר המקיפי' עם הפנימי' ולזה נצרך כל הל\"ב נתי', והיינו שהדעת מתחלק לב' מוחי' בב' חללי הלב חלל<sup data-n=\"124\">20</sup> השמאלי מלא דם גבו' וחלל הימיני מלא רוח חסדי', הגם שבלא\"ה יש חו\"ג היינו בבחי' מדות בלבד חסד ויתור כו' משא\"כ מה שהדעת מתחלק לב' מוחי' חו\"ג היינו החסד שע\"י החכמ' וכן הגבורה כו'.\n<b>וביאור</b> ענין ההתחברות יותר הוא כי כה\"ג<sup data-n=\"125\">21</sup> רב חסד שבלי גבול ואיש כהן<sup data-n=\"126\">22</sup> חסד סתם, וכנודע<sup data-n=\"127\">23</sup> דאית חסד ואית חסד כו', כמו בגשמיו' יש מי שהוא בעל צדקה בגבול ויש הרבה מאד, ובכללו' חסד שבעוה\"ז עושר ומזון בגבול וחסד שבעולמו' העליוני' בלי גבול, ובכדי שיתחברו יחד הוא ע\"י גילוי בחי' עליונה יותר, ולכן חגר האבנט בין אצילי ידיו<sup data-n=\"128\">24</sup> דוקא ששם צ\"ל ההתחברות (כי הוא בחי' חו\"ג) והיינו ע\"י ל\"ב נתי' שעש\"ז נק' הלב כן ל\"ב שבו יש ל\"ב אורות<sup data-n=\"129\">25</sup> ע\"י התחלקו' הדעת לב' מוחי' חו\"ג כנ\"ל.\n<b>מקיפו</b> ומחזירו כרך ע\"ג כרך, בחי' עיגולים כנודע<sup data-n=\"130\">26</sup> הענין בבחי' עיגולי' ויושר שהעיגולי' הוא עד\"מ כשהאדם משיג איזו שכל ששכלו מקיף אותו דבר המוקף כו' וכן הרב מקיף את שכל התלמיד משא\"כ התלמיד אינו מקיף את שכל הרב כי אינו מבין בו רק מעט מה שהביניהו הרב אבל הרב מבין כל מהות התלמיד ומקיפו כו' וכן למעלה המגביהי לשבת<sup data-n=\"131\">27</sup> וע\"כ משפילי לראות בשמי' וארץ סוכ\"ע משא\"כ אנחנו איננו תופסי' רק מעט הנרא' כו', וכך היו בגדי כה\"ג מבחי' מקיפי' סוכ\"ע כנ\"ל.",[["121","17","<b>ל\"ב נתיבות ד\"פ הוי' אדנ\"י</b>: באוה\"ת שם: ל\"ב נתיבות חכ' והם ד' פעמים הוי' אד' שעולה ל\"ב אותיות."],["122","18","<b>וכנודע בענין ד' מוחין דתפילין</b>: ראה זח\"ג רסב, א ואילך. רצב, ב. ועוד. פע\"ח שער התפילין (שער ד). סידור עם דא\"ח ו, ג ואילך. אמרי בינה שער התפילין ח\"ג קט, א ואילך."],["123","19","<b>שהדעת מתחלק לב' ונעשה ב' בחי' חו\"ג</b>: ראה ע\"ח שער תיקון הנוקבא (של\"ד) פ\"ג."],["124","20","<b>חלל השמאלי מלא דם גבו' וחלל הימיני מלא רוח חסדי'</b>: ראה תניא פ\"ט. אוה\"ת תצוה ע' א'תרסה. ”רשימות\" לתניא חוברת ב' ע' עו ואילך. וש\"נ."],["125","21","<b>כה\"ג רב חסד שבלי גבול</b>: ראה מאו\"א א, קמ. כ, ט. ס' מאמרי אדה\"ז עה\"ת ח\"א ע' שנד, ובהמ\"מ שם. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שמט. ח\"ג ע' תתפט. ח\"ד ע' א'שיט, ובהמ\"מ שם."],["126","22","<b>ואיש כהן חסד סתם</b>: ראה גם ס' מאמרי אדה\"ז עה\"ת ח\"א ע' רנב, ובהמ\"מ שם."],["127","23","<b>וכנודע דאית חסד ואית חסד כו'</b>: זח\"א ריט, א. זח\"ג כא, א. קלג, ב. קמ, ב."],["128","24","<b>האבנט בין אצילי ידיו</b>: זבחים יט, א. רמב\"ם רפ\"י מהל' כלי המקדש."],["129","25","<b>ל\"ב אורות</b>: כ\"ה בגוכי\"ק כאן. ובכת\"י מעתיקים של סה\"מ תרל\"ד (ע' רא): ל\"ב אונות. וע\"ש בהמ\"מ."],["130","26","<b>כנודע הענין בבחי' עיגולים ויושר</b>: ראה בארוכה לקו\"ת שלח לז, ג. מאמרי אדה\"ז ענינים ס\"ע רפ ואילך. אוה\"ת סוכות שם ע' א'תשכא."],["131","27","<b>המגביהי לשבת</b>: תהלים קיג, ה."]]],[2101920072,"<b>והנה</b><sup data-n=\"132\">28</sup> ע\"י כללות ענין עבודת כה\"ג ביוכ\"פ נעשה אח\"כ סוכות שענינם הוא בחי' ענני כבוד שהקיפום, כי ענן הוא ענין עשן כמ\"ש ענן<sup data-n=\"133\">29</sup> הקטרת כו' ומבחי' הענן שבקטרת דיוכ\"פ הוא שנמשך אח\"כ בחי' סוכות. כי הנה הקטרת הי' מי\"א סממני' הצרי והצפורן כו' שהם י\"א סממני קטרת<sup data-n=\"134\">30</sup> שהם כנגד י\"א ארורי' י\"א ניצוצי' שמהם חיות כל הקליפות עשר מובלעי' בתוך הקליפות והאחת בבחי' מקיף והנה שרשן מבחי' לפני<sup data-n=\"135\">31</sup> מלוך מלך כו' כמשל השליא<sup data-n=\"136\">32</sup> שמקפת את הולד, רק שנפלו מטה מטה, וכה\"ג ביוכ\"פ שהי' נכנס לפני ולפנים בבגדי לבן הי' מעלה מהם עשן, ע\"י שנטל גחלי' משני גזרי עצים שהי' כהן מביא בכל יום ג\"כ כשהוא בבגדי' דוקא שאז ממתיק הגבורו' ומאותן גחלי' דוקא נטל משא\"כ גחלי' אחרי' פסולים, ועל אותן גחלים הניח את הקטרת ואז עלה מהם עשן מבחי' יסוד המים שבהם שהוא בחי' הלחלוחי' שבהם דהיינו בחי' החיות מעולם התהו שבהם שזה עלה בבחי' עשן, ועל עשן זה הנק' ענן הוא שנאמ' כי<sup data-n=\"137\">33</sup> בענן אראה כו' שבעשן זה שורה ומתגלה אלקותו ית' ועי\"ז הי' מחילה וסליחה לכפר על כל העונות ע\"י שנלקח החיות מהקליפות כו', ומזה נעשה אח\"כ בחי' סוכות בחי' ענני כבוד שהקיפום, אלא שבסוכות הוא בבחי' המשכה ממעלה למטה, וסוכה תהי' לצל יומם<sup data-n=\"138\">34</sup>, וביוכ\"פ בחי' עליות ממט' למעלה וע\"י העלי' נעשה אח\"כ ההמשכה.\n<b>ובזה</b> יובן ענין סוכה<sup data-n=\"139\">35</sup> שחמתה מרובה מצלתה פסולה וצ\"ל כוכבים<sup data-n=\"140\">36</sup> נראי' מתוכה כי הנה החמה נראי' גדולה יותר מן הכוכבי' ובאמת יש כוכבי' שגדולי' יותר מן החמה (בהרמב\"ם<sup data-n=\"141\">37</sup> פ\"ג מה' יסוה\"ת ה\"ח כתב ואין בכל הכוכבים כוכב גדול מן השמש עכ\"ל וע\"ש שזהו אפילו בכוכבים הנראים כ\"ש בכוכבים שאינן נראים א\"כ מש\"כ<sup data-n=\"142\">38</sup> שיש כוכבים גדולים מן החמה הוא ט\"ס רק צ\"ל שיש כוכבים גדולים מכדור",[["132","28","<b>והנה ע\"י כללות ענין עבודת כה\"ג ביוכ\"פ</b>: בהבא להלן ראה גם עטרת ראש לו, א ואילך. מאמרי אדהאמ\"צ דברים ח\"ג ע' א'קלד ואילך. ח\"ד ע' א'רכז ואילך."],["133","29","<b>ענן הקטרת</b>: אחרי טז, יג. וראה יומא נג, א. תו\"א מג\"א צד, א."],["134","30","<b>י\"א סממני קטרת שהם כנגד י\"א ארורים</b>: ראה ע\"ח שער המלכים (שי\"א) פ\"י. ס' מאמרי אדהאמ\"צ קונטרסים ע' שמב (ובמ\"מ שם). אוה\"ת תולדות קנב, ב. ובכ\"מ."],["135","31","<b>לפני מלוך מלך</b>: בראשית לו, לא."],["136","32","<b>כמשל השליא</b>: ראה גם תו\"א וישלח כה, ג: וזהו שעשו הי' בכור שהוא מבחי' לפני מלך מלך כו' ועשו הי' מקור הז' מלכים שמלכו כו' וימת וימלוך וימת וימלוך כו' שהוא בחי' שליא המקפת על הולד שקדמה לולד והעיקר הוא הולד שנולד ובצאתו זורקין השליא כו' שאינו מקבל רק בחי' מקיף."],["137","33","<b>כי בענן אראה</b>: אחרי טז, ב."],["138","34","<b>וסוכה תהי' לצל יומם</b>: ישעי' ד, ו."],["139","35","<b>סוכה שחמתה מרובה מצלתה</b>: סוכה כב, א-ב. וראה לקו\"ת דברים כז, ג וז\"ל: ועמ\"ש במ\"א בענין סוכה שצ\"ל חמתה מרובה מצלתה ומ\"מ צ\"ל כוכבים נראים מתוכה כו'. וע\"ע בלקו\"ת תזריע כד, ב. סה\"מ תרל\"ב ח\"ב ע' תקצ. ד\"ה סוכה שחמתה מרובה מצלתה תשי\"ד."],["140","36","<b>כוכבים נראי' מתוכה</b>: סוכה שם. וראה גם ירושלמי סוכה פ\"ב ה\"ג."],["141","37","<b>בהרמב\"ם פ\"ג מהל' יסוה\"ת</b>: פיסקא זו (עד סיום המוסגר) היא הגהת כ\"ק אדמו\"ר הצ\"צ. וקאי על נוסח רשימת המאמר שהיתה לפניו."],["142","38","<b>מש\"כ שיש כוכבים גדולים מן החמה הוא ט\"ס</b>: ראה הלשון במאמרי אדהאמ\"צ דברים ח\"ד ע' א'רלא: מדדו בשיעור כל כוכב שהוא למעלה הרבה מגלגל החמה כו'. ועד\"ז נזכר באוה\"ת סוכות ע' א'תשכז."]]],[2101920073,"הארץ אף שכדור הארץ גדול מן הירח ארבעים פעמים עכ\"ז יש כוכבים גדולים מכל כדור הארץ), אך הסיבה מפני שהחמה<sup data-n=\"143\">39</sup> בגלגל הרביעי והכוכבי' בגלגל הח' רחוקי' מאד מן הארץ לכן אין נראי' רק קטנים מאד, והיינו כי החמה לפי שקטנה במדרגה לכן נראית לכל משא\"כ הכוכבי' שלהיותם מבחי' עליונה מאד וא\"א להתגלות כולה רק מעט מזעיר ככוכבי' ונקודות כמשל שגם בחמה עצמה א\"א להסתכל והעין כהה מהביט עלי' ודמעו' נוטפי' אלא ע\"י נרתק ואז נראי' גדולה משא\"כ בכוכבי' א\"א כן רק מעט מזעיר כנ\"ל.\n<b>והנה</b> כמ\"כ כשהיו ישראל במדבר היו במדרגה גבוה יותר למעלה מבחי' חמה לכן הקיפם ענני כבוד שלא תהי' החמ' זורחת עליהם, והענני כבוד היינו מבחי' רקיע השמיני דתמן כוכביא ומזליא קבועי' שהוא בחי' הארה שלמעלה מבחי' חמה רק שא\"א להראות רק בבחי' כוכב כו'.\n<b>והנה</b> סיבת הענן הוא נעשה ע\"י הקטרת שגם במדבר הי' מקטירי' כידוע וכמ\"ש מי<sup data-n=\"144\">40</sup> זאת עולה מן המדבר כתמרת עשן כו' שבחי' עשן זה היוצא מבחי' יסוד המי' שבקטורת שהוא בחי' החיות מלפני מלוך מלך כנ\"ל הוא מבחי' רקיע השמיני וד\"ל (בחי' ס\"ג בחי' בינה). וכן גם עתה ביוכ\"פ ע\"י הקטרת בבגדי לבן דוקא נעשה בחי' עשן זה אשר בו נאמ' בענן אראה כו' ומזה נעשה בחי' סוכות ענני כבוד שהם למעלה מבחי' חמה שהחמה היא המאירה בכל השנה משא\"כ בסוכו' חמתה מרובה מצילתה פסולה כי הענני' הם מבחי' שלמעלה מהחמ' רק שכוכבי' צ\"ל נראי' מתוכה כי תמן כוכבי' ומזלי' קבועי' שהם עליוני' יותר במדרגה ומזה הטעם א\"א להתגלות מהן רק בבחי' כוכבים כו'.\n<b>להעיר</b><sup data-n=\"145\">41</sup> בענין למעלה מבחי' חמה ממ\"ש<sup data-n=\"146\">42</sup> ע\"פ ואור החמה יהי' כאור זה\"י כו'.\n<b>במא\"א</b><sup data-n=\"147\">43</sup> אות אלף סעיף קפ\"ד אבנט עם האותיות גימ' אד' עם הכולל ובו ל\"ב אמה סוד ל\"ב נתיבות הכלולים בה והי\"נ<sup data-n=\"148\">44</sup> הביא מהת\"ז תקון כ' דף ע\"ב כד אתקשטת קדמיה בלבושין שפירין<sup data-n=\"149\">46</sup>.",[["143","39","<b>שהחמה בגלגל הרביעי</b>: רמב\"ם הל' יסוה\"ת רפ\"ג שם."],["144","40","<b>מי זאת עולה</b>: שה\"ש ג, ו."],["145","41","<b>להעיר</b>: מכאן ואילך הם הגהות כ\"ק אדמו\"ר הצ\"צ הקשורים להמאמר."],["146","42","<b>ממ\"ש ע\"פ ואור החמה</b>: לקו\"ת צו, ט, ב ואילך."],["147","43","<b>במא\"א . . אבנט</b>: ראה עוד בענין אבנט בארוכה באוה\"ת אחרי כרך א ע' רצב. כרך ב ע' תקסג ואילך."],["148","44","<b>והי\"נ</b>: והיאיר נתיב (בציוניו על המאורי אור).\n45)דף ע\"ב: צ\"ל דמ\"ט ע\"ב. וזהו ע\"פ דפוס אמשטרדם תקכ\"ז, ובדפוסים שלפנינו הוא בתכ\"א דנ\"ז ע\"ב."],["149","46","<b>מהת\"ז . . בלבושין שפירין</b>: ז\"ל בתקו\"ז שם: ואיהי יוהכ\"פ, וכד אתקשטת קדמיה בלבושין שפירין דאינון לבושי כפרה אתקרי ציץ דיליה, מצנפת דיליה, אבנט דיליה כו'.\nצדיקים מה הם עושים: מאמר זה נמצא בנוסחאות ובמהדורות שונות: א) נוסח הנדפס כאן, והוא מתוך גוכי\"ק הצ\"צ בס' הנחות תקע\"ב (כת\"י מס' 1116 יג, א. והוא מה שרשם כ\"ק אדמו\"ר הצ\"צ בסמוך לאמירתו ע\"י כ\"ק אדה\"ז). ב) באריכות יותר בד\"ה להבין מארז\"ל בחלק ע\"פ וקוי ה' — באוה\"ת בראשית כח, ב. [במפתח בתחילת האוה\"ת מציין המו\"ל שמאמר זה הוא מן ביכל תקע\"א גוכי\"ק הצ\"צ. ביכל זה לא הגיע לידינו. וניכר אשר כמה ממאמרי תקע\"א-תקע\"ב רשם אדמו\"ר הצ\"צ ב' פעמים, ובפעם הב' באריכות וביאור יותר]. ג) ד\"ה להבין מ\"ש במדרש ע\"פ וקוי ה' — נדפס לקמן. וכנראה הוא הנחת כ\"ק אדהאמ\"צ שרשם בשנת תקע\"ב. ד) באריכות ובתוס' ביאור בד\"ה להבין מ\"ש במדרש כו' — בס' מאמרי אדהאמ\"צ בראשית ע' עז [מאמר זה נמצא ג\"כ בכת\"י 1880 כז, א ושם הוספה כמה עמודים על הנדפס]. ה) באריכות יותר בד\"ה בראשית ברא בתו\"ח בראשית ד, ג ואילך. מאמר התו\"ח נדפס גם (בשינויים קלים) בס' מאמרי אדהאמ\"צ בראשית שם ע' קל. ו) בשינויים והגהות בד\"ה שיר השירים — באוה\"ת שה\"ש ע' ט, ומקבילו בסה\"מ תרכ\"ז ע' רסד ע\"ש. ז) בתוס' הגהות מהר\"ה מפאריטש בד\"ה להבין מארז\"ל צדיקים שעתיד הקב\"ה — בס' פלח הרמון בראשית י, ג. ושם א, א ד\"ה בראשית ברא [הגהות על ד\"ה בראשית ברא בתו\"ח].\nביהל אור להצ\"צ ע' תשכא, מביא מארז\"ל זה צדיקים מה הם עושים כו', ומציין: ”המאמר הזה ביארו אאזמו\"ר [אדוני אבי זקני מו\"ר] נ\"ע יום ב' דחוה\"מ סוכות תקע\"ב\" [וקאי על המאמר שלפנינו]. ובאוה\"ת יתרו ע' תתא מציין ע\"פ ואשא אתכם על כנפי נשרים למאמר ”לע\"ל כנפים כנשרים שמע\"צ תקע\"ב\"."]]],[2101920074,"<h3>צדיקים מה הם עושים</h3>\n<b>צדיקים</b> מה הם עושים הקב\"ה עושה להם כנפים כנשרים ושטים על פני המים<sup data-n=\"150\">2</sup>. בראשית<sup data-n=\"151\">3</sup> בשביל ישראל שנק' ראשית ובשביל התורה שנק' ראשית, בראשית ות\"י<sup data-n=\"152\">4</sup> בחוכמתא כי מה<sup data-n=\"153\">5</sup> רבו מעשיך ה' כולם בחכמ' עשית שכל התהוו' העולמות הוא ע\"י בחי' החכמ' בחכמה<sup data-n=\"154\">6</sup> יסד ארץ אך זהו בחי' חכמה תתאה והתורה היא ג\"כ בחי' חכמה אלא שהיא חכמה עילאה ולכן אין העולם מתקיים אלא בזכות התורה ואם לא התורה הי' העולם חוזר לתהו כדאי' בגמרא<sup data-n=\"155\">7</sup>, וע\"ז כתי' חכמות<sup data-n=\"156\">8</sup> בחוץ תרונה ב' חכמות, כי איתא במדרש<sup data-n=\"157\">9</sup> עד שלא נברא העולם היו מים במים פי'",[["150","2","<b>צדיקים מה הם עושים . . ושטים על פני המים</b>: ע\"פ סנהדרין צב, ב: אותן שנים שעתיד הקב\"ה לחדש בהן את עולמו שנאמר ונשגב ה' לבדו ביום ההוא צדיקים מה הם עושים הקב\"ה עושה להם כנפים ושטים ע\"פ המים כו' ושמא תאמר יש להם צער ת\"ל וקוי ה' יחליפו כח יעלו אבר כנשרים ירוצו ולא ייגעו ילכו ולא ייעפו. ע\"כ. וראה ג\"כ ילקו\"ש ישעי' עה\"פ מ, לא (רמז תמז). וראה עוד על מאמרז\"ל זה בתו\"ח תולדות קס, ג. תו\"ח שמות ח\"ב שיז, ב (בהוצאת שנת תשס\"ג). ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תקכא. אוה\"ת שה\"ש ע' וא\"ו."],["151","3","<b>בראשית בשביל ישראל . . ובשביל התורה</b>: פירש\"י עה\"ת ר\"פ בראשית. [וראה המ\"מ בלקו\"ש ח\"ג ע' 755]."],["152","4","<b>ות\"י</b>: ותרגם ירושלמי. וראה הל' במאמרי אדהאמ\"צ בראשית ע' עז, ובהמ\"מ."],["153","5","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד."],["154","6","<b>בחכמה יסד ארץ</b>: משלי ג, יט."],["155","7","<b>העולם חוזר לתוהו כדאי' בגמרא</b>: שבת פח, א. וראה גם מאמרי אדהאמ\"צ דברים ח\"א ע' רפ. ח\"ג ע' תשצג. ח\"ד ע' א'שכא, וש\"נ."],["156","8","<b>חכמות בחוץ תרונה</b>: משלי א, כ. וראה זח\"א קמא, ב: חכמות בחוץ תרונה מאי חכמות אלין חכמה עילאה וחכמתא זעירא כו'. וראה גם תו\"א וארא נט, ג. יתרו ע, א. לקו\"ת בהעלותך לב, ג. עקב טו, א."],["157","9","<b>במדרש עד שלא נברא העולם היו מים במים</b>: ראה ב\"ר פ\"ה, ב. שמו\"ר רפ\"נ."]]],[2101920075,"שב' חכמות הללו היו כא' ואח\"כ נאמר<sup data-n=\"158\">10</sup> יקוו המים שנעשה הבדלה ביניהם שבחי' ח\"ת נמשכה למטה להיות כולם בחכמ' עשית וח\"ע היא למעלה חכמ' התורה אורייתא מחכמה נפקת<sup data-n=\"159\">11</sup> חכים ולא בחכמה ידיעא<sup data-n=\"160\">12</sup>, ומשה מן המים משיתיהו<sup data-n=\"161\">13</sup> חזר והמשיך חכמת התורה למטה להתלבש למטה בח\"ת והמלאכי' לא רצו בזה שתתלבש חכמה זו למטה ואמרו<sup data-n=\"162\">14</sup> מה אנוש כו', וירידה זו צורך עלי' היא.\n<b>וזהו</b> חכמות בחוץ תרונה שהעלי' הוא ע\"י השיר יוצאי'<sup data-n=\"163\">15</sup> בשיר ונמשכי' בשיר וכענין שיר<sup data-n=\"164\">16</sup> המעלות פי' מעלות מל' עליה והיינו ע\"י השיר וכידוע בענין ט\"ו שיר המעלות שאמר דוד שהיו אומרי' אותם בט\"ו מעלות<sup data-n=\"165\">17</sup> שהיו נושאי' המים מהשילוח ע\"ג המזבח ועל כל מעלה ומעלה היו הלוים משוררים כו'. וזהו חכמות בחוץ שע\"י ירידת החכמו' בבחי' חוץ למטה להיות כולם בחכמ' עשית ואח\"כ מתחברי' יחד כמו שהן קודם בריאת העולם מים במים, וגם חכמ' התורה נתלבשה בגשמיות ועי\"ז תרונה בבחי' שיר להתעלות למעלה יותר משהיו מקודם כי יש הרבה בחי' חכמה ויש בחי' שלמעלה מעלה יותר כו'.\n<b>והנה</b> צדיקי' מה הם עושים שטי' ע\"פ המים פי' שיוגבהו למעלה יותר גם מבחי' חכמת התורה כמו שתתעלה אז הנק' מים שיורדי' מגבוה כו' והיינו ע\"י שהקב\"ה עושה להם כנפים כנשרים, כי הנה כתי' כנשר<sup data-n=\"166\">18</sup> יעיר קנו כו' ישאהו על אברתו, שנושא בניו בגובה למעלה ממנו ומשימם ע\"ג כנפיו וכך הקב\"ה כביכול ישא הצדיקי' מלמעלה מעצמו כביכול והיינו למעלה מחכמת התורה וכמ\"ש דרך<sup data-n=\"167\">19</sup> הנשר בשמים ופי' שטי' כמשל המשיג בתורה ששכלו משוטט מענין לענין כו' אלא שכהיום הוא בתורה הנגלות לנו וגם בג\"ע הוא רק זיו השכינה אבל לעה\"ב יהי' משוטטי' ע\"פ החכמ' ויתפסו אותה שלכן נאמ' ת\"ח<sup data-n=\"168\">20</sup> אין להם מנוחה שנאמ'<sup data-n=\"169\">21</sup> ילכו מחיל כו'. ועפ\"י הקבלה הוא שיהי' בבחי' כתר שלמעלה מחכמה וזהו ע\"פ המים.",[["158","10","<b>יקוו המים</b>: בראשית א, ט."],["159","11","<b>אורייתא מחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ועוד."],["160","12","<b>חכים ולא בחכמה ידיעא</b>: תקו\"ז בהקדמה (יז, ב). זהר חדש יתרו לד, ד."],["161","13","<b>מן המים משיתיהו</b>: שמות ב, י. וראה גם מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תקלד. במדבר ח\"ב ע' תשטז. דברים ח\"ד ע' א'קצט. וש\"נ."],["162","14","<b>ואמרו מה אנוש</b>: תהלים ח, ה. שבת פח, ב. וראה במ\"מ בסה\"מ תרל\"ג ח\"א ע' רסח."],["163","15","<b>יוצאי' בשיר</b>: שבת נא, ב. וראה תו\"א ז, ג. קיג, ב-ג. לקו\"ת פ' פינחס עז, ג. שם פ' ברכה צח, א (בשם לקו\"א להה\"מ). ס' מאמרי אדה\"ז על מארז\"ל ע' קכ (בשם מורי זלה\"ה). וראה במ\"מ בסה\"מ תרל\"ג ח\"א ע' רסט."],["164","16","<b>שיר המעלות</b>: תהלים קכ-קלד."],["165","17","<b>שהיו אומרי' אותם בט\"ו מעלות</b>: ראה סוכה נא, ב."],["166","18","<b>כנשר יעיר קנו</b>: האזינו לב, יא."],["167","19","<b>דרך הנשר בשמים</b>: משלי ל, יט."],["168","20","<b>ת\"ח אין להם מנוחה</b>: ברכות סד, א. מו\"ק כט, א."],["169","21","<b>שנאמ' ילכו מחיל</b>: תהלים פד, ח."]]],[2101920076,"<b>(ויש</b><sup data-n=\"170\">22</sup> עוד פי' הקב\"ה עושה להם כנפים כנשרים שיהיו הם הנשרים וא\"כ הם ישאו דבר אחר למעלה מהם וגם זה אמת והדבר כמוס ובין כך ובין כך עיקר ההעלא' ע\"י הכנפים דוקא).\n<b>שמא</b> תאמר יש להם צער כו' מחמת שלא יכלו להכיל החכמ' ת\"ל יחליפו כח כו', והיינו רק באלף הז' כי אח\"כ יתחדש העולם אלא שלא יהא כאופן שעתה ולא יהי' חורבן בהמ\"ק ושעבוד מלכיות כו'.",[["170","22","<b>ויש עוד פי'</b>: ראה גם סד\"ה זה באוה\"ת בראשית (ל, ב). וראה ס' מאמרי אדהאמ\"צ בראשית ח\"א ס\"ע קנה ואילך [ועד\"ז בתו\"ח בראשית ה, ג ואילך]."]]],[2101920077,"<h3>\n<i>נוסח אחר:</i> להבין מ\"ש במדרש ע\"פ וקוי ה'</h3>\n<b>להבין</b><sup data-n=\"171\">1</sup> מ\"ש במדרש<sup data-n=\"172\">2</sup> ע\"פ וקוי ה' יחליפו כח כו' לעתיד הקב\"ה עושה כנפיים לצדיקים ושטין ע\"פ המים, יכול יש להם צער ת\"ל וקוי ה' יחליפו כח כו'. הנה כתי' יהי<sup data-n=\"173\">3</sup> רקיע בתוך המים ויהי מבדיל כו', פי' שמתחלה היו המים תחתונים מעורבים עם מים העליונים ולא היו ניכרין כ\"א בפ\"ע עד שהוצרך להבדיל בכדי שיהי' ניכר כ\"א בפ\"ע, כמ\"ש<sup data-n=\"174\">4</sup> ב\"ז ראה שבין מים העליונים למים תחתונים אין ביניהם אלא שלש אצבעות, והיינו לאחר הבדלה ממילא מוכח דקודם הבדלה היו מעורבים בתכלית לגמרי כו', וכמו\"כ יובן למעלה ג\"כ שיש מ\"ע ומים תחתונים ורקיע המבדיל ביניהם.\n<b>כי</b> הנה כתי'<sup data-n=\"175\">5</sup> חכמות בחוץ תרונה, ב' חכמות, חכ' תתאה וחכ' עילאה, ח\"ת הוא בחי' חכ' שבדיבור כמו עד\"מ בחי' חכ' שיודע איך לצרף האותיות שיובן ממנו השכל לזולתו, שמוכרח להיות ע\"פ שכל וחכ' ג\"כ שאל\"כ לא יהי' מובן כלל השכל",[["171","1","<b>להבין מ\"ש במדרש</b>: מאמר זה הוא נוסח שני מד\"ה צדיקים מה הם עושים (שנדפס לפני\"ז). וכאן הוא באריכות יותר. ונמצא בשינויים ובאריכות בס' מאמרי אדהאמ\"צ בראשית ע' עז ואילך וע' קל ואילך. ובאוה\"ת בראשית כח, ב. וראה בהנסמן עוד בד\"ה צדיקים שם."],["172","2","<b>במדרש ע\"פ וקוי ה'</b>: סנהדרין צב, ב. ילקו\"ש ישעי' עה\"פ מ, לא רמז תמז. [וראה לקו\"ש ח\"ד ע' 1236 דבשם מדרש נקראו מאחז\"ל הדורשים ומבארים את הפסוקים, גם מאחז\"ל אשר בש\"ס, וע\"ש במ\"מ]."],["173","3","<b>יהי רקיע בתוך המים</b>: בראשית א, ו."],["174","4","<b>כמ\"ש ב\"ז ראה שבין מים העליונים</b>: חגיגה טו, א: ת\"ר מעשה ברבי יהושע בן חנניה כו' אמר לו מאין ולאין בן זומא אמר לו צופה הייתי בין מים העליונים למים התחתונים ואין בין זה לזה אלא שלש אצבעות בלבד שנאמר ורוח אלקים מרחפת על פני המים כיונה שמרחפת על בניה ואינה נוגעת. וראה גם מאמרי אדהאמ\"צ במדבר ח\"ג ס\"ע רכא ואילך."],["175","5","<b>כתי' חכמות בחוץ תרונה ב' חכמות</b>: משלי א, כ. זח\"א קמא, ב."]]],[2101920078,"לזולתו אם לא ע\"פ חכמה ושכל שמתחכם האיך לצרף האותיות כו', כמו\"כ יובן למעלה ג\"כ בבחי' צירופי אותיות העליונים, יהי<sup data-n=\"176\">6</sup> אור יהי רקיע שמוכרחי' להיות ג\"כ עפ\"י בחי' חכמה כמ\"ש כולם<sup data-n=\"177\">7</sup> בחכ' עשית כו', בחכ'<sup data-n=\"178\">8</sup> יסד כו', בראשית<sup data-n=\"179\">9</sup> ת\"י בחוכמתא והוא בחי' חכ' שבדיבור העליון שע\"י נמשכו הצירופי' של עשרה מאמרות באופן הנאות שיוכל להיות ממנו בחי' ההשתלשלות, והוא בחי' חכ' דמל' דאצי' שכל בחי' הצירופי' שמהוים בי\"ע מאין ליש נמשכים ממנו כמ\"ש והלא<sup data-n=\"180\">10</sup> במאמר אחד כו' שהוא כללות כל הצירופים והמאמרות, בראשית<sup data-n=\"181\">11</sup> נמי מאמר הוא שהוא בחי' חכ' שבדיבור שכל הצירופים פרטי' היו נכללים בו מתחלה רק שאח\"כ נתחלק לע\"מ וזהו הנק' למעלה בחי' מים תחתונים. ובחי' מים עליונים הוא בחי' ח\"ע פי' היינו חכ' שבעצמותו שהוא ג\"כ בבחי' א\"ס כמ\"ש ולתבונתו<sup data-n=\"182\">12</sup> אין מספר כו' כמ\"ש לאו<sup data-n=\"183\">13</sup> דאית לך צדק ידיעא כו' ולאו מכל אלין מדות כלל, ומה שנק' חכים כו' הוא כמ\"ש אנת חכים ולא בחכ' ידיעא כו' שהוא בחי' א\"ס שהוא למעלה מבחי' התפשטות לגמרי אפי' מבחי' אצי' כו'. והנה בין מ\"ע שהוא בחי' ח\"ע למים תחתונים שהוא בחי' ח\"ת הוכרח להיות בחי' רקיע המבדיל ביניהם, שמתחלה היו ב' בחי' החכמות הנ\"ל מעורבין לגמרי היינו שבחי' ח\"ת הי' נכלל בח\"ע ולא הי' ניכר למהות בפ\"ע עד שהוצרך להיות בחי' הבדלה.\n<b>וביאור</b> הענין הוא עד\"מ ממלך שהוא חכם גדול בעצם שבחי' חכ' העצמי' של המלך כמו שהיא בפ\"ע לא שייך בה שום המשכה עדיין שהרי עדיין היא נכללת בעצמותו של המלך, אך אח\"כ כשצריך להמשך ממנה איזה פרט חכמה כמו בשביל התנהגות המלוכה אזי מוכרח להיות התעלמות בבחי' חכ' עילאה שהוא בחי' חכמתו העצמי' בכדי שיוכל לצמצם עצמותו בבחי' פרט זה של חכ' להתנהגות המלוכה. והנה בודאי מקודם שנמשך פרט זה של חכמה הי' ג\"כ נכלל בבחי' חכמתו העצמיות שהרי הוא לפי ערך עצם חכמתו זה החכ' של התנהגות המלוכה, אם עצם חכמתו כמו שהיא בעצמותו הוא בגדלות כן לפ\"ע זה הוא ג\"כ חכמתו של התנהגות המלוכה ואם הוא בקטנות כן לפ\"ע זה הוא ג\"כ חכמתו שהוא בשביל התנהגות המלוכה, ואף שמקודם לא הי' בבחי' פרט חכמה רק חכמתו העצמיו' מ\"מ בודאי הפרט הי' נכלל בהכלל כמו עד\"מ מחכם גדול שאינו מלך עדיין שלא נמשך כלל מחכמתו בשביל התנהגות המלוכה רק שחכמתו היא כלולה בעצמותו הי' נכלל בעצמות החכ' גם הפרט דהיינו התנהגות המלוכה כו'. ולמעלה הוא ג\"כ עד\"ז שבחי'",[["176","6","<b>יהי אור</b>: בראשית שם, ג. ו."],["177","7","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["178","8","<b>בחכ' יסד</b>: משלי ג, יט."],["179","9","<b>בראשית ת\"י בחוכמתא</b>: תרגום ירושלמי עה\"פ. וראה מאמרי אדהאמ\"צ בראשית ע' עז, ובהמ\"מ שם."],["180","10","<b>והלא במאמר אחד</b>: אבות פ\"ה מ\"א."],["181","11","<b>בראשית נמי מאמר הוא</b>: ר\"ה לב, א. מגילה כא, ב."],["182","12","<b>ולתבונתו אין מספר כו'</b>: תהלים קמז, ה. וראה במ\"מ בס' מאמרי אדהאמ\"צ בראשית ס\"ע עח."],["183","13","<b>לאו דאית לך צדק ידיעא כו'</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101920079,"ח\"ת הוא בחי' דבר<sup data-n=\"184\">14</sup> מלך שלטון כו' ואתה<sup data-n=\"185\">15</sup> מחי' כו' שהוא בחי' חכ' להתנהגות המלוכה שהוא בחי' עשרה מאמרות שהוא גוף הבריאה מאין ליש מחנה מיכאל כו' כמ\"ש ויאמר אלקים יהי אור כו' פי' שנמשך מבחי' מאמר החכ' צירופי' פרטיי' להתהוות האור כו' וכן בכל בחי' השתלשלו' הכל הוא נמשך מבחי' ח\"ת, ובחי' ח\"ע היא בחי' חכ' שבעצמו' אנת חכים כו'. והנה מקודם הי' בחי' ח\"ת נכלל בח\"ע ולא הי' ניכר למהות בפ\"ע עד שהוצרך להיות רקיע המפסיק ומבדיל ביניהם שהוא בחי' העלם חכמתו העצמי' כדי שיוכל להיות נמשך חכ' פרטית בחי' חכמה השייך להשתלשלות.\n<b>והנה</b> זהו ענין החילוק שבין עשרה מאמרות לעשרה דברות, שבחי' יו\"ד דברות הוא בחי' חכמתו העצמי', ובחי' ע\"מ הוא בחי' חכ' ששייך לבחי' השתלשלות ובריאה יש מאין כו'. כי' בחי' חכ' שבתורה הוא מבחי' חכמתו העצמי' כמ\"ש אורייתא<sup data-n=\"186\">16</sup> מחכמה נפקת שהוא בחי' ח\"ע, ובחי' חכ' השייך להשתלשלו' ובריאה יש מאין הי' מתחלה נכלל בח\"ע וע\"כ נמשך אח\"כ בבחי' עשרה מאמרות שהוא לפי ערך חכמתו העצמיות כנ\"ל. ורשב\"י הי' יודע כל מאמר מע\"מ מקורו ושרשו בעשרת הדברות כו'.\n<b>והנה</b> בשעת מ\"ת נעשה יחוד וחיבור ח\"ת עם ח\"ע כמו קודם ההשתלשלות רק שהוא באופן אחר והיינו שנמשך ע\"י התורה מבחי' ח\"ע לבחי' ח\"ת והתורה היא בחי' ממוצע שע\"י נתחבר ח\"ת עם ח\"ע כמ\"ש חכמות בחוץ תרונה שהוא בחי' ב' חכמות ח\"ת וח\"ע, והוא באופן אחר מכמו קודם ההשתלשלות שקודם ההשתלשלות הוא בבחי' העלאה ממטה למעלה שהתחתון עלה לגבי עליון היינו שבחי' ח\"ת הי' נכלל בבחי' ח\"ע שכל מהותו של התחתון הי' נכלל בהעליון, אבל בשעת מ\"ת הי' באופן אחר שעליון ירד לגבי תחתון היינו שבחי' ח\"ע ירד ונמשך בבחי' ח\"ת שהוא רק בחי' צמצום לפי ערך התחתון כו' והוא כמו עד\"מ מב' אנשים שזה עומד בגובה ורום וזה עומד למטה שיש ב' אופנים בהתחברותם זה אל זה או שתחתון יעלה לגבי העליון או שהעליון ירד להתחתון וד\"ל.\n<b>והנה</b> יש להבין מ\"ש במ\"א ע\"פ בראשית<sup data-n=\"187\">17</sup> בשביל התורה שנק' ראשית כמ\"ש ה'<sup data-n=\"188\">18</sup> קנני ראשית דרכו, היינו שבחי' חכ' שבתורה היא בחי' ראשית ומקור להיות בחי' דרך והמשכה להיות בחי' השתלשלות, ועוד אפשר לומר שפי' הכי בשביל שינתן התורה שנק' ראשית וכו'. אך לפי\"ז יש להבין מ\"ש בזוהר אסתכל<sup data-n=\"189\">19</sup> קוב\"ה באורייתא וברא עלמא והוא כמו עד\"מ אומן שרוצה לבנות איזה בנין שצריך מתחלה",[["184","14","<b>דבר מלך שלטון</b>: קהלת ח, ד."],["185","15","<b>ואתה מחי'</b>: נחמי' ט, ו."],["186","16","<b>אורייתא מחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א."],["187","17","<b>בראשית בשביל התורה כו'</b>: פירש\"י עה\"ת ר\"פ בראשית. וראה המ\"מ בלקו\"ש ח\"ג ע' 755."],["188","18","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["189","19","<b>אסתכל קוב\"ה באורייתא וברא עלמא</b>: זהר ח\"א קלד, סע\"א. ח\"ב קסא, ריש ע\"ב. ח\"ג קעח, א."]]],[2101920080,"לעיין בהלוח שיש בו ציורי הבנין כמ\"ש<sup data-n=\"190\">20</sup> במדרש ואהי' אצלו אמון אמון פדגוג כו' תורתו<sup data-n=\"191\">21</sup> אומנתו כו', והוא להיפך ממה שמבואר למעלה שעיקר התהוות העולמות הוא ע\"י חכ' שבדיבור כמ\"ש כולם בחכ' עשית שהוא חכ' השייך לעשי' הנ\"ל. אך מתחלה י\"ל שורש התורה הנה מבואר דאוריי' מחכ' נפקת הנה מהלשון משמע ששורש התורה הוא למעלה בחכמה רק שירד למטה ובאמת הרי התורה היא בחי' חכמתו העצמיות כמ\"ש אנוכי<sup data-n=\"192\">22</sup> מי שאנוכי כו', אך הענין שיש ב' פירושי' הא' הוא שהתורה נפקת מחכ' עילאה שהוא בחי' חכמתו העצמיי' בחי' אין האמיתי והוא ההיפך לגמרי מבחי' ח\"ת שהוא התהוות הבריאה מאין ליש, ולא הי' ביכולת להשתלשל למטה בחי' ח\"ת אם לא שהי' מתחלה בחי' ממוצע שהוא התורה ע\"כ הי' היכולת אח\"כ להתהוות בחי' ח\"ת. וזהו אסתכל באורייתא וברא עלמא שזהו בחי' ממוצע להיות בחי' ח\"ת וד\"ל. ופי' הב' הוא ע\"ד מ\"ש הנה<sup data-n=\"193\">23</sup> ה' יוצא ממקומו שהוא בחי' בירורי' שבתורה להבדיל ולרחק כל רע בשס\"ה ל\"ת כו' שהוא נמשך מבחי' חכמתו העצמיו' כמ\"ש<sup data-n=\"194\">24</sup> בחייט שחכמה הוא דין שנמשך משם כח להרחיק כל סיג ופסולת ולדחות הרע כו'. והנה אף שבחי' חכ' שהוא לברר בירורי' הוא בא ונמשך למטה בבי\"ע מ\"מ שרשו הוא הגבה למעלה מבחי' ח\"ע ששרשו הוא ממקור החכ' שהוא בחי' אין כמ\"ש והחכ'<sup data-n=\"195\">25</sup> מאין תמצא כו', והוא עד\"מ ממלך שהוא חכם בעצם שמתקן תיקונים הרבה במדינתו ע\"פ חכמתו לדחות ולהרחיק כל רע, שהכח לתיקון זה הוא בא ונמשך ממקור חכמתו שהוא פנימי' החכ', כי החכ' בעצם יש לו שיעור וקצבה כמ\"ש והחכ' מאין תמצא שהוא בחי' מציאות כו' אבל הכח לתקן תיקונים הרבה בא ונמשך מבחי' מקור החכ' שהוא דבר שאין לו שיעור וקצבה, שכל שהוא חכם ביותר יכול לתקן תיקונים הרבה ביותר, וכמו\"כ יובן בבחי' חכ' של תו' שהוא לברר בירורי' שאף שבא ונמשך למטה בבי\"ע שהוא בחי' חיצוניו' החכ' כמ\"ש נובלות<sup data-n=\"196\">26</sup> חכמה של מעלה תורה כו' מ\"מ הכח לבירורי' הוא בא ונמשך מבחי' מקור החכ' מפנימי' אין שהוא בעילוי אחר עילוי כו'. וזהו אורייתא מחכ' נפקת לחוץ בבי\"ע לברר בירורי' בבי\"ע כמ\"ש הנה ה' יוצא ממקומו. והנה זהו ענין שהי' במ\"ת שנמשך מבחי' ח\"ע לח\"ת שהיו ב' החכמות בבחי' יחוד וחיבור כמו קודם הבדלה רק שהוא ממעלה למטה כו', וע\"כ הי' קבלת התו' ע\"י משה, כי בחי' משה הוא מבחי' מ\"ה בחי' פנימי' אין כו' מבחי' פנימי' החכ' כמ\"ש כי<sup data-n=\"197\">27</sup> מן המים משיתיהו כו' שהוא הכח לבירורים, וע\"כ הי'<sup data-n=\"198\">28</sup> מכה הסלע פעמיים להוציא מימיו כי בחי' סלע הוא בחי'",[["190","20","<b>כמ\"ש במדרש ואהי' אצלו אמון אמון פדגוג</b>: ב\"ר בתחלתו. משלי ח, ל."],["191","21","<b>תורתו אומנתו</b>: שבת יא, א."],["192","22","<b>אנוכי מי שאנוכי</b>: ראה לקו\"ת פינחס פ, ב."],["193","23","<b>הנה ה' יוצא ממקומו</b>: ישעי' כו, כא. מיכה א, ג."],["194","24","<b>כמ\"ש בחייט שחכמה הוא דין</b>: פי' הר\"י חייט לס' מערכת האלקות, פ\"ד. וראה גם תו\"א בראשית ה, ד. לקו\"ת ראה לא, א. תו\"ח בראשית לא, ד, ובהמ\"מ שם."],["195","25","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["196","26","<b>נובלות חכמה של מעלה תורה</b>: ב\"ר פי\"ז, ה."],["197","27","<b>כי מן המים משיתיהו</b>: שמות ב, י. וראה בהמ\"מ למאמר שלפני\"ז."],["198","28","<b>הי' מכה הסלע פעמיים</b>: ראה חוקת כ, יא."]]],[2101920081,"חכ' רק שהי' נותן בה הכח לבירורי' ע\"י הכאה מבחי' מקור החכמה, שהוא דוקא ע\"י משה שהוא מפנימי' החכ' שמשם נמשך כח הבירור כנ\"ל.\n<b>והנה</b> הגם שנמשך מבחי' ח\"ע לח\"ת שהוא בחי' בירורי' מ\"מ הוצרך להיות ע\"י לבוש שיתלבש לפי ערך התחתון כו'. והנה לפי\"ז נראה שהיחוד והחיבור של הב' חכמות שהי' קודם הבדלה הוא במדריגה יותר נעלה מהיחוד והחיבור שבשעת מ\"ת, שהיחוד שקודם הבדלה הוא התחברות ועליות תחתון בעליון שהוא נעשה במדריגת עליון אבל היחוד שבשעת מ\"ת הוא התחברות וירידות עליון בתחתון שהוא ע\"י לבוש שמתלבש לפי ערך התחתון. אבל יש סתירה לזה ממ\"ש בשעת בריאת העולם התנה<sup data-n=\"199\">29</sup> הקב\"ה במעשה בראשית אם יקבלו ישראל את התורה מוטב וא\"ל אחזיר אתכם לתוהו ובוהו כו' דנראה שנתינת התורה הוא העיקר והוא במדריגה יותר נעלה מכמו קודם הבדלה כמ\"ש בראשי' בשביל התורה שנק' ראשית כו'.\n<b>והענין</b> יובן בהקדים תחלה מ\"ש נובלות חכמה של מעלה תורה, דנראה שהוא לגריעותא אבל האמת שהוא לטיבותא ולשבח. כי הנה בחי' חכמה שהוא לברר בירורי' הוא מבחי' חיצוני' החכ' אבל הוא נוגע לבחי' עצמיות שהוא למעלה ממקור החכ', כי הנה כתי' החכ'<sup data-n=\"200\">30</sup> תחי' בעליה, בעליה דחכמה, כי יש בחי' אבנים<sup data-n=\"201\">31</sup> שחקו מים. אבל לכאו' אינו מובן שתחי' בעליה, והוא<sup data-n=\"202\">32</sup> עד\"מ מבן מלך שאוכל תמיד על שולחן אביו המלך שאינו חשוב בעיני המלך כ\"כ מאחר שאוכל לחם שלא יגע בו בעצמו רק מעל שולחן המלך כו' כמו אשר יצא הבן למרחקים ועושה מלאכה להחיות נפשו אף שהוא בלחם צר ומים לחץ כו'. והנה מה שנמשך מכח חכמתו לעשות מלאכה הוא בחי' יציאה מעצמותו לחוץ שהוא בחי' חיצוני' חכ', שהרי חכמתו הוא מלובש בעשי' זאת, וכשעושה מלאכה ומרוויח בזה שיכול להחיות נפשו הוא מחי' כללות נפשו שהוא בחי' עצמותו שהוא למעלה מבחי' חכמתו, ונתוסף דבר חדש בחכמתו העצמי' היינו שנתעלה בחי' חכמתו העצמי' מה שלא הי' בכח חכמתו העצמי' מצד עצמו. וכמו\"כ יובן למעלה בבחי' חכ' דבירורי' הגם שהוא בחי' נובלות חכ' בחי' חיצוניו' חכ' מ\"מ לאחר תשלום הבירורים הוא נוגע לבחי' עצמותו שלא שייך שם לאמר אפי' בשם מקור לחכ' כמ\"ש כשתגיע<sup data-n=\"203\">33</sup> לאבני שיש טהור אל תאמר מים מים, שהוא בחי' שלא שייך שם לאמר אפי' בשם מקור לחכ', וזהו והחכ' תחי' בעליה שהוא בחי' חכ' דבירורי' שהוא נובלות חכ' שלמעלה בחי' חיצוניו' חכ' שמלובש למטה בבי\"ע הוא מחי' בעליה בחי' פנימי' חכ', והיינו לאחר תשלום כל הבירורי' שאז יתעלה בחי' חכמתו לבחי' שהוא למעלה בעילוי אחר עילוי עד אין סוף מבחי' מקור החכ'.",[["199","29","<b>התנה הקב\"ה במעשה בראשית</b>: שבת פח, א."],["200","30","<b>החכ' תחי' בעלי'</b>: קהלת ז, יב."],["201","31","<b>אבנים שחקו מים</b>: איוב יד, יט."],["202","32","<b>והוא עד\"מ מבן מלך</b>: ראה ס' מאמרי אדהאמ\"צ בראשית ע' קמח. במדבר ח\"ב ע' תקס. וש\"נ."],["203","33","<b>כשתגיע לאבני שיש טהור</b>: חגיגה יד, ב."]]],[2101920082,"<b>וזהו</b> ענין מ\"ש במדרש<sup data-n=\"204\">34</sup> ע\"פ אדם לעמל יולד איני יודע אם לעמל תורה אם לעמל שיחה כו' כי הנה יש ב' בחי' חכמה, חכ' שהוא שייך לדיבור היינו שהוא מדבר דברי חכמה אף שהם דברים בטלים שאין בהם שום תועלת מ\"מ יש בהם חכ' כמ\"ש שיחת<sup data-n=\"205\">35</sup> ת\"ח צריכים לימוד כו', ובחי' חכ' שהוא בשביל תיקוני' שיש בהם תועלת לדחות ולהרחיק הרע מדק שבדקות כו'. וכמו\"כ יובן בבחי' חכמות שהוא להחיות מאין ליש שנק' בשם חכ' שבדיבור הוא הנק' בשם עמל שיחה שאין בו תועלת כ\"כ כמ\"ש בזוהר<sup data-n=\"206\">36</sup> לאו אורחא דמלכא לאשתעי מילין דהדיוטא כו' שהוא בחי' ע\"מ שנק' בשם שיחה בטילה לגבי מהותו ועצמותו, אבל בחי' עמל תורה הוא בחי' חכ' שבתורה שהוא לברר בירורי' שיש בו תועלת והוא שנתעלה בחי' חכ' שירדה ונתלבשה בבי\"ע לברר בירורי' וגם בחי' עצם החכ' שלא ירדה, כי לא ירדה רק חיצוניו' חכ' כמ\"ש נובלות חכמה כו', שניהן נתעלו לבחי' עצמות שלא שייך שם לאמר אפי' בשם מקור לחכ', כי הכח לבירורי' הוא מבחי' מקור לחכ' כנ\"ל וכשנתעלה ע\"י הבירורי' נתעלה למעלה מבחי' מקור לחכ' שהוא בחי' עילוי אחר עילוי בעצמותו כו' וד\"ל.\n<b>נמצא</b> שיש כאן ג' בחי' יחודים בחי' א' הוא שבחי' ח\"ת הוא נכלל בבחי' ח\"ע כמו שהי' מתחלה קודם הבדלה, ובחי' ב' הוא שירד ונמשך מבחי' ח\"ע לח\"ת והוא ע\"י התורה שהיא בחי' ממוצע כנ\"ל שיורדת לברר בירורים, ובחי' ג' שבחי' חכ' שבתורה עם בחי' חכ' שבעצמות שניהם שוין נתעלו לבחי' עילוי אחר עילוי כו' שלא שייך שם אפי' בשם מקור לחכ' כנ\"ל. והוא הענין מ\"ש בגמרא<sup data-n=\"207\">37</sup> ע\"פ יהיב חכמתא לחכימי' כל מי שיש בו חכמה הקב\"ה נותן לו כו', פי' שיש בו חכ' היינו שיתבונן באלקות ביחו\"ע ויחו\"ת כו' ומחמת זה יתפעל הלב בחי' מדותיו בבחי' לאתהפכא כו' שהוא בחי' הבירורים כו' אף שבחי' חכמה ושכל שיתפעל הלב הוא בבחי' חיצוניו' ונובלות חכ' שלמעלה בעצמותו מ\"מ ע\"י בחי' חכ' של התפעלות הלב לאהפכא כו' נתעלה בחי' חכ' שבעצמותו למעלה מעלה למקום שלא שייך שם לאמר אפי' בשם מקור לחכ' שהוא בחי' עילוי אחר עילוי כו' ומחמת זה ניתוסף לו חכ' ושכל בבחי' חכ' שבעצמותו כנ\"ל, וזהו הקב\"ה נותן בו חכ' כו' שהוא ע\"י בחי' העליו' שנתעלה למעלה כו' וד\"ל.\n<b>וזהו</b> חכמות בחוץ תרונה ב' חכמות ח\"ת וח\"ע, והנה משמעות הלשון הוא כשהב' חכמות בחוץ אז הם תרונה אבל כשלא היו בחוץ הב' חכמות הנ\"ל לא שייך",[["204","34","<b>במדרש ע\"פ אדם לעמל יולד</b>: איוב ה, ז. סנהדרין צט, ב. [וראה במ\"מ לעיל לתחילת המאמר, שגם מאמר הגמ' נק' בשם מדרש, וראה במ\"מ בס' מאמרי אדאהמ\"צ בראשית ע' קלה]."],["205","35","<b>שיחת ת\"ח צריכים לימוד</b>: סוכה כא, א."],["206","36","<b>בזוהר לאו אורחא דמלכא לאשתעי מילין</b>: ראה זח\"ג קמט, ב."],["207","37","<b>בגמרא ע\"פ יהיב חכמתא לחכימי' כל מי שיש בו חכמה</b>: דניאל ב, כא. ראה ד\"ה יהיב חכמתא בס' מאמרי אדה\"ז כתובים ח\"ב ס\"ע קצו ואילך. [המאמר נדפס כאן מכת\"י מעתיק בלבד, ואולי מ\"ש כאן ”בגמרא\" הוא טעות המעתיק]."]]]]});
